    assert_eq!(quest_status(&game, PATH), QuestStatus::Completed);
    let coins_after_path = coins(&game);
    let xp_after_path = archer_xp(&game);

    now += 10;
    offer(&mut game, &character, LUGABOW, OATH, now);
    now += 10;
    accept(&mut game, &character, OATH, now);
