    assert_eq!(archer_xp(&game), xp_after_path + OATH_XP);
    assert_eq!(quest_status(&game, OATH), QuestStatus::Completed);
    // Completed Path is not offered again.
    assert_no_offer(
        &mut game,
        &character,
        LUGABOW,
        &mut now,
        "completed Path after Oath",
    );
}

