coin_authoring.excerpt:
//! T525: live coin authoring through the real chat path (`Gameplay::handle_in_world`).
//!
//! The gameplay content is the private opening package the collection pickup suite uses,
//! copied with the shipped `mining.json`; NPCs, coins and the collection catalogue are the
//! repository's `data/content`. The live-world folder is the overlay's home, exactly as
//! `--world` uses it.
#[path = "common/content_copy.rs"]
mod content_copy;

use osfr_tools::{
    account_store::AccountRole,
    character_store::CharacterState,
    chat,
    gameplay::{Gameplay, GameplayState, Outcome},
    npc_interaction::NpcInteractRequest,
};
use serde_json::{Value, json};
use std::{
    fs,
    path::{Path, PathBuf},
    sync::atomic::{AtomicU64, Ordering},
};

const LIVE_GUID_BASE: u64 = 131_000_000_000;
const LIVE_GUID_END: u64 = 132_000_000_000;
/// A content coin bound to Blackspore Elite (collection 288) entry 2039; it cannot be
/// reached on foot (Lxzxrus 65ec688), which is what `move` is for.
const COIN_2115: u64 = 100_000_002_115;
const COIN_2115_AT: [f32; 3] = [-2519.431, -1.902856, 1201.663];
/// An empty patch of the open world for new coins.
const HERE: [f32; 3] = [321.0, 5.0, -654.0];
static NEXT: AtomicU64 = AtomicU64::new(0);

fn bundled() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("data/content")
}

struct Fixture {
    dir: PathBuf,
    live: PathBuf,
}

impl Fixture {
    fn new() -> Self {
        let dir = std::env::temp_dir().join(format!(
            "osfr-coin-authoring-{}-{}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        let opening = std::env::var_os("OSFR_TYPE8_CONTENT")
            .map(PathBuf::from)
            .unwrap_or_else(|| {
                Path::new(env!("CARGO_MANIFEST_DIR"))
                    .join("../../../lab/references/opening-journal-text-v2/content")
            });
        content_copy::copy_tree(&opening, &dir);
        fs::copy(bundled().join("mining.json"), dir.join("mining.json")).unwrap();
        let live = dir.join("live");
        fs::create_dir_all(&live).unwrap();
        Self { dir, live }
    }

    /// A session with the live-world layer already applied, like the gateway's login.
    fn load(&self, state: Option<GameplayState>) -> Gameplay {
        let mut game = Gameplay::load(&self.dir, state).unwrap();
        game.set_world_dir(Some(self.live.clone())).unwrap();
        game
    }

    fn admin(&self) -> Gameplay {
        let mut game = self.load(None);
        game.set_role_commands(true);
        game.set_role(AccountRole::Admin);
        game
    }

    fn with_role(&self, role: AccountRole) -> Gameplay {
        let mut game = self.load(None);
        game.set_role_commands(true);
        game.set_role(role);
        game
    }

    fn edits_bytes(&self) -> Option<Vec<u8>> {
        fs::read(self.live.join("collection_coin_edits.json")).ok()
    }

    fn rows(&self) -> Vec<Value> {
        self.edits_bytes()
            .map(|bytes| serde_json::from_slice::<Value>(&bytes).unwrap()["records"].clone())
            .and_then(|records| records.as_array().cloned())
            .unwrap_or_default()
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let overlay = self.live.join("collection_coin_edits.json");
        if overlay.is_file() {
            let mut permissions = fs::metadata(&overlay).unwrap().permissions();
            permissions.set_readonly(false);
            let _ = fs::set_permissions(&overlay, permissions);
        }
        let _ = fs::remove_dir_all(&self.dir);
    }
}

fn at(position: [f32; 3]) -> CharacterState {
    CharacterState {
        guid: 1,
        zone_id: 0,
        position,
        rotation: [1.0, 0.0, 0.0],
    }
}

fn realm(game: &mut Gameplay, line: &str, who: &CharacterState) -> Outcome {
    game.handle_in_world(&chat::local_request(line), who, 1_000)
        .unwrap()
}

fn said(out: &Outcome) -> String {
    let text: String = out
        .replies
        .iter()
        .map(|packet| String::from_utf8_lossy(packet))
        .collect();
    text
}

fn click(game: &mut Gameplay, target: u64, who: &CharacterState) -> Outcome {
    let request = NpcInteractRequest {
        target,
        trailing_flag: false,
    };
    game.handle_in_world(&request.encode(), who, 1_000).unwrap()
}

/// 35/2 AddNpc: the actor guid follows the header (reader `0x00921a10`).
fn added(packets: &[Vec<u8>], guid: u64) -> bool {
    packets
        .iter()
        .any(|p| p.starts_with(&[35, 0, 2, 0]) && p.get(4..12) == Some(&guid.to_le_bytes()[..]))
}

/// 35/3: a u16 count, then the guid (reader `0x008d69f0`).
fn removed(packets: &[Vec<u8>], guid: u64) -> bool {
    packets
        .iter()
        .any(|p| p.starts_with(&[35, 0, 3, 0]) && p.get(6..14) == Some(&guid.to_le_bytes()[..]))
}

fn ledger_holds(game: &Gameplay, entry: i32) -> bool {
    game.state()
        .progression_extras
        .is_some_and(|extras| extras.collections.is_collected(entry))
}

/// What a refusal must leave alone: the save, the visibility revision and both files.
#[derive(Debug, PartialEq)]
struct Snapshot {
    state: GameplayState,
    revision: u64,
    coins: Vec<u8>,
    edits: Option<Vec<u8>>,
    placements: Option<Vec<u8>>,
}

fn snapshot(game: &Gameplay, fixture: &Fixture) -> Snapshot {
    Snapshot {
        state: game.state(),
        revision: game.npc_visibility_revision(),
        coins: fs::read(bundled().join("collection_coins.json")).unwrap(),
        edits: fixture.edits_bytes(),
        placements: fs::read(fixture.live.join("npc_placements.json")).ok(),
    }
}

fn single_row(fixture: &Fixture) -> Value {
    let rows = fixture.rows();
    assert_eq!(rows.len(), 1, "{rows:?}");
    rows.into_iter().next().unwrap()
}

#[test]
fn place_binds_1950_and_a_reload_can_collect_it() {
    let fixture = Fixture::new();
    let mut game = fixture.admin();
    let who = at(HERE);
    game.update_npc_visibility(&who).unwrap();
    let out = realm(&mut game, "realm coin place 1950", &who);
    assert!(said(&out).contains("Placed coin"), "{}", said(&out));

    let row = single_row(&fixture);
    let guid = row["spawn_guid"].as_u64().unwrap();
    assert!(
        (LIVE_GUID_BASE..LIVE_GUID_END).contains(&guid),
        "{guid} is outside the live band"
    );
    assert_eq!(row["entry_id"], json!(1950));
    assert_eq!(row["collection_id"], json!(265));
    assert_eq!(row["tier"], "rare");
    assert_eq!(
        row["model_id"],
        json!(818),
        "the model collection 265 coins use"
    );
    assert_eq!(row["name_string_id"], json!(386_170));
    assert_eq!(row["pairing"], "live");
    assert_eq!(row["source"]["kind"], "reconstructed");
    assert_eq!(row["source"]["recorded_ms"], json!(1_000));
    assert_eq!(row["source"]["character_guid"], json!(1));
    assert!(row["replaces"].is_null(), "a fresh entry replaces nothing");
    assert_eq!(row["position"][0].as_f64().unwrap(), HERE[0] as f64);
    assert_eq!(row["position"][1].as_f64().unwrap(), HERE[1] as f64);
    assert_eq!(row["position"][2].as_f64().unwrap(), HERE[2] as f64);
    assert!(added(&out.replies, guid), "the acting session sees it");

    // A new session merges the overlay from the live folder and can collect it.
    let mut reloaded = fixture.load(Some(game.state()));
    let who = at(HERE);
    assert!(added(&reloaded.update_npc_visibility(&who).unwrap(), guid));
    let out = click(&mut reloaded, guid, &who);
    assert!(out.changed);
    assert!(
        out.replies[0].starts_with(&[38, 0, 10, 0]),
        "38/10 AddEntry"
    );
    assert!(ledger_holds(&reloaded, 1950));
}

#[test]
fn move_2115_repoints_2039_and_hides_the_old_guid() {
    let fixture = Fixture::new();
    let mut game = fixture.admin();
    let who = at(HERE);
    game.update_npc_visibility(&who).unwrap();
    let out = realm(&mut game, "realm coin move 100000002115", &who);
    assert!(
        said(&out).contains("Moved coin 100000002115"),
        "{}",
        said(&out)
    );

    let row = single_row(&fixture);
    let new = row["spawn_guid"].as_u64().unwrap();
    assert_eq!(row["entry_id"], json!(2039));
    assert_eq!(row["collection_id"], json!(288));
    assert_eq!(row["tier"], "elite");
    assert_eq!(row["model_id"], json!(947));
    assert_eq!(row["name_string_id"], json!(4_412));
    assert_eq!(row["replaces"], json!(COIN_2115));
    assert!(added(&out.replies, new));

    // The old content coin is hidden for everyone; only the new coin ticks entry 2039.
    let old_spot = at(COIN_2115_AT);
    assert!(!added(
        &game.update_npc_visibility(&old_spot).unwrap(),
        COIN_2115
    ));
    let old_click = click(&mut game, COIN_2115, &old_spot);
    assert!(!old_click.changed);
    assert!(
        old_click
            .replies
            .iter()
            .all(|p| !p.starts_with(&[38, 0, 10, 0])),
        "a hidden content coin records nothing"
    );

    let mut reloaded = fixture.load(Some(game.state()));

coin_shop.excerpt:
#[path = "common/resale.rs"]
mod resale;

use osfr_tools::{
    coin_shop::{self, CoinShop, StoreCatalogue},
    inventory::{Inventory, InventoryState},
    soe::{self, Packet, RELIABLE_DATA, ReliableReceiver},
    station_cash,
};
use resale::resale;
use std::path::{Path, PathBuf};

fn inventory_content() -> PathBuf {
    std::env::var_os("OSFR_COIN_SHOP_CONTENT")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../lab/references/rust-gameplay")
        })
}

fn catalogue_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("data/content/stores.json")
}

fn inventory_with_coins(directory: &Path, coins: u32) -> Inventory {
    let loaded = Inventory::load(directory, None).expect("prepared item content loads");
    let mut state = loaded.state().clone();
    state.coins = coins;
    Inventory::load(directory, Some(state)).expect("coin balance is valid")
}

fn shop(directory: &Path, inventory: Inventory, capacity: usize) -> CoinShop {
    let catalogue = StoreCatalogue::load(&catalogue_path()).expect("store catalogue loads");
    CoinShop::new(
        directory,
        inventory,
        catalogue,
        capacity,
        None,
        station_cash::Wallet::default(),
    )
    .expect("shop state loads")
}

fn count_definition(state: &InventoryState, definition_id: i32) -> u32 {
    state
        .items
        .iter()
        .filter(|item| item.definition_id == definition_id)
        .map(|item| item.count)
        .sum()
}

fn merchant_status(result: &coin_shop::CoinShopOutcome) -> u32 {
    let packet = result.replies.last().expect("vendor reply exists");
    assert_eq!(packet.len(), 56);
    assert_eq!(&packet[..4], &[66, 0, 44, 0]);
    u32::from_le_bytes(packet[48..52].try_into().unwrap())
}

/// T362 kept this id and changed the body. The native 165/4 writer (`00c75ed0`) has no
/// per-request id: its context dword is the 165/10 record scalar (`00cf10d0`), the same for every
/// buy from one open shop, so the shop keeps no replay cache. A retry is a retransmitted reliable
/// packet, which the gateway's SOE receiver drops before the shop sees it. The client's next
/// 165/4 (a new sequence) is the player buying again, and each buy pays the server price.
#[test]
fn buy_debits_exact_cost_and_retry_is_idempotent() {
    let directory = inventory_content();
    let mut shop = shop(
        &directory,
        inventory_with_coins(&directory, 100),
        usize::MAX,
    );
    let original_count = count_definition(shop.inventory().state(), 8);

    let mut request = vec![165, 0, 4, 0];
    request.extend(0u64.to_le_bytes());
    request.extend(71001u32.to_le_bytes());
    request.extend(8i32.to_le_bytes());
    request.extend(0i32.to_le_bytes()); // tint
    request.extend(1u32.to_le_bytes()); // quantity (client writer 0x00c75ed0)
    // The gateway's session receiver limits (`osfr-gateway.rs`).
    let mut receiver =
        ReliableReceiver::new(0, 1024, soe::MAX_LOGICAL_MESSAGE, 2 * 1024 * 1024).unwrap();
    // The first send, its retransmission, then the player's second buy.
    for (sequence, bought) in [(0u16, 1u32), (0, 1), (1, 2)] {
        let packet = Packet {
            opcode: RELIABLE_DATA,
            payload: [&sequence.to_be_bytes()[..], &request].concat(),
        };
        for message in receiver.receive(&packet).unwrap().messages {
            let result = shop.handle(&message).unwrap();
            assert_eq!(result.result_code, coin_shop::RESULT_SUCCESS);
            assert!(result.changed);
        }
        assert_eq!(shop.inventory().state().coins, 100 - 15 * bought);
        assert_eq!(
            count_definition(shop.inventory().state(), 8),
            original_count + bought
        );
    }
}

#[test]
fn member_purchase_uses_catalogued_discounted_price() {
    let directory = inventory_content();
    let mut shop = shop(
        &directory,
        inventory_with_coins(&directory, 100),
        usize::MAX,
    );
    shop.set_member_status(true);

    let result = shop.buy(71005, 8, 1).unwrap();

    assert_eq!(result.result_code, coin_shop::RESULT_SUCCESS);
    assert_eq!(shop.inventory().state().coins, 87);
}

#[test]
fn insufficient_coins_returns_client_result_without_mutation() {
    let directory = inventory_content();
    let mut shop = shop(&directory, inventory_with_coins(&directory, 5), usize::MAX);
    let before = shop.inventory().state().clone();

    let result = shop.buy(71002, 8, 1).unwrap();

    assert_eq!(result.result_code, coin_shop::RESULT_INSUFFICIENT_COINS);
    assert!(!result.changed);
    assert_eq!(shop.inventory().state(), &before);
}

#[test]
fn full_bag_returns_service_result_without_mutation() {
    let directory = inventory_content();
    let loaded = Inventory::load(&directory, None).expect("prepared item content loads");
    let mut state = loaded.state().clone();
    state.coins = 100;
    state.items.clear();
    for equipped in &mut state.equipment {
        equipped.item_id = 0;
    }
    let inventory = Inventory::load(&directory, Some(state)).expect("empty bag is valid");
    let mut shop = shop(&directory, inventory, 0);
    let before = shop.inventory().state().clone();

    let result = shop.buy(71003, 8, 1).unwrap();

    assert_eq!(result.result_code, coin_shop::RESULT_SERVICE_UNAVAILABLE);
    assert!(!result.changed);
    assert_eq!(shop.inventory().state(), &before);
}

#[test]
fn unlisted_item_returns_invalid_item_without_mutation() {
    let directory = inventory_content();
    let mut shop = shop(
        &directory,
        inventory_with_coins(&directory, 100),
        usize::MAX,
    );
    let before = shop.inventory().state().clone();

    let result = shop.buy(71004, i32::MAX, 1).unwrap();

    assert_eq!(result.result_code, coin_shop::RESULT_INVALID_ITEM);
    assert!(!result.changed);
    assert_eq!(shop.inventory().state(), &before);
}

#[test]
fn sell_then_buy_back_restores_item_and_coin_balance() {
    let directory = inventory_content();
    let mut inventory = inventory_with_coins(&directory, 100);
    let mut state = inventory.state().clone();
    state.items.clear();
    for equipped in &mut state.equipment {
        equipped.item_id = 0;
    }
    inventory = Inventory::load(&directory, Some(state)).expect("empty inventory is valid");
    inventory.grant(0, 8, 1).expect("test item grant succeeds");
    let item_instance_id = inventory
        .state()
        .items
        .iter()
        .find(|item| item.definition_id == 8)
        .expect("catalogued item is owned")
        .id;
    let mut shop = shop(&directory, inventory, usize::MAX);

    let mut sell_request = vec![165, 0, 5, 0];
    sell_request.extend(0u64.to_le_bytes());
    sell_request.extend(item_instance_id.to_le_bytes());
    sell_request.extend(1u32.to_le_bytes());
    let sold = shop.handle(&sell_request).unwrap();
    assert_eq!(sold.result_code, coin_shop::RESULT_SUCCESS);
    assert_eq!(shop.inventory().state().coins, 100 + resale(8));
    assert_eq!(count_definition(shop.inventory().state(), 8), 0);

    let mut buy_back_request = vec![165, 0, 12, 0];
    buy_back_request.extend(sold.transaction_id.to_le_bytes());
    buy_back_request.extend(0u32.to_le_bytes());
    let bought_back = shop.handle(&buy_back_request).unwrap();
    assert_eq!(bought_back.result_code, coin_shop::RESULT_SUCCESS);
    assert_eq!(shop.inventory().state().coins, 100);
    assert_eq!(count_definition(shop.inventory().state(), 8), 1);
}

/// One 66/3 order built exactly as the client serializer `00b3fc60`/`00b3af80` writes it.
fn order_for(item_id: i32) -> Vec<u8> {
    fn text(bytes: &mut Vec<u8>, value: &str) {
        bytes.extend((value.len() as i32).to_le_bytes());
        bytes.extend_from_slice(value.as_bytes());
    }
