fn sell_packet(merchant: u64, instance: i32, quantity: u32) -> Vec<u8> {
    let mut packet = vec![165, 0, 5, 0];
    packet.extend(merchant.to_le_bytes());
    packet.extend(instance.to_le_bytes());
    packet.extend(quantity.to_le_bytes());
