fn changed_stacks(before: &InventoryState, after: &InventoryState) -> Vec<i32> {
    let ids: BTreeSet<i32> = before
        .items
        .iter()
        .chain(&after.items)
        .map(|item| item.id)
        .collect();
    ids.into_iter()
        .filter(|id| {
            before.items.iter().find(|item| item.id == *id)
                != after.items.iter().find(|item| item.id == *id)
        })
        .collect()
}

