        template[33..37].copy_from_slice(&1_f32.to_le_bytes());
        template[49..53].copy_from_slice(&1_f32.to_le_bytes());
        template[61..65].copy_from_slice(&1_f32.to_le_bytes());
        template[133..137].copy_from_slice(&100_i32.to_le_bytes());
        template[224] = 1;
