        let config = serde_json::json!({"schema_version":1,"template_file":"npc.bin",
            "template_sha256":format!("{:x}",Sha256::digest(&template)),
            "npc":{"definition_id":0,"model_id":3311,"name":"Test Guide","texture_alias":"","position":[0.0,0.0,0.0]},
