    }
}
fn request(guid: u64) -> Vec<u8> {
    let mut bytes = vec![26, 0, 8, 0];
    bytes.extend(guid.to_le_bytes());
    bytes.push(0);
    bytes
}
fn select(guid: u64, id: i32) -> Vec<u8> {
