    bytes.extend(guid.to_le_bytes());
    bytes.extend(id.to_le_bytes());
    bytes
}
fn ability(guid: u64) -> Vec<u8> {
    let mut bytes = vec![36, 0, 10, 0];
    for value in [4895_i32, 0, 0] {
