consumable_effects_route.excerpt:
//! T474: the consumable effect stack through the real `Gameplay` route: applied with
//! `apply_consumable_effect`, expired by `Gameplay::tick`, cancelled by the client's 35/33
//! (`handle_in_world`), resent after a scene load, and never saved.
use osfr_tools::{
    character_store::CharacterState,
    consumable_effects::{Kind, Refusal, Spec},
    gameplay::{Gameplay, Outcome},
};
use std::path::PathBuf;

const GUID: u64 = 1;
const MIN: u64 = 60_000;

fn reference() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../lab/references/rust-opening-cooking-original-assets")
}
fn who() -> CharacterState {
    CharacterState {
        guid: GUID,
        zone_id: 0,
        position: [-440.0, 0.8, 1292.0],
        rotation: [1.0, 0.0, 0.0],
    }
}
fn game() -> Gameplay {
    Gameplay::load(&reference(), None).unwrap()
}
/// A test-only transform: no catalogue entry is needed, the route only sees the `Spec`.
fn transform(duration_ms: u64) -> Spec {
    Spec {
        kind: Kind::Transform {
            model_id: 4321,
            poof_effect_id: 77,
        },
        duration_ms,
        icon_id: 3843,
        name_id: 100,
    }
}
fn heads(packets: &[Vec<u8>]) -> Vec<(u16, u16)> {
    packets
        .iter()
        .map(|p| {
            (
                u16::from_le_bytes([p[0], p[1]]),
                u16::from_le_bytes([p[2], p[3]]),
            )
        })
        .collect()
}
/// The replies that belong to the effect stack (the world tick may add unrelated ones).
fn effect_heads(out: &Outcome) -> Vec<(u16, u16)> {
    heads(&out.replies)
        .into_iter()
        .filter(|h| [(35, 14), (35, 15), (35, 16), (38, 16), (38, 17)].contains(h))
        .collect()
}
/// 35/33: `u16 35, u16 33, i32 id` (client sender `00934740`, serializer `00913b80`).
fn strip(id: i32) -> Vec<u8> {
    [vec![35, 0, 33, 0], id.to_le_bytes().to_vec()].concat()
}
/// The buff id the 38/16 row carries (`i32` tag id right after the header).
fn buff_id(out: &Outcome) -> i32 {
    let row = out.replies.iter().find(|p| p.starts_with(&[38, 0, 16, 0]));
    i32::from_le_bytes(row.unwrap()[4..8].try_into().unwrap())
}

#[test]
fn a_transform_goes_to_the_owner_with_its_row_and_to_neighbours_without_it() {
    let mut game = game();
    let out = game
        .apply_consumable_effect(GUID, who().position, transform(30 * MIN), 1_000)
        .unwrap();
    assert_eq!(heads(&out.replies), [(35, 16), (35, 14), (38, 16)]);
    assert_eq!(heads(&out.nearby), [(35, 16), (35, 14)]);
    assert!(out.changed, "a visible change refreshes the AddPc snapshot");
}

#[test]
fn a_refused_spec_sends_and_changes_nothing() {
    let mut game = game();
    let before = game.consumable_effects().clone();
    assert!(matches!(
        game.apply_consumable_effect(GUID, who().position, transform(0), 0),
        Err(Refusal::Duration)
    ));
    assert_eq!(*game.consumable_effects(), before);
}

#[test]
fn expiry_is_sent_once_by_the_tick() {
    let mut game = game();
    game.apply_consumable_effect(GUID, who().position, transform(MIN), 0)
        .unwrap();
    let early = game.tick(&who(), MIN - 1).unwrap();
    assert!(effect_heads(&early).is_empty() && early.nearby.is_empty());
    let out = game.tick(&who(), MIN).unwrap();
    assert_eq!(effect_heads(&out), [(35, 15), (38, 17)]);
    assert_eq!(heads(&out.nearby), [(35, 15)]);
    assert!(out.changed);
    let again = game.tick(&who(), MIN + 1).unwrap();
    assert!(effect_heads(&again).is_empty() && again.nearby.is_empty() && !again.changed);
}

#[test]
fn the_buff_bar_cancel_ends_only_an_owned_effect() {
    let mut game = game();
    let applied = game
        .apply_consumable_effect(GUID, who().position, transform(30 * MIN), 0)
        .unwrap();
    let id = buff_id(&applied);

    // Another id, a job or power-up tag id and a negative id: nothing is sent, nothing changes.
    let before = game.consumable_effects().clone();
    for other in [id + 1, 2, 15_255, -1, 0] {
        let out = game.handle_in_world(&strip(other), &who(), 5_000).unwrap();
        assert!(out.replies.is_empty() && out.nearby.is_empty() && !out.changed);
        assert_eq!(*game.consumable_effects(), before);
    }

    // The owned id reverts the model and drops the row, for the owner and for neighbours.
    let out = game.handle_in_world(&strip(id), &who(), 5_000).unwrap();
    assert_eq!(effect_heads(&out), [(35, 15), (38, 17)]);
    assert_eq!(heads(&out.nearby), [(35, 15)]);
    assert!(out.changed);

    // A repeat is the unknown-id case; so is the expiry that would have come later.
    let repeat = game.handle_in_world(&strip(id), &who(), 6_000).unwrap();
    assert!(repeat.replies.is_empty() && repeat.nearby.is_empty());
    assert!(effect_heads(&game.tick(&who(), 30 * MIN).unwrap()).is_empty());
}

#[test]
fn a_malformed_cancel_is_an_error_that_changes_nothing() {
    let mut game = game();
    game.apply_consumable_effect(GUID, who().position, transform(30 * MIN), 0)
        .unwrap();
    let before = game.consumable_effects().clone();
    let saved = serde_json::to_string(&game.state()).unwrap();
    for bad in [
        vec![35, 0, 33, 0],
        vec![35, 0, 33, 0, 1, 0, 0],
        [strip(1_000_000_000), vec![0]].concat(),
        [strip(1_000_000_000), vec![0; 4]].concat(),
    ] {
        assert!(game.handle_in_world(&bad, &who(), 1).is_err(), "{bad:?}");
        assert_eq!(*game.consumable_effects(), before);
    }
    assert_eq!(serde_json::to_string(&game.state()).unwrap(), saved);
}

#[test]
fn the_stack_is_session_only_and_follows_a_scene_load() {
    let mut game = game();
    let saved = serde_json::to_string(&game.state()).unwrap();
    game.apply_consumable_effect(GUID, who().position, transform(30 * MIN), 0)
        .unwrap();
    assert_eq!(serde_json::to_string(&game.state()).unwrap(), saved);

    // A scene load rebuilds the client's own actor: model and buff row come again, remaining time.
    let loaded = game.initialize_world(&who(), 10 * MIN).unwrap();
    let heads = heads(&loaded.replies);
    assert!(heads.contains(&(35, 14)) && heads.contains(&(38, 16)));

    // A relog starts with nothing and sends nothing.
    let mut relog = Gameplay::load(&reference(), Some(game.state())).unwrap();
    let login = relog.initialize_world(&who(), 0).unwrap();
    assert!(effect_heads(&login).is_empty());
    assert_eq!(
        *relog.consumable_effects(),
        *Gameplay::load(&reference(), None)
            .unwrap()
            .consumable_effects()
    );
}

consumables_content.excerpt:
//! T511: the shipped `data/content/consumables.json` through the real loaders.
//!
//! The file is generated offline by `scripts/build_consumables.py` from the pinned
//! Sanctuary/Legacy item definitions and the client asset tables. These checks pin the
//! loader contract (the production `ItemBar::load` path), the two potion rows, the two
//! named rows the brief calls out, the exclusions and every row's provenance.
use osfr_tools::item_bar::{EffectKind, Effects, ItemBar};
use std::path::PathBuf;

const POTIONS: [i32; 2] = [2173, 11002];
/// Every definition the content rules exclude. `900000..` (the OSFR synthetic abilities) is
/// checked separately.
const EXCLUDED: [&[i32]; 4] = [
    // Cakes
    &[
        7966, 7967, 7968, 7969, 7970, 7971, 7972, 7973, 7974, 17597, 69819, 48100,
    ],
    // RandomTransformFoods
    &[69828, 48104],
    // Boomboxes
    &[
        878, 1180, 1913, 8185, 35759, 48244, 56774, 69825, 76927, 76928, 76930, 76933, 76935,
        77329, 76934, 900059, 900060, 900061, 76877, 900063, 78075,
    ],
    // PartyFavors
    &[62516, 67961, 67962, 67963, 67964, 68909, 68910, 68911],
];

fn content() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("data/content")
}

#[test]
fn the_shipped_rows_load_through_the_real_loader_with_their_client_checked_values() {
    let directory = content();
    // The production entry point the game uses at bind; it calls `Effects::load` itself.
    ItemBar::load(&directory, Default::default(), None).expect("the shipped rows load");
    let effects = Effects::load(&directory).expect("consumables.json parses");
    let rows = effects.rows();
    assert!(
        (90..=100).contains(&rows.len()),
        "{} consumable rows, outside the content bounds",
        rows.len()
    );

    // Rule 1: the built-in potion rows come first and keep their values.
    assert_eq!(
        rows[..2]
            .iter()
            .map(|row| row.definition)
            .collect::<Vec<_>>(),
        POTIONS
    );
    for definition in POTIONS {
        let row = effects.get(definition).expect("a potion row");
        assert!(matches!(row.effect, EffectKind::Heal { percent: 35 }));
        assert_eq!(row.cooldown_ms, 10_000);
        assert!(row.single_use);
        assert_eq!((row.name_id, row.description_id), (422909, 422916));
    }
    // Rule 6: every generated row is sorted by definition id.
    assert!(
        rows[2..]
            .windows(2)
            .all(|pair| pair[0].definition < pair[1].definition)
    );

    // 2982 Electric Veal Meat: the brief's aura row.
    let veal = effects.get(2982).expect("Electric Veal Meat");
    assert!(matches!(
        veal.effect,
        EffectKind::Aura {
            composite_effect_id: 5030,
            duration_ms: 1_800_000,
            delay_ms: 0,
            icon_id: 3843,
        }
    ));
    assert_eq!((veal.name_id, veal.description_id), (277, 2707));
    assert_eq!(veal.cooldown_ms, 1_800_000);
    assert!(veal.single_use);

    // 4042 Bark Berries: the brief's transformation treat.
    let berries = effects.get(4042).expect("Bark Berries");
    assert!(matches!(
        berries.effect,
        EffectKind::Transform {
            model_id: 169,
            poof_effect_id: 21,
            duration_ms: 1_800_000,
            icon_id: 3843,
        }
    ));
    assert_eq!((berries.name_id, berries.description_id), (1201, 2772));
    assert_eq!(berries.cooldown_ms, 1_800_000);

    // The retained joins: 23 food items and 69 transformation items after the exclusions.
    let (mut heals, mut auras, mut transforms) = (0, 0, 0);
    for row in rows {
        match row.effect {
            EffectKind::Heal { .. } => heals += 1,
            EffectKind::Aura { .. } => auras += 1,
            EffectKind::Transform { .. } => transforms += 1,
            EffectKind::Scale { .. } => {}
        }
    }
    assert_eq!(heals, 2);
    assert_eq!(auras, 23);
    assert_eq!(transforms, 69);

    // No excluded item and no OSFR synthetic ability id is present.
    for group in EXCLUDED {
        for definition in group {
            assert!(
                effects.get(*definition).is_none(),
                "excluded definition {definition} is present"
            );
        }
    }
    assert!(rows.iter().all(|row| row.definition < 900_000));

    // Rule 7: every row names the pinned data it came from; the sampled rows also name the
    // client asset the effect resolves to.
    for row in rows {
        assert!(
            row.source.contains("10f129e"),
            "definition {} has no Sanctuary provenance",
            row.definition
        );
        assert!(
            row.source.contains("Legacy@9e08202"),
            "definition {} has no Legacy cross-check",
            row.definition
        );
    }
    assert!(veal.source.contains("PFX_barrier-electricity_blue_loop"));
    assert!(berries.source.contains("dog_large_floppy.adr"));
    assert!(
        effects
            .get(36)
            .expect("Can of Beans")
            .source
            .contains("EffectDelayMs 300")
    );
}

