use osfr_tools::content;

use content::{ContentDb, ContentError};
use serde_json::Value;
use std::{
    fs,
    path::{Path, PathBuf},
    sync::atomic::{AtomicU64, Ordering},
    time::{SystemTime, UNIX_EPOCH},
};

static NEXT_FIXTURE: AtomicU64 = AtomicU64::new(0);

struct FixtureDir(PathBuf);

impl Drop for FixtureDir {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn fixture_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/content")
}

fn copied_fixture() -> FixtureDir {
    let stamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    let target = std::env::temp_dir().join(format!(
        "osfr-content-{}-{stamp}-{}",
        std::process::id(),
        NEXT_FIXTURE.fetch_add(1, Ordering::Relaxed)
    ));
    fs::create_dir(&target).unwrap();
    for entry in fs::read_dir(fixture_dir()).unwrap() {
        let entry = entry.unwrap();
        fs::copy(entry.path(), target.join(entry.file_name())).unwrap();
    }
    FixtureDir(target)
}

fn edit_json(dir: &Path, file: &str, edit: impl FnOnce(&mut Value)) {
    let path = dir.join(file);
    let mut value: Value = serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();
    edit(&mut value);
    fs::write(path, serde_json::to_vec_pretty(&value).unwrap()).unwrap();
}

#[test]
fn validated_content_set_loads() {
    let db = ContentDb::load(fixture_dir()).unwrap();

    assert_eq!(db.zones.len(), 1);
    assert_eq!(db.npcs.len(), 1);
    assert_eq!(db.pois.len(), 1);
    assert_eq!(db.items.len(), 1);
    assert_eq!(db.quests.len(), 1);
    assert_eq!(db.jobs.len(), 1);
    assert_eq!(db.dungeons.len(), 1);
    assert_eq!(db.minigames.len(), 1);
}

#[test]
fn duplicate_ids_fail_with_the_dataset_and_id() {
    let fixture = copied_fixture();
    edit_json(&fixture.0, "zones.json", |value| {
        let row = value["records"][0].clone();
        value["records"].as_array_mut().unwrap().push(row);
    });

    match ContentDb::load(&fixture.0).unwrap_err() {
        ContentError::DuplicateId { kind, id } => {
            assert_eq!(kind, "zone");
            assert_eq!(id, "7");
        }
        error => panic!("expected duplicate zone id, got {error}"),
    }
}

#[test]
fn dangling_references_fail_with_the_owner_field_and_target() {
    let fixture = copied_fixture();
    edit_json(&fixture.0, "quests.json", |value| {
        value["records"][0]["giver_npc_id"] = 999999.into();
    });

    match ContentDb::load(&fixture.0).unwrap_err() {
        ContentError::DanglingReference {
            owner,
            field,
            target,
        } => {
            assert_eq!(owner, "quest 101");
            assert_eq!(field, "giver_npc_id");
            assert_eq!(target, "999999");
        }
        error => panic!("expected dangling quest giver, got {error}"),
    }
}

#[test]
fn missing_reward_items_fail_with_the_grant_field_and_target() {
    let fixture = copied_fixture();
    edit_json(&fixture.0, "quests.json", |value| {
        value["records"][0]["rewards"][0]["items"][0]["definition_id"] = (-999).into();
    });

    match ContentDb::load(&fixture.0).unwrap_err() {
        ContentError::DanglingReference {
            owner,
            field,
            target,
        } => {
            assert_eq!(owner, "quest 101");
            assert_eq!(field, "reward.items.definition_id");
            assert_eq!(target, "-999");
        }
        error => panic!("expected dangling reward item, got {error}"),
    }
}

#[test]
fn missing_zone_references_fail_with_the_owner_field_and_target() {
    let fixture = copied_fixture();
    edit_json(&fixture.0, "npcs.json", |value| {
        value["records"][0]["zone_id"] = 999.into();
    });

    match ContentDb::load(&fixture.0).unwrap_err() {
        ContentError::DanglingReference {
            owner,
            field,
            target,
        } => {
            assert_eq!(owner, "npc 2732686529148769137");
            assert_eq!(field, "zone_id");
            assert_eq!(target, "999");
        }
        error => panic!("expected dangling NPC zone, got {error}"),
    }
}

#[test]
fn records_without_provenance_fail_with_the_file_and_index() {
    let fixture = copied_fixture();
    edit_json(&fixture.0, "items.json", |value| {
        value["records"][0]
            .as_object_mut()
            .unwrap()
            .remove("source");
    });

    match ContentDb::load(&fixture.0).unwrap_err() {
        ContentError::MissingProvenance { file, record_index } => {
            assert_eq!(file, "items.json");
            assert_eq!(record_index, 0);
        }
        error => panic!("expected missing provenance, got {error}"),
    }
}

#[test]
fn unsupported_schema_versions_fail_precisely() {
    let fixture = copied_fixture();
    edit_json(&fixture.0, "zones.json", |value| {
        value["schema_version"] = 2.into();
    });

    assert!(matches!(
        ContentDb::load(&fixture.0),
        Err(ContentError::UnsupportedSchemaVersion {
            file,
            found: 2,
            expected: 1
        }) if file == "zones.json"
    ));
}

#[test]
fn unknown_record_fields_fail_with_the_file_name() {
    let fixture = copied_fixture();
    edit_json(&fixture.0, "items.json", |value| {
        value["records"][0]["nmae_string_id"] = 123.into();
    });

    match ContentDb::load(&fixture.0).unwrap_err() {
        ContentError::InvalidJson { file, message } => {
            assert_eq!(file, "items.json");
            assert!(message.contains("nmae_string_id"));
        }
        error => panic!("expected unknown-field error, got {error}"),
    }
}

content_dungeons.excerpt:
use content::{ContentDb, Dungeon};
use osfr_tools::content;
use serde_json::{Value, json};
use std::{
    collections::{HashMap, HashSet},
    fs,
    path::{Path, PathBuf},
    time::{SystemTime, UNIX_EPOCH},
};

struct Scratch(PathBuf);

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn read_json(path: &Path) -> Value {
    serde_json::from_slice(&fs::read(path).unwrap()).unwrap()
}

fn write_json(path: &Path, value: &Value) {
    fs::write(path, serde_json::to_vec_pretty(value).unwrap()).unwrap();
}

fn source_tag(kind: &str, evidence: &str) -> Value {
    json!({"kind": kind, "evidence": evidence})
}

fn records(value: &Value) -> &[Value] {
    value["records"].as_array().unwrap()
}

fn key(row: &Value) -> (String, String, String, String) {
    (
        row["owner"].as_str().unwrap().to_owned(),
        row["kind"].as_str().unwrap().to_owned(),
        row["target_name"].as_str().unwrap_or("").to_owned(),
        row["target_id"]
            .as_u64()
            .map(|id| id.to_string())
            .unwrap_or_default(),
    )
}

fn check_source_tags(value: &Value, path: &str) {
    match value {
        Value::Array(rows) => {
            for (index, row) in rows.iter().enumerate() {
                check_source_tags(row, &format!("{path}[{index}]"));
            }
        }
        Value::Object(fields) => {
            if let Some(sources) = fields.get("source") {
                let sources = sources
                    .as_array()
                    .unwrap_or_else(|| panic!("{path}.source must be an array"));
                assert!(!sources.is_empty(), "{path}.source must not be empty");
                for source in sources {
                    let kind = source["kind"].as_str().unwrap();
                    let evidence = source["evidence"].as_str().unwrap();
                    assert!(!evidence.trim().is_empty(), "{path} has blank evidence");
                    if kind == "reconstructed" {
                        assert!(evidence.starts_with("(R)"), "{path}: {evidence}");
                    }
                }
            }
            if fields.get("value") == Some(&Value::Null) {
                assert!(
                    fields
                        .get("reason")
                        .and_then(Value::as_str)
                        .is_some_and(|s| !s.trim().is_empty()),
                    "{path}: null value needs a reason"
                );
            }
            for (name, child) in fields {
                check_source_tags(child, &format!("{path}.{name}"));
            }
        }
        _ => {}
    }
}

#[derive(Default)]
struct Catalogues {
    zones: HashSet<u64>,
    zone_names: HashSet<String>,
    npc_actor_ids: HashSet<u64>,
    npc_content_ids: HashSet<u64>,
    npc_names: HashMap<String, HashSet<u64>>,
    item_ids: HashSet<u64>,
}

impl Catalogues {
    fn load(root: &Path) -> Self {
        let mut result = Self::default();
        let zones_path = root.join("zones.json");
        if zones_path.is_file() {
            for row in read_json(&zones_path)["records"]
                .as_array()
                .into_iter()
                .flatten()
            {
                if let Some(id) = row["id"].as_u64() {
                    result.zones.insert(id);
                }
                if let Some(name) = row["name"].as_str() {
                    result.zone_names.insert(name.to_owned());
                }
            }
        }
        let npcs_path = root.join("npcs.json");
        if npcs_path.is_file() {
            for row in read_json(&npcs_path)["records"]
                .as_array()
                .into_iter()
                .flatten()
            {
                if let Some(id) = row["actor_id"].as_u64() {
                    result.npc_actor_ids.insert(id);
                }
            }
        }
        let npc_dir = root.join("npcs");
        if npc_dir.is_dir() {
            for entry in fs::read_dir(npc_dir).unwrap().filter_map(Result::ok) {
                let path = entry.path();
                if !path.extension().is_some_and(|ext| ext == "json") {
                    continue;
                }
                for row in read_json(&path)["records"].as_array().into_iter().flatten() {
                    let Some(id) = row["npc_id"].as_u64() else {
                        continue;
                    };
                    result.npc_content_ids.insert(id);
                    if let Some(name) = row["name"].as_str() {
                        result
                            .npc_names
                            .entry(name.to_lowercase())
                            .or_default()
                            .insert(id);
                    }
                }
            }
        }
        let items_path = root.join("items.json");
        if items_path.is_file() {
            for row in read_json(&items_path)["records"]
                .as_array()
                .into_iter()
                .flatten()
            {
                if let Some(id) = row["id"].as_u64() {
                    result.item_ids.insert(id);
                }
            }
        }
        result
    }

    fn resolves(&self, reference: &Value) -> bool {
        let kind = reference["kind"].as_str().unwrap_or("");
        if let Some(id) = reference["target_id"].as_u64() {
            return match kind {
                "zone" => self.zones.contains(&id),
                "npc" => self.npc_actor_ids.contains(&id) || self.npc_content_ids.contains(&id),
                "item" => self.item_ids.contains(&id),
                _ => false,
            };
        }
        let name = reference["target_name"].as_str().unwrap_or("");
        match kind {
            "zone" => self.zone_names.contains(name),
            "npc" => self
                .npc_names
                .get(&name.to_lowercase())
                .is_some_and(|ids| ids.len() == 1),
            _ => false,
        }
    }
}

