            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir(&path).unwrap();
        let data = [
            [10, 8, 15, 2, 50, 1, 0, 0, 0, 0, 0],
            [24, 15, 1, 1, 100, 0, 0, 0, 0, 0, 0],
            [40, 2, 2, 0, 20, 20, 2, 3, 100, 200, 400],
            [49, 8, 3, 100, 500, 0, 0, 0, 0, 0, 0],
            [46, 0, 500, 0, 0, 0, 0, 0, 0, 0, 0],
