            .load_field_enemies(&self.dir.join("field_enemies.json"))
            .unwrap();
        engine
            .load_field_battles(&self.dir.join("field_battles.json"))
            .unwrap();
        if self.dir.join("zone_0.hgt").is_file() {
            engine.set_terrain(Some(Arc::new(Terrain::load(&self.dir).unwrap())));
        }
        engine
    }
