    for camp in camps(&engine).iter().filter(|c| c.band[0] > STARTER_TOP) {
        for (route, from, to) in &routes {
            let need = camp.leash + camp.aggro + LOW_LEVEL_MARGIN;
            let apart = off_route(camp.at, *from, *to);
