use osfr_tools::encounter::{EncounterEngine, EncounterOutcome, Mode};
use serde_json::{Value, json};
use std::{collections::BTreeSet, fs};

#[path = "common/combat_scale.rs"]
mod combat_scale;
#[path = "common/field_enemy_fixture.rs"]
mod field_enemy_fixture;

use field_enemy_fixture::{Fixture, content_dir, spawned};

const GUID: u64 = 131000102001;

fn at(e: &EncounterEngine, guid: u64) -> [f32; 3] {
    e.field_teleport_targets()
        .into_iter()
        .find(|target| target.guid == guid)
        .unwrap()
        .position
}

fn horizontal_radius(position: [f32; 3], home: [f32; 3]) -> f32 {
    (position[0] - home[0]).hypot(position[2] - home[2])
}

fn hp(out: &EncounterOutcome, guid: u64) -> Option<(u32, u32)> {
    out.replies
        .iter()
        .find(|packet| packet.starts_with(&[35, 0, 5, 0]) && packet[4..12] == guid.to_le_bytes())
        .map(|packet| {
            (
                u32::from_le_bytes(packet[12..16].try_into().unwrap()),
                u32::from_le_bytes(packet[16..20].try_into().unwrap()),
            )
        })
}

#[test]
fn starting_regions_have_grouped_reconstructed_placements_and_presets() {
    let field: Value =
        serde_json::from_slice(&fs::read(content_dir().join("field_enemies.json")).unwrap())
            .unwrap();
    let behaviours: Value =
        serde_json::from_slice(&fs::read(content_dir().join("behaviours.json")).unwrap()).unwrap();
    let preset = &behaviours["presets"]["field_roamer"];
    assert_eq!(preset["mode"], "melee");
    assert_eq!(preset["leash"], 12.0);
    assert_eq!(preset["reach"], 2.5);

    let groups = field["spawn_groups"].as_array().unwrap();
    let expected = [
        ("starting_farnum_wolves", "Farnum outskirts", "W102-F", 45),
        (
            "starting_highroad_hooligans",
            "Highroad outskirts",
            "W102-H",
            60,
        ),
        (
            "starting_queensfields_bixies",
            "Sanctuary / Queensfields",
            "W102-Q",
            45,
        ),
        (
            "starting_wilds_shamans",
            "Lakeshore / northeast Wilds",
            "W102-T",
            60,
        ),
    ];
    assert!(groups.len() >= expected.len());

    let enemies = field["enemies"].as_array().unwrap();
    let mut grouped = BTreeSet::new();
    for (group, (id, region, area_prefix, respawn)) in groups.iter().zip(expected) {
        assert_eq!(group["id"], id);
        assert_eq!(group["region"], region);
        assert_eq!(group["zone_id"], 0);
        assert_eq!(group["behaviour"], "field_roamer");
        assert_eq!(group["respawn_seconds"], respawn);
        assert_eq!(group["aggro_range"], 8.0);
        assert_eq!(group["leash_radius"], 12.0);
        assert!(group["source"].as_array().is_some_and(|sources| {
            sources.iter().any(|source| {
                source["kind"] == "reconstructed"
                    && source["evidence"]
                        .as_str()
                        .is_some_and(|text| text.starts_with("(R)"))
            })
        }));
        let members = group["members"].as_array().unwrap();
        assert_eq!(members.len(), 3);
        for member in members {
            let guid = member.as_u64().unwrap();
            assert!(grouped.insert(guid), "duplicate grouped GUID {guid}");
            let actor = enemies.iter().find(|actor| actor["guid"] == guid).unwrap();
            assert_eq!(actor["quest_ids"], json!([]));
            assert!(
                actor["spawn_area"]["id"]
                    .as_str()
                    .is_some_and(|area| area.starts_with(area_prefix))
            );
            assert!(actor["position"].as_array().is_some_and(|p| p.len() == 3));
            let sources = actor["source"].as_array().unwrap();
            for kind in ["client", "reference", "legacy-data", "reconstructed"] {
                assert!(sources.iter().any(|source| source["kind"] == kind));
            }
            assert!(sources.iter().any(|source| {
                source["kind"] == "reconstructed"
                    && source["evidence"]
                        .as_str()
                        .is_some_and(|text| text.starts_with("(R)"))
            }));
        }
    }
    assert_eq!(grouped.len(), 12);
    // Every always-on actor belongs to a group. T245's mid-level camps are
    // appended groups too; this test pins the four starter groups above.
    let all_grouped: BTreeSet<u64> = groups
        .iter()
        .flat_map(|group| group["members"].as_array().unwrap())
        .map(|member| member.as_u64().unwrap())
        .collect();
    for actor in enemies
        .iter()
        .filter(|actor| actor["quest_ids"] == json!([]))
    {
        assert!(
            all_grouped.contains(&actor["guid"].as_u64().unwrap()),
            "{} is always-on but ungrouped",
            actor["guid"]
        );
    }
}

#[test]
fn group_spawns_roam_kill_and_respawn_on_the_authored_timer() {
    let fixture = Fixture::copied();
    let mut e = fixture.load();
    let spawned = spawned(&e.on_zone_ready(11, 0).unwrap());
    assert!(spawned.len() >= 12);
    for guid in 131000102001..=131000102012 {
        assert!(spawned.contains(&guid), "starter {guid} must still spawn");
    }
    assert!(spawned.contains(&GUID));
    let behaviour = e.behaviour(GUID).unwrap();
    assert_eq!(behaviour.mode, Mode::Melee);
    assert_eq!(behaviour.leash, 12.0);

    let home = at(&e, GUID);
    let observer = [home[0] + 100.0, home[1], home[2]];
    let mut moved = false;
    for t in 0..100 {
        e.tick(observer, 11, t * 100).unwrap();
        let position = at(&e, GUID);
        let radius = horizontal_radius(position, home);
        moved |= radius > 0.5;
        assert!(radius <= 6.001, "roamed {radius} m from its 6 m disc");
    }
    assert!(moved, "the group member must leave its exact spawn point");

    let target = at(&e, GUID);
    let mut killed_at = None;
    let mut death = None;
    for now in [20_000_u64, 20_700, 21_400] {
        let out = e
            .attack(GUID, [target[0] + 1.0, target[1], target[2]], 11, 0, now)
            .unwrap();
        death = Some(out);
        if !e
            .field_teleport_targets()
            .iter()
            .any(|enemy| enemy.guid == GUID)
        {
            killed_at = Some(now);
            break;
        }
    }
    let killed_at = killed_at.expect("three basic attacks must defeat the level-1 wolf");
    let death = death.unwrap();
    assert!(death.replies.iter().any(|packet| {
        packet.starts_with(&[35, 0, 3, 0]) && packet[6..14] == GUID.to_le_bytes()
    }));

    let before = e
        .tick(
            [target[0] + 1.0, target[1], target[2]],
            11,
            killed_at + 44_999,
        )
        .unwrap();
    assert!(
        !e.field_teleport_targets()
            .iter()
            .any(|enemy| enemy.guid == GUID),
        "the group timer must not expire one millisecond early"
    );
    assert!(!before.replies.iter().any(|packet| {
        (packet.starts_with(&[35, 0, 2, 0]) && packet[4..12] == GUID.to_le_bytes())
            || (packet.starts_with(&[35, 0, 5, 0]) && packet[4..12] == GUID.to_le_bytes())
    }));
    let at_respawn = e
        .tick(
            [target[0] + 1.0, target[1], target[2]],
            11,
            killed_at + 45_100,
        )
        .unwrap();
    assert_eq!(
        hp(&at_respawn, GUID),
        Some((
            combat_scale::enemy_health(100),
            combat_scale::enemy_health(100)
        ))
    );
    assert!(at_respawn.replies.iter().any(|packet| {
        packet.starts_with(&[35, 0, 2, 0]) && packet[4..12] == GUID.to_le_bytes()
    }));
    assert_eq!(at(&e, GUID), home);
}

#[test]
fn malformed_group_reload_is_atomic() {
    let fixture = Fixture::copied();
    let mut e = fixture.load();
    let before = e
        .field_teleport_targets()
        .into_iter()
        .map(|target| (target.guid, target.position))
        .collect::<Vec<_>>();
    let behaviour = e.behaviour(GUID).cloned().unwrap();

    let path = fixture.field_path().to_path_buf();
    let mut field: Value = serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();
    field["spawn_groups"][0]["members"] = json!([GUID, GUID]);
    fs::write(&path, field.to_string()).unwrap();

    assert!(e.reload_field_enemies(&path).is_err());
    let after = e
        .field_teleport_targets()
        .into_iter()
        .map(|target| (target.guid, target.position))
        .collect::<Vec<_>>();
    assert_eq!(after, before);
    assert_eq!(e.behaviour(GUID), Some(&behaviour));
}

field_kill_rewards.excerpt:
//! T240/F276: field-enemy kills pay coins and active-job XP once per credited player.
//!
//! Every test drives the production shared-field seams: `handle_shared_field`
//! (attack), `tick_shared_effects` (claim), `Gameplay::load` (content/reconnect),
//! `Gameplay::reload_content` (the dev reload path) and, for a battle win,
//! `handle_in_world` (realm battle/win). The reward table is
//! `data/content/field_kill_rewards.json`; the field actors stay in
//! `field_enemies.json` with their existing schema. F276 adds the disconnect
//! prune (`retain_casters`, the real shared-tick call), the mid-fight reload
//! proof, the battle-reward gate and the shipped level-band assertions. The
//! real-session save guard lives in the gateway binary
//! (`src/bin/osfr_gateway/f276_field_session_save.rs`), because only the
//! binary writes the character save. The load root and the shared field helpers
//! are `tests/common/field_reward_fixture.rs`, shared with the high-camp suite.
use osfr_tools::{
    account_store::AccountRole,
    character_store::CharacterState,
    chat,
    encounter::{EncounterPhase, SharedFieldState},
    game_store::{self, Snapshot},
    gameplay::{Gameplay, Outcome},
};
use serde_json::{Value, json};
use std::{collections::BTreeSet, fs, path::PathBuf};

#[path = "common/field_reward_fixture.rs"]
mod field_reward_fixture;

use field_reward_fixture::{
    CREDIT_TTL_MS, NONCOMBAT, RewardFixture, attack, bank, character_at, kill, player,
    shipped_field_actor, source,
};

#[path = "support/packets.rs"]
mod packets;
#[allow(dead_code)] // Only the shared reply-text extractor is used here.
#[path = "common/s6.rs"]
mod s6;

use packets::{carrier, count, packet};

const ENEMY: u64 = 131000109001;
const ENEMY_TWO: u64 = 131000109002;
const LEVEL_ONE: i32 = 930108;
const WOLF: i32 = 3156;
/// T245's level-5 MID-F1 camp wolf. The shipped row keeps definition 3156, so
/// the kind's override (not the level 5-8 band) owns its payout.
const MID_F1: u64 = 131_000_102_013;

/// The one fixed refusal line for a reward the wallet or active job cannot
/// take. `(R)` text: no recovered client locale row names it.
const REWARD_REFUSED: &str = "This reward, any prize item and any chance drop it carried were not granted: your coin balance or active job is at its limit.";

/// A field actor with no power-up table: only the kill reward path is used.
fn actor(guid: u64, definition_id: i32, level: u32, position: [f32; 3], max_health: u32) -> Value {
    json!({
        "guid": guid,
        "definition_id": definition_id,
        "model_id": 3,
        "name_id": 100,
        "name": "Synthetic field reward",
        "texture_alias": "",
        "position": position,
        "max_health": max_health,
        "damage": 1,
        "boss": false,
        "level": level,
        "respawn_seconds": 60,
        "aggro_range": 8.0,
        "leash_radius": 12.0,
        "behaviour": {"mode":"stationary","reach":2.5,"attack_ms":1000},
        "quest_ids": []
    })
}

/// The shipped shape: one level band and no definition override.
fn levels(coins: u32, job_xp: u32) -> Value {
    json!({
        "schema_version": 1,
        "level_rewards": [
            {"min_level": 1, "max_level": 2, "coins": coins, "job_xp": job_xp, "source": source()}
        ],
        "definition_overrides": []
    })
}

/// The production reconnect reads the character snapshot back through
/// `game_store::load_or_create` and then loads the gameplay state.
fn reconnect(fixture: &RewardFixture, character: &CharacterState) -> Gameplay {
    let snapshot =
        game_store::load_or_create(&fixture.save_path(character), character.clone()).unwrap();
    let mut game = Gameplay::load(fixture.dir(), snapshot.gameplay).unwrap();
    game.initialize_world(character, 0).unwrap();
    game.take_shared_fields();
    game
}

fn save(game: &Gameplay, fixture: &RewardFixture, character: &CharacterState) -> PathBuf {
    let path = fixture.save_path(character);
    game_store::save(
        &path,
        &Snapshot {
            character: character.clone(),
            gameplay: Some(game.state()),
            pets: None,
        },
    )
    .unwrap();
    path
}

fn switch_job(
    game: &mut Gameplay,
    character: &CharacterState,
    profile: i32,
    now_ms: u64,
) -> Outcome {
    let mut select = vec![26, 0, 13, 0];
    select.extend(profile.to_le_bytes());
    game.handle_in_world(&select, character, now_ms).unwrap()
}

/// The observable runtime of one field actor; a refusal must not move any of it.
fn field_view(field: &SharedFieldState, guid: u64) -> (Option<u32>, [f32; 3], Option<u64>) {
    (
        field.health(guid),
        field.position(guid).unwrap(),
        field.respawn_at(guid),
    )
}

#[test]
fn a_solo_field_kill_pays_once_and_only_the_active_job() {
    let fixture = RewardFixture::new(vec![actor(ENEMY, LEVEL_ONE, 1, [0.0; 3], 100)]);
    let at = [1.0, 0.0, 0.0];
    let character = character_at(101, at);
    let mut game = player(&fixture, 101, 43, at, 0, None);
    let mut field = game.take_shared_fields().unwrap();
    let known = BTreeSet::from([ENEMY]);

    let (lethal, killed_at) = kill(&mut game, &mut field, &character, &known, ENEMY, 0);
    assert_eq!(field.health(ENEMY), Some(0));
    // Byte-level carriers: 38/19 is one i32 total (client ctor 0x0089e670);
    // 38/14 is profile, rank, progress and three zero fields (reader 0x008d86e0).
    assert_eq!(count(&lethal.replies, 38, 19), 1);
    assert_eq!(
        packet(&lethal.replies, 38, 19),
        [38u8, 0, 19, 0, 2, 0, 0, 0].as_slice()
    );
    assert_eq!(
        packet(&lethal.replies, 38, 14),
        carrier(38, 14, &[43, 1, 5, 0, 0, 0]).as_slice()
    );
    let (coins, xp) = bank(&game);
    assert_eq!(coins, 2);
    assert_eq!(xp.get(&43), Some(&5));
    assert_eq!(xp.get(&35), None, "only the active job is paid");
    assert_eq!(xp.get(&NONCOMBAT), None);

    // Replaying the lethal hit or hitting the corpse must change nothing. The
    // gateway only saves when the action changed state, and the real-session
    // save guard for that rule is `f276_field_session_save` in the binary.
    let state_before = game.state();
    let field_before = field_view(&field, ENEMY);
    let replay = attack(
        &mut game,
        &mut field,
        &character,
        &known,
        ENEMY,
        killed_at + 700,
    )
    .unwrap();
    assert!(!replay.changed && replay.replies.is_empty());
    let corpse = attack(
        &mut game,
        &mut field,
        &character,
        &known,
        ENEMY,
        killed_at + 1_400,
    )
    .unwrap();
    assert!(!corpse.changed && corpse.replies.is_empty());
    assert_eq!(game.state(), state_before);
    assert_eq!(field_view(&field, ENEMY), field_before);
}

#[test]
fn the_mid_level_farnum_camp_pays_the_kind_override_rate() {
    // The level-5 MID-F camp reuses definition 3156. The override exists so the
    // kind's rate cannot be retuned by a level edit; it wins over the level 5-8
    // band for this camp, so the payout stays 2 coins / 5 job XP.
    let (row, home) = shipped_field_actor(MID_F1);
    assert_eq!(row["level"], 5);
    let fixture = RewardFixture::new(vec![row]);
    let at = [home[0] + 1.0, home[1], home[2]];
    let character = character_at(101, at);
    let mut game = player(&fixture, 101, 43, at, 0, None);
    let mut field = game.take_shared_fields().unwrap();
    let known = BTreeSet::from([MID_F1]);

    let (lethal, _) = kill(&mut game, &mut field, &character, &known, MID_F1, 0);
    assert_eq!(
        packet(&lethal.replies, 38, 19),
        [38u8, 0, 19, 0, 2, 0, 0, 0].as_slice(),
        "definition 3156 keeps its 2 coins at level 5, not the band's 7"
    );
    assert_eq!(
        packet(&lethal.replies, 38, 14),
        carrier(38, 14, &[43, 1, 5, 0, 0, 0]).as_slice(),
        "and its 5 job XP, not the level 5-8 band's 15"
    );
    assert_eq!(game.state().inventory.coins, 2);
    assert_eq!(
        game.state().profiles.as_ref().unwrap().experience.get(&43),
        Some(&5)
    );
}

#[test]
fn a_shared_kill_pays_each_credited_player_once() {
    // Definition 3156's override pays 2/5 at level 3, where the band pays 4/10.
    let fixture = RewardFixture::new(vec![actor(ENEMY, WOLF, 3, [0.0; 3], 500)]);
    let a_at = [1.0, 0.0, 0.0];
    let b_at = [-1.0, 0.0, 0.0];
    let c_at = [2.0, 0.0, 0.0];
    let a_character = character_at(101, a_at);
    let b_character = character_at(202, b_at);
    let c_character = character_at(303, c_at);
