            let action = &b"\x0b\x00\x00\x00closeWindow"[..];
            expected = [&expected[..38], action, &expected[46..]].concat();
            expected[3..7].copy_from_slice(&71u32.to_le_bytes());
        }
        assert_eq!(message, &expected, "startup message index {index:02}");
    }
