        }
    );
}

#[test]
fn leader_can_disband_and_all_character_references_are_removed() {
    let (mut store, guild) = three_members();
    store.login(1).unwrap();
    let notices = store.disband(1).unwrap();
    assert!(
        notices
            .iter()
            .any(|notice| notice.kind == GuildNoticeKind::Disbanded)
    );
