halloween_dance_off.excerpt:
//! T464: the Halloween Vampires vs Werewolves dance-off, the shipped `halloween_dance_off` row of
//! `world_events.json`. Every id in it is gated against the client's own tables; the run is
//! driven through the real `WorldEvents::tick` for each ending; the schedule is swept over a day
//! in and a day out of season.
#[path = "support/world_event_content.rs"]
mod world_event_content;

use osfr_tools::{
    chat,
    client_areas::ClientAreas,
    players::{InterestPolicy, PlayerRegistry, SessionId, ZoneInstance},
    world_events::{self, WorldEvent, WorldEvents},
};
use serde_json::Value;
use std::collections::BTreeSet;
use world_event_content::{assert_every_id_resolves, content, locale, ops, row, shipped};

const KEY: &str = "halloween_dance_off";
const WORLD: ZoneInstance = ZoneInstance {
    zone_id: 0,
    instance_id: 0,
};
/// The song-area centre in the client (FabledRealmsAreas.xml:3488); the viewer stands on it.
const DANCE_SPOT: [f32; 3] = [-2384.4, -26.77, 1214.94];
const OCT_21_2026_MS: u64 = 1_792_540_800_000; // 00:00 UTC, in the season
const NOV_12_2026_MS: u64 = 1_794_441_600_000; // the day after the season's last day
const DAY_MS: u64 = 86_400_000;
const POOF: i32 = 21; // PFX_smoke_black_explosion
const BOOMBOX_SPARKS: i32 = 5120;
const FIREWORKS: i32 = 5349;

#[test]
fn every_id_resolves_against_the_client() {
    let file = shipped();
    let event = row(&file, KEY);
    let ids = assert_every_id_resolves(event);
    assert_eq!(
        ids.areas,
        BTreeSet::from([4299, 4300, 4302, 4303, 4304, 4305])
    );
    assert_eq!(
        ids.effects,
        BTreeSet::from([POOF, BOOMBOX_SPARKS, FIREWORKS])
    );
    assert_eq!(
        event["schedule"]["announce"]["text"],
        locale()[&5197],
        "the kickoff line is the client's"
    );
}

/// One viewer standing on the dance spot, in the open world.
fn viewer() -> PlayerRegistry {
    let mut players = PlayerRegistry::new(InterestPolicy::new(100.0, 64).unwrap());
    players
        .join(SessionId(1), 1, 1, WORLD, DANCE_SPOT, 0.0)
        .unwrap();
    players
}
fn event() -> WorldEvent {
    let mut events = world_events::load(&content()).unwrap();
    let at = events.iter().position(|event| event.key == KEY).unwrap();
    events.swap_remove(at)
}

/// What the viewer was sent, in order.
type Heard = Vec<Vec<u8>>;

/// Runs the event from `start_ms` for ten minutes (it lasts about ten and a half) in 250 ms
/// ticks; the returned run is the viewer's packets plus whether the run has ended.
fn play(start_ms: u64, stop_at: Option<u64>) -> (Heard, WorldEvents, ClientAreas) {
    let (players, mut areas) = (viewer(), ClientAreas::load(&content()).unwrap());
    let mut events = WorldEvents::default();
    assert!(events.start(event(), WORLD, start_ms));
    let mut heard = Heard::new();
    for now in (start_ms..start_ms + 650_000).step_by(250) {
        if stop_at.is_some_and(|stop| now == start_ms + stop) {
            assert!(events.stop(KEY));
        }
        let out = events.tick(now, OCT_21_2026_MS + now, &players, &mut areas);
        heard.extend(out.into_iter().map(|(_, packet)| packet));
    }
    (heard, events, areas)
}

fn guid(packet: &[u8]) -> u64 {
    u64::from_le_bytes(packet[4..12].try_into().unwrap())
}
fn i32_at(packet: &[u8], at: usize) -> i32 {
    i32::from_le_bytes(packet[at..at + 4].try_into().unwrap())
}

/// The actors' indices in the event row, so a guid's low byte names who it is.
fn index_of(event: &Value, key: &str) -> u64 {
    event["actors"]
        .as_array()
        .unwrap()
        .iter()
        .position(|actor| actor["key"] == key)
        .unwrap_or_else(|| panic!("no actor {key}")) as u64
}

/// The two endings: a run whose prince announces the vampires, and one that announces the
/// werewolves. The branch comes from the run's seed (`start_ms` and the serial), so the first
/// start times that draw each are found by running.
fn both_endings() -> [Heard; 2] {
    let mut found: [Option<Heard>; 2] = [None, None];
    for start_ms in 0..64 {
        let heard = play(start_ms, None).0;
        let says = |id: i32| {
            heard
                .iter()
                .any(|p| p[..4] == [15, 0, 4, 0] && i32_at(p, 12) == id)
        };
        let side = match (says(432_432), says(432_407)) {
            (true, false) => 0,
            (false, true) => 1,
            other => panic!("one ending per run, saw {other:?}"),
        };
        found[side].get_or_insert(heard);
        if found.iter().all(Option::is_some) {
            break;
        }
    }
    found.map(|heard| heard.expect("both endings are reachable within 64 seeds"))
}

#[test]
fn the_six_rounds_alternate_sides_and_every_song_area_goes_off_once() {
    let file = shipped();
    let event = row(&file, KEY);
    let idx =
        |keys: &[&str]| -> BTreeSet<u64> { keys.iter().map(|k| index_of(event, k)).collect() };
    let vampires = idx(&["ed", "vampire1", "vampire2", "vampire3"]);
    let werewolves = idx(&["jake", "werewolf1", "werewolf2", "werewolf3"]);
    let boombox = index_of(event, "boombox");
    let song_areas = [4299, 4300, 4302, 4303, 4304, 4305];
    for heard in both_endings() {
        // Area packets: opcode 89, area i32 at 2, on-flag at 6. Each goes on and then off, in order.
        let area_packets: Vec<(usize, i32, bool)> = heard
            .iter()
            .enumerate()
            .filter(|(_, p)| p[..2] == [89, 0])
            .map(|(at, p)| (at, i32_at(p, 2), p[6] == 1))
            .collect();
        let sequence: Vec<_> = area_packets
            .iter()
            .map(|(_, area, on)| (*area, *on))
            .collect();
        let expected: Vec<_> = song_areas
            .iter()
            .flat_map(|a| [(*a, true), (*a, false)])
            .collect();
        assert_eq!(
            sequence, expected,
            "each area on then off, one at a time, in song order"
        );

        for (round, pair) in area_packets.chunks(2).enumerate() {
            let window = &heard[pair[0].0..pair[1].0];
            // The dancers are the ones given a one-shot move (35/8, base flag clear) in the song.
            let dancers: BTreeSet<u64> = window
                .iter()
                .filter(|p| p[..4] == [35, 0, 8, 0] && p[20] == 0)
                .map(|p| guid(p) & 0xff)
                .collect();
            let (side, rival) = match round % 2 {
                0 => (&vampires, &werewolves),
                _ => (&werewolves, &vampires),
            };
            assert_eq!(&dancers, side, "round {round} is danced by one whole side");
            let speakers: BTreeSet<u64> = window
                .iter()
                .filter(|p| p[..4] == [15, 0, 4, 0])
                .map(|p| guid(p) & 0xff)
                .collect();
            assert!(
                !speakers.is_empty() && speakers.iter().all(|s| rival.contains(s)),
                "round {round}: the rival side taunts, {speakers:?}"
            );
            // The boombox sparks are on for the song and off after it.
            let tags = |sub: u8| -> Vec<&Vec<u8>> {
                window
                    .iter()
                    .filter(|p| p[..4] == [35, 0, sub, 0] && guid(p) & 0xff == boombox)
                    .collect()
            };
            assert_eq!(tags(41).len(), 1, "round {round}: the sparks come on once");
            assert_eq!(i32_at(tags(41)[0], 16), BOOMBOX_SPARKS);
            assert!(
                tags(42).is_empty(),
                "round {round}: not off until the song ends"
            );
        }
        let sparks_on = heard.iter().filter(|p| p[..4] == [35, 0, 41, 0]).count();
        let sparks_off = heard.iter().filter(|p| p[..4] == [35, 0, 42, 0]).count();
        assert_eq!((sparks_on, sparks_off), (6, 6));
    }
}

#[test]
fn each_ending_names_its_winner_leaves_one_cake_and_no_actor_behind() {
    let file = shipped();
    let event = row(&file, KEY);
    let key = |index: u64| event["actors"][index as usize]["key"].as_str().unwrap();
    let says = |heard: &Heard| -> Vec<(String, i32)> {
        heard
            .iter()
            .filter(|p| p[..4] == [15, 0, 4, 0])
            .map(|p| (key(guid(p) & 0xff).to_owned(), i32_at(p, 12)))
            .collect()
    };
    let [vampire_win, werewolf_win] = both_endings();
    for (heard, winner_line, reward, cake, other_lines) in [
        (
            &vampire_win,
            432_432,
            432_433,
            "cake_vampire",
            [432_407, 432_435],
        ),
        (
            &werewolf_win,
            432_407,
            432_435,
            "cake_werewolf",
            [432_432, 432_433],
        ),
    ] {
        let said = says(heard);
        let ids: Vec<i32> = said.iter().map(|(_, id)| *id).collect();
        assert!(ids.contains(&winner_line) && ids.contains(&reward));
        assert!(
            other_lines.iter().all(|id| !ids.contains(id)),
            "the other ending's lines stay out"

halloween_season_props.excerpt:
//! T491 (R): a content row may name a `client_areas.json` season; `NpcVisibility` drops it when
//! that season is over. T468 retired the 12 Halloween decoration rows to
//! `npc_spawns_retired.json` as out-of-bounds housing-demo props, and `world.rs` never reads that
//! archive, so production draws none of them today. These tests copy the real live table and add
//! those archived rows, so the rule is proven on the shipped 2,675 rows plus the 12 candidates.
//! No test reads today's date: every clock below is fixed.
use osfr_tools::{gameplay::Gameplay, world::NpcVisibility};
use serde_json::{Value, json};
use std::{
    collections::BTreeSet,
    fs,
    path::{Path, PathBuf},
    sync::atomic::{AtomicU64, Ordering},
};

#[allow(dead_code)] // only `copy_missing` is used here
#[path = "common/content_copy.rs"]
mod content_copy;

/// 2026-10-31 12:00 UTC, inside Halloween (9/20 to 11/11), and 2026-01-15 12:00 UTC, outside.
const IN_SEASON_MS: u64 = 1_793_448_000_000;
const OFF_SEASON_MS: u64 = 1_768_478_400_000;
const CAKE: u64 = 100_000_012_182;
/// A content key no live row uses, put on the cake to prove the load-side map follows the row.
const CAKE_KEY: u64 = 491_000_001;
static NEXT: AtomicU64 = AtomicU64::new(0);

fn bundled() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("data/content")
}

/// The opening package supplies the opening, inventory and quest files `Gameplay::load` needs;
/// the bundled content then fills in the world, NPC and area tables.
fn opening() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../../lab/references/rust-opening-cooking-original-assets")
}

fn rows_of(path: &Path) -> Vec<Value> {
    serde_json::from_slice::<Value>(&fs::read(path).unwrap()).unwrap()["records"]
        .as_array()
        .unwrap()
        .clone()
}

fn guid(row: &Value) -> u64 {
    row["spawn_guid"].as_u64().unwrap()
}

fn live_rows() -> Vec<Value> {
    rows_of(&bundled().join("npc_spawns_extra.json"))
}

/// T468's archive: the 12 shipped Halloween decoration rows, sorted by GUID.
fn archived_halloween_rows() -> Vec<Value> {
    let mut rows: Vec<Value> = rows_of(&bundled().join("npc_spawns_retired.json"))
        .into_iter()
        .filter(|row| {
            row["model_file_name"]
                .as_str()
                .is_some_and(|name| name.to_ascii_lowercase().contains("halloween"))
        })
        .collect();
    rows.sort_by_key(guid);
    rows
}

/// The 12 shipped rows, tagged, unique, and absent from the live table (T468).
fn tagged_rows(live: &[Value], archived: &[Value]) -> BTreeSet<u64> {
    assert_eq!(
        archived.len(),
        12,
        "the archive holds the 12 Halloween decoration rows"
    );
    assert!(
        live.iter().all(|row| row.get("season").is_none()),
        "the live table carries no season tag: production draws none of these props (T468)"
    );
    let tagged: BTreeSet<u64> = archived.iter().map(guid).collect();
    assert_eq!(tagged.len(), 12, "a Halloween spawn GUID repeats");
    assert!(
        archived
            .iter()
            .all(|row| row["season"].as_str() == Some("Halloween")),
        "every archived row names the Halloween season"
    );
    let live_guids: BTreeSet<u64> = live.iter().map(guid).collect();
    assert!(
        tagged.is_disjoint(&live_guids),
        "an archived row is live again; T468's exit pin would fail too"
    );
    tagged
}

fn cake_key(archived: &mut [Value]) {
    archived.iter_mut().find(|row| guid(row) == CAKE).unwrap()["content_key"] = json!(CAKE_KEY);
}

fn present(visibility: &NpcVisibility, guids: &BTreeSet<u64>) -> BTreeSet<u64> {
    guids
        .iter()
        .copied()
        .filter(|guid| visibility.actor_position(*guid).is_some())
        .collect()
}

/// The production-shaped content tree with `live` plus `archived` in the live NPC table.
struct Fixture {
    dir: PathBuf,
}

impl Fixture {
    fn new(tag: &str, live: &[Value], archived: &[Value]) -> Self {
        let dir = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(format!(
            "f683-t491-{tag}-{}-{}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        content_copy::copy_missing(&opening(), &dir);
        content_copy::copy_missing(&bundled(), &dir);
        // This suite exercises NPC visibility, not harvesting; the opening inventory does not
        // carry every optional farming reward the bundled content defines (same rule as the
        // soccer and field-combat fixtures).
        let _ = fs::remove_file(dir.join("harvesting.json"));
        let fixture = Self { dir };
        let mut rows = live.to_vec();
        rows.extend(archived.iter().cloned());
        fixture.write_rows(&rows);
        fixture
    }

    fn path(&self) -> &Path {
        &self.dir
    }

    fn write_rows(&self, rows: &[Value]) {
        fs::write(
            self.dir.join("npc_spawns_extra.json"),
            serde_json::to_vec(&json!({"schema_version": 1, "records": rows})).unwrap(),
        )
        .unwrap();
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.dir);
    }
}

#[test]
fn the_twelve_halloween_rows_are_tagged_and_leave_only_when_the_season_is_over() {
    let live = live_rows();
    let mut archived = archived_halloween_rows();
    let tagged = tagged_rows(&live, &archived);
    cake_key(&mut archived);
    let guids: BTreeSet<u64> = live.iter().chain(&archived).map(guid).collect();

    let fixture = Fixture::new("retain", &live, &archived);
    let loaded = NpcVisibility::load(fixture.path()).unwrap();
    let shown = present(&loaded, &guids);
    assert!(
        tagged.is_subset(&shown),
        "every archived row loads before the filter"
    );

    let mut active = loaded.clone();
    active.retain_in_season(|_| Some(true)).unwrap();
    assert_eq!(
        present(&active, &guids),
        shown,
        "an active season keeps every row"
    );

    let mut over = loaded.clone();
    over.retain_in_season(|_| Some(false)).unwrap();
    let dropped: BTreeSet<u64> = shown.difference(&present(&over, &guids)).copied().collect();
    assert_eq!(
        dropped, tagged,
        "the over season drops exactly the tagged rows and leaves every live row"
    );
    assert_eq!(active.content_key(CAKE), Some(CAKE_KEY));
    assert_eq!(over.content_key(CAKE), None);
    let (control, key) = live
        .iter()
        .find_map(|row| {
            let guid = guid(row);
            let key = row["content_key"].as_u64()?;
            loaded.actor_position(guid).is_some().then_some((guid, key))
        })
        .expect("the live table has a content-keyed row");
    assert_eq!(active.content_key(control), Some(key));
    assert_eq!(over.content_key(control), Some(key));
}

#[test]
fn an_unknown_season_fails_naming_the_row_and_drops_nothing() {
    let live = live_rows();
    let archived = archived_halloween_rows();
    let first = guid(&archived[0]);
    let guids: BTreeSet<u64> = live.iter().chain(&archived).map(guid).collect();
    let fixture = Fixture::new("unknown", &live, &archived);
    let mut visibility = NpcVisibility::load(fixture.path()).unwrap();
    let before = present(&visibility, &guids);
    let error = visibility.retain_in_season(|_| None).unwrap_err();
    assert!(error.to_string().contains(&first.to_string()), "{error}");
    assert_eq!(
        present(&visibility, &guids),
        before,
        "the refused season dropped a row"
    );
}

#[test]
fn loading_for_play_follows_the_shipped_season_dates() {
    let live = live_rows();
    let mut archived = archived_halloween_rows();
    let tagged = tagged_rows(&live, &archived);
    cake_key(&mut archived);
    let guids: BTreeSet<u64> = live.iter().chain(&archived).map(guid).collect();
    let fixture = Fixture::new("dates", &live, &archived);

    let loaded = NpcVisibility::load(fixture.path()).unwrap();
    let in_season = NpcVisibility::load_in_season_at(fixture.path(), IN_SEASON_MS).unwrap();
    assert_eq!(in_season.model_of(CAKE), Some(3202));
    assert_eq!(in_season.content_key(CAKE), Some(CAKE_KEY));
    assert_eq!(
        present(&in_season, &guids),
        present(&loaded, &guids),
        "the shipped dates keep every row inside Halloween"
    );

    let off_season = NpcVisibility::load_in_season_at(fixture.path(), OFF_SEASON_MS).unwrap();
    assert!(off_season.model_of(CAKE).is_none());
    assert_eq!(off_season.content_key(CAKE), None);
    let dropped: BTreeSet<u64> = present(&loaded, &guids)
        .difference(&present(&off_season, &guids))
        .copied()
        .collect();
    assert_eq!(
        dropped, tagged,
        "outside the shipped dates exactly the tagged rows go"
    );

