/// The (health, maximum) of the last 38/1 in the replies.
fn health_packet(out: &Outcome) -> Option<(i32, i32)> {
    out.replies
        .iter()
        .rev()
        .find(|r| r.len() == 12 && r.starts_with(&[38, 0, 1, 0]))
        .map(|r| {
            (
                i32::from_le_bytes(r[4..8].try_into().unwrap()),
