use osfr_tools::item_categories::ItemCategories;
use serde_json::{Value, json};
use sha2::{Digest, Sha256};
use std::{
    fs,
    path::PathBuf,
    sync::atomic::{AtomicU64, Ordering},
};

static SEQUENCE: AtomicU64 = AtomicU64::new(0);

fn integer(bytes: &mut Vec<u8>, value: i32) {
    bytes.extend(value.to_le_bytes());
}

struct Fixture {
    directory: PathBuf,
    content: Value,
    expected: Vec<u8>,
}

impl Fixture {
    fn new() -> Self {
        let directory = std::env::temp_dir().join(format!(
            "osfr-categories-{}-{}",
            std::process::id(),
            SEQUENCE.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir(&directory).unwrap();
        let mut expected = vec![44, 0, 2, 0];
        integer(&mut expected, 2);
        for (id, name, icon, sort, visible, display) in [
            (10, 962, 1007, 1200, true, 1),
            (104, 23322, 5141, 1360, false, 0),
        ] {
            for field in [id, id, name, icon, sort] {
                integer(&mut expected, field);
            }
            expected.push(u8::from(visible));
            integer(&mut expected, display);
        }
        integer(&mut expected, 3);
        // The third source row rejoins group8 and serializes before group44.
        for fields in [[8, 8, 10], [8, 8, 58], [44, 44, 104]] {
            for field in fields {
                integer(&mut expected, field);
            }
        }
        let content = json!({"schema_version":1,"categories":[
            {"id":10,"name_id":962,"icon_id":1007,"unknown":1200,"unknown2":true,"display":1},
            {"id":104,"name_id":23322,"icon_id":5141,"unknown":1360,"unknown2":false,"display":0}],
            "groups":[{"id":8,"category_id":10},{"id":44,"category_id":104},{"id":8,"category_id":58}],
            "packet_sha256":format!("{:x}",Sha256::digest(&expected))});
        let fixture = Self {
            directory,
            content,
            expected,
        };
        fixture.write();
        fixture
    }
    fn write(&self) {
        fs::write(
            self.directory.join("categories.json"),
            serde_json::to_vec(&self.content).unwrap(),
        )
        .unwrap();
    }
}
impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = fs::remove_file(self.directory.join("categories.json"));
        let _ = fs::remove_dir(&self.directory);
    }
}

#[test]
fn dictionary_keys_values_booleans_and_group_order_match_evidenced_layout() {
    let fixture = Fixture::new();
    let categories = ItemCategories::load(&fixture.directory).unwrap();
    assert_eq!(categories.initialization(), fixture.expected);
    assert_eq!(categories.clone().initialization(), fixture.expected);
    assert_eq!(fixture.expected.len(), 98);
}

#[test]
fn conflicting_duplicate_or_invalid_rows_and_changed_proof_reject() {
    for mutation in 0..7 {
        let mut fixture = Fixture::new();
        match mutation {
            0 => fixture.content["categories"][1]["id"] = json!(10),
            1 => fixture.content["groups"][2]["category_id"] = json!(10),
            2 => fixture.content["categories"][0]["display"] = json!(-1),
            3 => fixture.content["groups"][0]["id"] = json!(0),
            4 => fixture.content["packet_sha256"] = json!("00".repeat(32)),
            5 => fixture.content["schema_version"] = json!(2),
            _ => fixture.content["categories"] = json!([]),
        }
        fixture.write();
        assert!(ItemCategories::load(&fixture.directory).is_err());
    }
}

#[test]
fn oversized_and_malformed_private_content_reject() {
    let fixture = Fixture::new();
    fs::write(
        fixture.directory.join("categories.json"),
        vec![b' '; 256 * 1024 + 1],
    )
    .unwrap();
    assert!(ItemCategories::load(&fixture.directory).is_err());
    fs::write(fixture.directory.join("categories.json"), b"invalid-json").unwrap();
    assert!(ItemCategories::load(&fixture.directory).is_err());
}

#[test]
#[ignore = "requires prepared private categories and unmodified community serializer output"]
fn private_community_serializer_packet_matches_exactly() {
    let directory =
        PathBuf::from(std::env::var_os("OSFR_GAMEPLAY_CONTENT").expect("private content required"));
    let oracle = PathBuf::from(
        std::env::var_os("OSFR_CATEGORY_ORACLE").expect("private C# oracle output required"),
    );
    let categories = ItemCategories::load(&directory).unwrap();
    let packet = categories.initialization();
    assert_eq!(packet, fs::read(oracle).unwrap());
    assert_eq!(&packet[..8], &[44, 0, 2, 0, 71, 0, 0, 0]);
    assert_eq!(packet.len(), 2675);
    println!("71 categories and74 group associations match unmodified C# serializer byte for byte");
}

job_ability_bars.excerpt:
//! T011: every combat job's bar comes from its own job level. Switching away
//! must neither consume an unlocked skill nor reset the job's experience.
use osfr_tools::{
    inventory::Inventory,
    opening_abilities::OpeningAbilities,
    profiles::{ProfileState, Profiles},
};
use serde_json::json;
use sha2::{Digest, Sha256};
use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    path::{Path, PathBuf},
    sync::atomic::{AtomicU64, Ordering},
};

#[path = "common/job_playtest.rs"]
mod job_playtest;

use job_playtest::bar_ids;

static NEXT: AtomicU64 = AtomicU64::new(0);
const JOBS: [i32; 7] = [1, 11, 32, 12, 2, 43, 35]; // Adventurer 1 has no combat bar.

fn digest(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

struct Fixture(PathBuf);

impl Fixture {
    fn new() -> Self {
        let path = std::env::temp_dir().join(format!(
            "osfr-job-ability-bars-{}-{}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir(&path).unwrap();
        let zero = 0i32.to_le_bytes();
        let mut profiles = Vec::new();
        let mut inventory_profiles = Vec::new();
        let mut spans = vec![json!({"kind":"coins","offset":13,"length":4,
            "profile_id":0,"sha256":digest(&zero)})];
        let mut end = 17;
        for id in JOBS {
            // 12 rank bytes, 16 equipment bytes and four trailing bytes match
            // the profile proof layout used by the real loader.
            let mut raw = vec![0u8; 32];
            raw[0..4].copy_from_slice(&1i32.to_le_bytes());
            profiles.push(json!({
                "id": id,
                "offset": 0,
                "length": raw.len(),
                "sha256": digest(&raw),
                "serialized_hex": hex(&raw),
                "rank_offset": 0,
                "equipment_offset": 12,
                "equipment_length": 16
            }));
            inventory_profiles.push(json!({"id":id,"allowed_classes":[1],"slots":[]}));
            spans.push(json!({"kind":"equipment","offset":end,"length":4,
                "profile_id":id,"sha256":digest(&zero)}));
            end += 4;
        }
        spans.push(json!({"kind":"items","offset":end,"length":4,
            "profile_id":0,"sha256":digest(&zero)}));
        fs::write(
            path.join("profiles.json"),
            serde_json::to_vec(&json!({
                "schema_version": 1,
                "active_offset": 0,
                "active_sha256": digest(&1i32.to_le_bytes()),
                "profiles": profiles,
                "default_state": {
                    "version": 1,
                    "active": 11,
                    "unlocked": JOBS,
                    "experience": {}
                },
                "starter_items": {}
            }))
            .unwrap(),
        )
        .unwrap();
        fs::write(
            path.join("inventory.json"),
            serde_json::to_vec(&json!({
                "schema_version": 1,
                "player_guid": 1,
                "default_state": {"coins":0,"items":[],"equipment":[]},
                "profiles": inventory_profiles,
                "spans": spans,
                "definitions": []
            }))
            .unwrap(),
        )
        .unwrap();
        Self(path)
    }

    fn profiles(&self, experience: &BTreeMap<i32, u32>) -> Profiles {
        Profiles::load(
            &self.0,
            Some(ProfileState {
                version: 1,
                active: 11,
                unlocked: JOBS.into_iter().collect::<BTreeSet<_>>(),
                experience: experience.clone(),
            }),
        )
        .unwrap()
    }

    fn inventory(&self) -> Inventory {
        Inventory::load(&self.0, None).unwrap()
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn roster() -> OpeningAbilities {
    let content = Path::new(env!("CARGO_MANIFEST_DIR")).join("data/content");
    let mut abilities = OpeningAbilities::load(&content).unwrap();
    abilities
        .load_job_abilities(&content.join("job_abilities.json"))
        .unwrap();
    abilities
}

fn level(profiles: &Profiles, id: i32) -> u32 {
    (1 + profiles.state().experience.get(&id).copied().unwrap_or(0) / 100).min(20)
}

#[test]
fn switching_jobs_keeps_each_jobs_level_and_unlocked_bar() {
    let fixture = Fixture::new();
    let experience: BTreeMap<i32, u32> = [
        (1, 0),
        (11, 1400), // Medic 15
        (32, 900),  // Warrior 10
        (12, 1900), // Wizard 20
        (2, 900),   // Ninja 10
        (43, 400),  // Brawler 5
        (35, 1400), // Archer 15
    ]
    .into_iter()
    .collect();
    let mut profiles = fixture.profiles(&experience);
    let inventory = fixture.inventory();
    let abilities = roster();
    let levels: BTreeMap<i32, u32> = JOBS.iter().map(|id| (*id, level(&profiles, *id))).collect();
    let canonical: BTreeMap<i32, Vec<Vec<u8>>> = JOBS
        .iter()
        .map(|id| (*id, abilities.activation(*id, levels[id]).unwrap()))
        .collect();

    // T421: Brawler at 5 has Leg Sweep (row 1) and Rock Toss (row 2) with no
    // blank button before them; Pummel opens row 3 at 10, and rows 4-7, which
    // the client never draws, stay empty.
    let brawler = bar_ids(&canonical[&43]);
    assert_eq!(&brawler[..4], &[Some(4895), Some(62018), Some(62024), None]);
    assert!(brawler[4..].iter().all(Option::is_none));

    // Switching through every combat job and the non-combat Adventurer returns
    // exactly the same job bar each time; experience and levels stay intact.
    let switches = [
        11, 32, 12, 2, 43, 35, 1, 35, 43, 2, 12, 32, 11, 1, 11, 32, 12, 2, 43, 35,
    ];
    for id in switches {
        let packet = profiles.select(id, &inventory).unwrap();
        assert_eq!(&packet[..4], &[38, 0, 21, 0]);
        assert_eq!(profiles.active(), id);
        assert_eq!(level(&profiles, id), levels[&id], "job {id} level");
        assert_eq!(
            abilities.activation(id, level(&profiles, id)).unwrap(),
            canonical[&id],
            "job {id} bar after switching"
        );
        assert_eq!(
            profiles.state().experience,
            experience,
            "job {id} switch changed experience"
        );
    }

    // Adventurer clears all eight slots rather than leaving the Medic bar up.
    let empty = bar_ids(&canonical[&1]);
    assert!(empty.iter().all(Option::is_none));
    assert_eq!(canonical[&1].len(), 1);
    assert_eq!(&canonical[&1][0][12..], &[0; 32]);
}

job_basic_attacks.excerpt:
//! T010: each combat job starts with its client-derived weapon and can defeat
//! a cave enemy through the ordinary action-bar packet.
//!
//! The test content is the preserved private opening package. Its profile
//! starter lists predate the Ninja, Warrior and Wizard weapons, so this also
//! covers the reconstructed (R) fallback to the canonical basic-attack row.
use osfr_tools::{
    abilities::equipped_weapon_matches,
    account_store::AccountRole,
    character_store::CharacterState,
    chat,
    encounter::EncounterPhase,
    gameplay::{Gameplay, GameplayState},
    inventory::Inventory,
};
use serde_json::Value;
use std::{
    fs,
    path::{Path, PathBuf},
    sync::atomic::{AtomicU64, Ordering},
};

#[path = "common/job_playtest.rs"]
mod job_playtest;

static SERIAL: AtomicU64 = AtomicU64::new(0);

const COMBAT_JOBS: [(i32, i32, i32); 6] = [
    (2, 75091, 6),
    (11, 4622, 27),
    (12, 4914, 10),
    (32, 29963, 17),
    (35, 4266, 18),
    (43, 75030, 71),
];

struct Fixture(PathBuf);

impl Fixture {
    fn new() -> Self {
        let source = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../lab/references/opening-anvil-placement-v1/content");
        let path = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(format!(
            "t010-combat-{}-{}",
            std::process::id(),
            SERIAL.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir_all(&path).unwrap();
        for entry in fs::read_dir(source).unwrap() {
            let source = entry.unwrap().path();
            if source.is_file() {
                fs::copy(&source, path.join(source.file_name().unwrap())).unwrap();
            }
        }
        // The private campaign carries the first three jobs only. Use the
        // shipped canonical roster to exercise all six without changing the
        // pinned package on disk.
        fs::copy(
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("data/content/opening-abilities.json"),
            path.join("opening-abilities.json"),
        )
        .unwrap();
        job_playtest::install_starter_weapon_definitions(&path);
        job_playtest::install_starter_outfits(&path);
        patch_encounter(&path);
        Self(path)
    }

    fn content(&self) -> &Path {
        &self.0
    }
}

/// One harmless 300 HP target makes each test about the job's weapon and
/// action-bar path, not four separate dungeon objectives.
fn patch_encounter(path: &Path) {
    let encounter_path = path.join("encounters.json");
    let mut encounters: Value =
        serde_json::from_slice(&fs::read(&encounter_path).unwrap()).unwrap();
    let cave = encounters["dungeons"]
        .as_array_mut()
        .unwrap()
        .iter_mut()
        .find(|dungeon| dungeon["id"] == 411)
        .expect("opening cave 411 exists");
    cave["enemies"].as_array_mut().unwrap().truncate(1);
    cave["enemies"][0]["max_health"] = serde_json::json!(300);
    cave["enemies"][0]["damage"] = serde_json::json!(0);
    fs::write(encounter_path, serde_json::to_vec(&encounters).unwrap()).unwrap();
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn command(family: u16, sub: u16, fields: &[i32]) -> Vec<u8> {
    [
        family.to_le_bytes().to_vec(),
        sub.to_le_bytes().to_vec(),
        fields
            .iter()
            .flat_map(|value| value.to_le_bytes())
            .collect(),
    ]
    .concat()
}

fn basic(target: u64) -> Vec<u8> {
    [command(36, 10, &[1, 0, 0]), target.to_le_bytes().to_vec()].concat()
}

fn hit(out: &osfr_tools::gameplay::Outcome) -> bool {
    out.replies.iter().any(|packet| {
        packet.starts_with(&[32, 0, 7, 0])
            && packet.get(4..12) == Some(1_u64.to_le_bytes().as_slice())
    })
}

fn fresh_game(fixture: &Fixture, job: i32) -> (Gameplay, CharacterState, GameplayState) {
    let base = Gameplay::load(fixture.content(), None).unwrap();
    let mut seed = base.state();
    let profiles = seed.profiles.as_mut().unwrap();
    profiles.unlocked.extend([2, 11, 12, 32, 35, 43]);
    profiles.active = 1;
    for equipment in &mut seed.inventory.equipment {
        if equipment.profile_id == job && equipment.slot == 7 {
            equipment.item_id = 0;
        }
    }
    let location = CharacterState {
        guid: 1,
        zone_id: 0,
        position: [0.0; 3],
        rotation: [0.0; 3],
    };
    let mut game = Gameplay::load(fixture.content(), Some(seed.clone())).unwrap();
    game.set_dev_tools(true);
    game.set_role(AccountRole::Admin);
    let out = game
        .handle_in_world(&command(26, 13, &[job]), &location, 100)
        .unwrap();
    assert!(
        out.replies
            .iter()
            .any(|packet| packet.starts_with(&[38, 0, 21, 0])),
        "job {job} activation"
    );
    (game, location, seed)
}

fn equipped_weapon(fixture: &Fixture, game: &Gameplay, job: i32, class: i32) -> i32 {
    let state = game.state().inventory;
    let equipped = state
        .equipment
        .iter()
        .find(|entry| entry.profile_id == job && entry.slot == 7)
        .expect("the job has a weapon slot");
    assert_ne!(equipped.item_id, 0, "job {job} has a starter weapon");
    let item = state
        .items
        .iter()
        .find(|item| item.id == equipped.item_id)
        .expect("equipped weapon instance exists");
    let definition = item.definition_id;
    let inventory = Inventory::load(fixture.content(), Some(state)).unwrap();
    assert!(
        equipped_weapon_matches(&inventory, job, Some(class)),
        "job {job} starter weapon passes the live cast gate"
    );
    definition
}

fn start_cave(game: &mut Gameplay, location: &CharacterState) -> ([f32; 3], u64, u32) {
    let out = game
        .handle_in_world(&chat::local_request("realm battle 411"), location, 200)
        .unwrap();
    assert!(!out.replies.is_empty(), "opening cave 411 exists");
    let active = game
        .state()
        .encounter
        .and_then(|encounter| encounter.active)
        .expect("the cave encounter starts");
    let enemy = active.enemies.first().expect("the cave has an enemy");
    (enemy.position, enemy.guid, enemy.health)
}

fn kill_with_basic(
    game: &mut Gameplay,
    location: &CharacterState,
    target: u64,
    starting_health: u32,
) {
    for attempt in 0..16 {
        let out = game
            .handle_in_world(&basic(target), location, 1_000 + attempt * 700)
            .unwrap();
        if attempt == 0 {
            assert!(hit(&out), "the basic attack produces a player hit");
        }
        let encounter = game.state().encounter.unwrap();
        let enemy = encounter
            .active
            .as_ref()
            .unwrap()
            .enemies
            .iter()
            .find(|enemy| enemy.guid == target)
            .unwrap();
        assert!(
            enemy.health < starting_health,
            "job basic attack dealt damage"
        );
        if encounter.active.as_ref().unwrap().phase == EncounterPhase::Won {
            assert_eq!(enemy.health, 0);
            return;
        }
    }
    panic!("job basic attack did not defeat the cave enemy");
}

fn job_kills_cave_enemy(job: i32, weapon: i32, class: i32) {
    let fixture = Fixture::new();
    let (mut game, mut location, _) = fresh_game(&fixture, job);
    assert_eq!(
        equipped_weapon(&fixture, &game, job, class),
        weapon,
        "job {job} starter weapon"
    );
    let (position, target, health) = start_cave(&mut game, &location);
    location.zone_id = 411;
    location.position = position;
    game.initialize_world(&location, 300).unwrap();
    kill_with_basic(&mut game, &location, target, health);
}

macro_rules! starter_test {
    ($name:ident, $job:expr, $weapon:expr, $class:expr) => {
        #[test]
        fn $name() {
            job_kills_cave_enemy($job, $weapon, $class);
        }
    };
}

starter_test!(ninja_starter_weapon_kills_cave_enemy, 2, 75091, 6);
starter_test!(medic_starter_weapon_kills_cave_enemy, 11, 4622, 27);
starter_test!(wizard_starter_weapon_kills_cave_enemy, 12, 4914, 10);
starter_test!(warrior_starter_weapon_kills_cave_enemy, 32, 29963, 17);
starter_test!(archer_starter_weapon_kills_cave_enemy, 35, 4266, 18);
starter_test!(brawler_starter_weapon_kills_cave_enemy, 43, 75030, 71);

#[test]
fn shipped_rows_name_each_jobs_starter_weapon() {
    let rows: Value =
        serde_json::from_str(include_str!("../data/content/opening-abilities.json")).unwrap();
    for (job, weapon, class) in COMBAT_JOBS {
        let row = rows["basics"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["profile_id"] == job)
            .unwrap_or_else(|| panic!("profile {job} basic row"));
        assert_eq!(row["weapon_definition_id"], weapon, "profile {job}");
        assert_eq!(row["weapon_class"], class, "profile {job}");
    }
}

