            let mut bytes = vec![0x5a; CLIENT_DATA_PAYLOAD_LEN];
            bytes[77..81].copy_from_slice(&0x2a6ac44au32.to_le_bytes());
            bytes[81..85].copy_from_slice(&1u32.to_le_bytes());
