            stderr.contains("loopback gateway, or a private-network one"),
            refused,
            "{gateway}: {stderr}"
        );
    }
    // With --allow-lan a private gateway passes this gate (the run then stops on missing resources).
    let result = Command::new(env!("CARGO_BIN_EXE_osfr-login"))
        .args([
            "--bind",
            "127.0.0.1:0",
            "--gateway",
            "100.64.0.1:20041",
            "--allow-lan",
        ])
        .output()
        .unwrap();
