        (1, REFUSED),
        "owned wins over a short balance"
    );
    let unowned = poor.handle(&buy(2, SKELETAL_DRAGON)).unwrap();
    assert_eq!(
        order_result(&unowned.replies),
        (2, station_cash::ORDER_INSUFFICIENT_SC),
        "an unowned ride still reports the s

