    );
    *now += 10;
    // No completion line is recovered for 3090005; keep the documented 0 gap.
    release_end_screen(game, greyli, VITAMINS, GREYLI, 0, *now);
    *now += 10;
    finish_quest(
        game,
        greyli,
        VITAMINS,
        MEDIC,
        VITAMIN_COINS,
        VITAMIN_XP,
        *now,
