const TITLE: u32 = 23_217;
const DESCRIPTION: u32 = 23_218;
const END_TEXT: u32 = 23_219;
const ALL_I_GOT_INTRO: u32 = 76_086;
const ALL_I_GOT_TITLE: u32 = 76_087;
