#[test]
fn payload_packet_matches_pinned_original_framing() {
    let packet = payload_packet(FIRST_INSTANCE, "OnConnectMsg").unwrap();
    let mut expected = vec![39, 0, 14];
    expected.extend(FIRST_INSTANCE.to_le_bytes());
