mining_dead_board.excerpt:
//! Bounded regression for the captured dead board (native run 125556): a
//! chainless mining board with a collectable parked on the bottom playable
//! row must still rebuild like the original
//! `ServerGrid.updateCurrentGridArray` (`if(!HasMove()) LevelReshuffle()`),
//! on both the chain-update and collect-update paths. `has_bottom_collectable`
//! must never suppress the rebuild the original performs.
//!
//! Every fixture is synthetic and private: no user save, native client, gateway state or shared content is read or written.
use osfr_tools::mining::{
    Type8BoardSpec, Type8Engine, Type8Goal, Type8Kind, Type8Outcome, Type8Phase, Type8Run,
    Type8State, MINING_GAME_ID, SIDE,
};
use serde_json::json;
use std::fs;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};

const LEFT: usize = 3;
const TOP: usize = 3;
const PLAYABLE: usize = 8;
const BOTTOM: usize = TOP + PLAYABLE - 1;
const PROFILE: i32 = 14;
const FIRST_INSTANCE: i32 = 18_000_001;
const INSTANCE: i32 = 18_000_002;
const ORE: u16 = 601;
const ORE_TWO: u16 = 602;
const ORE_X: usize = 8;
const ORE_TWO_X: usize = 10;
const COLLECT_MESSAGE: &str = "OnLevelEventMsg\t50\t8\t10";
const CHAIN_MESSAGE: &str = "OnChainMsg\t3,3,4,3,5,3,";

static NEXT: AtomicU64 = AtomicU64::new(0);

struct Fixture {
    directory: PathBuf,
}

impl Fixture {
    fn new(spec: &Type8BoardSpec) -> Self {
        let directory = std::env::temp_dir().join(format!(
            "osfr-mining-dead-board-{}-{}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir(&directory).unwrap();
        let content = json!({
            "schema_version": 1,
            "game_id": MINING_GAME_ID,
            "profile_id": PROFILE,
            "name_id": 7910,
            "description_id": 7911,
            "icon_id": 909,
            "spec": spec,
        });
        fs::write(
            directory.join("mining.json"),
            serde_json::to_vec(&content).unwrap(),
        )
        .unwrap();
        Self { directory }
    }

    fn load(&self, state: Option<Type8State>) -> Type8Engine {
        Type8Engine::load(
            &self.directory,
            "mining.json",
            MINING_GAME_ID,
            FIRST_INSTANCE,
            state,
        )
        .unwrap()
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = fs::remove_file(self.directory.join("mining.json"));
        let _ = fs::remove_dir(&self.directory);
    }
}

fn spec() -> Type8BoardSpec {
    let mut shape = vec![0_i32; SIDE * SIDE];
    for y in TOP..TOP + PLAYABLE {
        for x in LEFT..LEFT + PLAYABLE {
            shape[y * SIDE + x] = 1;
        }
    }
    for x in LEFT..LEFT + PLAYABLE {
        shape[(TOP + PLAYABLE) * SIDE + x] = 4;
    }
    Type8BoardSpec {
        width: SIDE,
        height: SIDE,
        shape,
        selectable: vec![401, 402, 403, 404],
        collectable: vec![ORE, ORE_TWO],
        tiles: vec![
            Type8Kind {
                value: 401,
                category: 400,
                icon_id: 1,
            },
            Type8Kind {
                value: ORE,
                category: 600,
                icon_id: 909,
            },
        ],
        goals: vec![goal(0, ORE, 15, 1), goal(1, ORE_TWO, 6, 1)],
        outputs: Vec::new(),
        duration_seconds: 180,
        seed: 18,
        wildcard_percent: 0,
        collectable_percent: 0,
        blocker_percent: 0,
        powerup_percent: 0,
        meter_id: 0,
        reconstructed_rules: true,
        rule_notice: "Synthetic private fixture. Original server level tables unrecovered.".into(),
    }
}

fn goal(index: i32, value: u16, quota: u32, per_reward: u32) -> Type8Goal {
    Type8Goal {
        index,
        value,
        quota,
        per_reward,
        icon_id: 909,
    }
}

/// Pattern with period four along both axes: orthogonal neighbours never match,
/// so the playable area holds no connected selectable group by construction.
fn pattern(x: usize, y: usize) -> u16 {
    401 + ((x + y) % 4) as u16
}

fn board_with(chain: bool) -> Vec<u16> {
    let mut board = vec![0_u16; SIDE * SIDE];
    for y in TOP..TOP + PLAYABLE {
        for x in LEFT..LEFT + PLAYABLE {
            board[y * SIDE + x] = pattern(x, y);
        }
    }
    if chain {
        // Exactly one connected group over two tiles: the 403 chain that the
        // accepted `OnChainMsg` consumes, mirroring the captured run's single
        // legal chain on an otherwise chainless board.
        for x in LEFT..LEFT + 3 {
            board[TOP * SIDE + x] = 403;
        }
    }
    // Both captured bottom-row ores: (10,8)=602-style goal collectable and
    // (10,10)=601 directly above dropzone cells (row 11).
    board[BOTTOM * SIDE + ORE_X] = ORE;
    board[BOTTOM * SIDE + ORE_TWO_X] = ORE_TWO;
    board
}

/// Queue with a controlled refill prefix; the length stays above `QUEUE_MIN`
/// (50) so gravity never appends an rng batch and the refill stays exact.
fn queue(prefix: &[u16]) -> Vec<u16> {
    let mut queue = prefix.to_vec();
    queue.resize(60, 402);
    queue
}

fn dead_state(board: Vec<u16>, tile_queue: Vec<u16>) -> Type8State {
    Type8State {
        version: 1,
        next_instance_id: INSTANCE + 1,
        completed: 0,
        active: Some(Type8Run {
            instance_id: INSTANCE,
            phase: Type8Phase::Playing,
            idle: vec![true; board.len()],
            board,
            tile_queue,
            random_queue: Vec::new(),
            rng: 3_309_872_643,
            collected: vec![0, 0],
            score: 3000,
            remaining_ms: 172_329,
            wall_ms: 973_839,
            paused: false,
            chains: 6,
            reshuffles: 0,
            end_sent: false,
        }),
    }
}

fn header(sub: u8, id: i32, game: i32) -> Vec<u8> {
    let mut b = 39_u16.to_le_bytes().to_vec();
    b.push(sub);
    for n in [id, -1, game] {
        b.extend(n.to_le_bytes());
    }
    b
}

fn client_payload(id: i32, s: &str) -> Vec<u8> {
    let mut b = header(14, id, -1);
    b.extend(((s.len() + 1) as i32).to_le_bytes());
    b.extend(s.as_bytes());
    b.push(0);
    b
}

fn payload_text(packet: &[u8]) -> Option<String> {
    if packet.len() < 19 || packet[0..3] != [39, 0, 14] {
        return None;
    }
    let n = i32::from_le_bytes(packet[15..19].try_into().unwrap());
    assert!(n >= 1);
    let end = 19 + n as usize - 1;
    assert_eq!(packet.len(), end + 1);
    assert_eq!(packet[end], 0);
    Some(String::from_utf8(packet[19..end].to_vec()).unwrap())
}

fn texts(outcome: &Type8Outcome) -> Vec<String> {
    outcome
        .replies
        .iter()
        .filter_map(|p| payload_text(p))
        .collect()
}

fn has_text(outcome: &Type8Outcome, prefix: &str) -> bool {
    texts(outcome)
        .iter()
        .any(|t| t == prefix || t.starts_with(&format!("{prefix}\t")))
}

/// Captured dead-board regression, chain-update path: an accepted chain leaves
/// a chainless board with a collectable on the bottom playable row. The
/// original rebuilds (`if(!HasMove()) LevelReshuffle()`); the bottom ore must
/// not suppress that rebuild.
#[test]
fn chainless_board_with_bottom_ore_rebuilds_after_chain() {
    let fixture = Fixture::new(&spec());
    // Refill for columns 5, 4, 3 (gravity scans right to left): keeps the
    // quarter pattern intact, so the post-chain board is genuinely chainless.
    let mut engine = fixture.load(Some(dead_state(board_with(true), queue(&[404, 403, 401]))));
    let out = engine
        .handle(&client_payload(INSTANCE, CHAIN_MESSAGE))
        .unwrap();
    let run = engine.state().active.as_ref().unwrap();
    assert_eq!(run.chains, 7);
    assert_eq!(run.collected, vec![0, 0]);
    assert_eq!(
        run.reshuffles, 1,
        "chainless board with a bottom collectable must rebuild like the original"
    );
    assert!(
        has_text(&out, "OnLevelEventMsg\t11"),
        "reshuffle notice must reach the client"
    );
    assert!(
        has_text(&out, "OnBuildMapMsg"),
        "rebuilt board must be sent to the client"
    );
}

/// Captured dead-board regression, collect-update path: a client fall for one
/// bottom ore leaves a second bottom ore and a chainless board. The original
/// still rebuilds; the remaining bottom ore must not suppress it.
#[test]
fn chainless_board_with_bottom_ore_rebuilds_after_collect() {
    let fixture = Fixture::new(&spec());
    // Column 8 refill after the collected tile shifts the column down one row.
    let mut engine = fixture.load(Some(dead_state(board_with(false), queue(&[402]))));
    let out = engine
        .handle(&client_payload(INSTANCE, COLLECT_MESSAGE))
        .unwrap();
    let run = engine.state().active.as_ref().unwrap();
    assert_eq!(run.collected, vec![1, 0]);
    assert_eq!(run.score, 3500);
    assert!(
        has_text(&out, "OnQuotaUpdateMsg\t0"),
        "collect must update the goal quota"
    );

mining_idle.excerpt:
//! Mining idle-acknowledgement regression: `OnIdleMsg` accepts any non-empty
//! coordinate list.
//!
//! Recovered wiring:
//! - `core/Grid.UpdateIdle` (1356-1363) sends the pending `sNowIdle` string as
//!   soon as it is non-empty;
//! - `GameClientNetwork.SendIdle` (26-29) wraps it as `OnIdleMsg`;
//! - `GameLevel.OnIdleMsg` (543-552) splits on `,`, pops the trailing empty
//!   field and forwards every remaining pair to `ServerGrid.NowIdle`;
//! - `ServerGrid.NowIdle` (78-102) loops `length / 2` entries with no minimum.
//!
//! A single fired tile (`"4,4,"`) is therefore a complete, legal message; only
//! the chain path has the recovered three-tile minimum.
//!
//! Fixtures are synthetic: the content file comes from the production
//! `write_content` and every state is built in this file. No save, native client
//! or gateway state is read.

use osfr_tools::mining::{
    CONTENT_FILE, FIRST_MINING_INSTANCE, MINING_GAME_ID, SIDE, TILE_SELECTABLE_START, Type8Engine,
    Type8Phase, Type8Run, Type8State, write_content,
};
use std::fs;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};

const LEFT: usize = 3;
const TOP: usize = 3;
const PLAYABLE: usize = 8;
const BACKGROUND: u16 = 601;

static NEXT: AtomicU64 = AtomicU64::new(0);

struct Fixture {
    directory: PathBuf,
}

impl Fixture {
    fn new() -> Self {
        let directory = std::env::temp_dir().join(format!(
            "osfr-mining-idle-{}-{}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir(&directory).unwrap();
        write_content(&directory, MINING_GAME_ID).expect("mining content writes");
        Self { directory }
    }

    fn load(&self, state: Type8State) -> Type8Engine {
        Type8Engine::load(
            &self.directory,
            CONTENT_FILE,
            MINING_GAME_ID,
            FIRST_MINING_INSTANCE,
            Some(state),
        )
        .expect("the synthetic state loads")
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = fs::remove_file(self.directory.join(CONTENT_FILE));
        let _ = fs::remove_dir(&self.directory);
    }
}

fn header(sub: u8, id: i32, game: i32) -> Vec<u8> {
    let mut bytes = 39_u16.to_le_bytes().to_vec();
    bytes.push(sub);
    for number in [id, -1, game] {
        bytes.extend(number.to_le_bytes());
    }
    bytes
}

fn client_payload(id: i32, text: &str) -> Vec<u8> {
    let mut bytes = header(14, id, -1);
    bytes.extend(((text.len() + 1) as i32).to_le_bytes());
    bytes.extend(text.as_bytes());
    bytes.push(0);
    bytes
}

fn index(x: usize, y: usize) -> usize {
    y * SIDE + x
}

/// Playable rectangle filled with one goal collectable so no accidental chain
/// exists; the dropzone row stays as the content writes it.
fn background() -> Vec<u16> {
    let mut board = vec![0_u16; SIDE * SIDE];
    for y in TOP..TOP + PLAYABLE {
        for x in LEFT..LEFT + PLAYABLE {
            board[index(x, y)] = BACKGROUND;
        }
    }
    for x in LEFT..LEFT + PLAYABLE {
        board[index(x, TOP + PLAYABLE)] = 100;
    }
    board
}

fn state_with(
    board: Vec<u16>,
    idle_marks: &[(usize, usize)],
    phase: Type8Phase,
    paused: bool,
) -> Type8State {
    let mut idle = vec![true; SIDE * SIDE];
    for &(x, y) in idle_marks {
        idle[index(x, y)] = false;
    }
    Type8State {
        version: 1,
        next_instance_id: FIRST_MINING_INSTANCE + 1,
        completed: u32::from(matches!(phase, Type8Phase::Won)),
        active: Some(Type8Run {
            instance_id: FIRST_MINING_INSTANCE,
            phase,
            board,
            idle,
            tile_queue: vec![TILE_SELECTABLE_START; 64],
            random_queue: Vec::new(),
            rng: 1,
            collected: vec![0, 0],
            score: 0,
            remaining_ms: 30_000,
            wall_ms: 0,
            paused,
            chains: 0,
            reshuffles: 0,
            end_sent: false,
        }),
    }
}

fn idle_at(engine: &Type8Engine, x: usize, y: usize) -> bool {
    engine.state().active.as_ref().unwrap().idle[index(x, y)]
}

#[test]
fn single_tile_idle_ack_is_accepted() {
    // RED before the fix: the shared chain parser demanded three pairs.
    let fixture = Fixture::new();
    let mut engine = fixture.load(state_with(
        background(),
        &[(4, 4)],
        Type8Phase::Playing,
        false,
    ));
    assert!(!idle_at(&engine, 4, 4), "fixture starts busy");
    engine
        .handle(&client_payload(FIRST_MINING_INSTANCE, "OnIdleMsg\t4,4,"))
        .expect("a single fired tile is a complete idle acknowledgement");
    assert!(idle_at(&engine, 4, 4));
}

#[test]
fn two_tile_idle_ack_is_accepted() {
    let fixture = Fixture::new();
    let mut engine = fixture.load(state_with(
        background(),
        &[(4, 4), (5, 4)],
        Type8Phase::Playing,
        false,
    ));
    engine
        .handle(&client_payload(
            FIRST_MINING_INSTANCE,
            "OnIdleMsg\t4,4,5,4,",
        ))
        .expect("two fired tiles are a complete idle acknowledgement");
    assert!(idle_at(&engine, 4, 4));
    assert!(idle_at(&engine, 5, 4));
}

#[test]
fn chain_still_requires_three_tiles() {
    // The three-tile minimum belongs to the chain path only.
    let fixture = Fixture::new();
    let mut board = background();
    for x in [4, 5, 6] {
        board[index(x, 4)] = TILE_SELECTABLE_START;
    }
    let mut engine = fixture.load(state_with(board, &[], Type8Phase::Playing, false));
    let before = engine.state().clone();
    assert!(
        engine
            .handle(&client_payload(
                FIRST_MINING_INSTANCE,
                "OnChainMsg\t4,4,5,4,"
            ))
            .is_err(),
        "a two-tile chain must stay refused"
    );
    assert!(
        engine
            .handle(&client_payload(FIRST_MINING_INSTANCE, "OnChainMsg\t4,4,"))
            .is_err(),
        "a one-tile chain must stay refused"
    );
    assert_eq!(engine.state(), &before);
    // The legal three-tile chain is still accepted.
    engine
        .handle(&client_payload(
            FIRST_MINING_INSTANCE,
            "OnChainMsg\t4,4,5,4,6,4,",
        ))
        .expect("the recovered three-tile chain still works");
}

#[test]
fn idle_ack_outside_the_board_is_refused_atomically() {
    let fixture = Fixture::new();
    let mut engine = fixture.load(state_with(
        background(),
        &[(4, 4)],
        Type8Phase::Playing,
        false,
    ));
    let before = engine.state().clone();
    assert!(
        engine
            .handle(&client_payload(
                FIRST_MINING_INSTANCE,
                "OnIdleMsg\t0,0,4,4,"
            ))
            .is_err(),
        "an out-of-board coordinate must be refused"
    );
    assert_eq!(engine.state(), &before, "refusal must not mark any tile");
}

#[test]
fn malformed_idle_lists_are_refused_and_change_nothing() {
    let fixture = Fixture::new();
    let mut engine = fixture.load(state_with(
        background(),
        &[(4, 4)],
        Type8Phase::Playing,
        false,
    ));
    let before = engine.state().clone();
    for malformed in [
        "OnIdleMsg\t4,4,5,",    // odd field count
        "OnIdleMsg\t4,4,,5,4,", // empty field
        "OnIdleMsg\t9999,4,",   // coordinate above the recovered bound
        "OnIdleMsg\tx,4,",      // non-numeric
        "OnIdleMsg\t,",         // no coordinate at all
    ] {
        assert!(
            engine
                .handle(&client_payload(FIRST_MINING_INSTANCE, malformed))
                .is_err(),
            "{malformed} must be refused"
        );
        assert_eq!(
            engine.state(),
            &before,
            "{malformed} must not mutate the run"
        );
    }
}

#[test]
fn idle_acks_keep_their_non_playing_behaviour() {
    let fixture = Fixture::new();
    // Terminal run: the message parses and is accepted, but no tile changes.
    let mut engine = fixture.load(state_with(background(), &[(4, 4)], Type8Phase::Won, false));
    let before = engine.state().clone();
    engine
        .handle(&client_payload(FIRST_MINING_INSTANCE, "OnIdleMsg\t4,4,"))
        .expect("a terminal run still accepts a well-formed idle request");
    assert_eq!(engine.state(), &before);
    assert!(
        engine
            .handle(&client_payload(FIRST_MINING_INSTANCE, "OnIdleMsg\t4,4,,"))
            .is_err(),
        "malformed input is refused in every phase"
    );
    assert_eq!(engine.state(), &before);

    // Paused play keeps applying idle acknowledgements, as before the fix.
    let mut engine = fixture.load(state_with(
        background(),
        &[(4, 4)],
        Type8Phase::Playing,
        true,
    ));
    engine
        .handle(&client_payload(FIRST_MINING_INSTANCE, "OnIdleMsg\t4,4,"))
        .expect("a paused level still acknowledges idle tiles");
    assert!(idle_at(&engine, 4, 4));
}

