//! Mining's shared lifecycle, payout and quest-event acceptance.
//!
//! Fixtures are private and synthetic. The seeded whole-round case drives the
//! production Type8 engine, lifecycle manager and reward API without a client.

use osfr_tools::{
    inventory::{Inventory, InventoryState},
    minigame::RunState,
    mining::{
        CONTENT_FILE, FIRST_MINING_INSTANCE, MINER_PROFILE_ID, MINING_GAME_ID, SIDE, TILE_WILDCARD,
        Type8Engine, Type8Phase, Type8Run, lifecycle::MiningActivityOutcome,
        lifecycle::MiningLifecycle, write_content,
    },
    profiles::ProfileState,
    quest_engine::QuestEvent,
    rewards::RewardState,
};
use serde_json::{Value, json};
use sha2::{Digest, Sha256};
use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    path::PathBuf,
    sync::atomic::{AtomicU64, Ordering},
};

const GUID: u64 = 800;
const ORE_ITEM: i32 = 2739;
const LEFT: usize = 3;
const TOP: usize = 3;
const BOTTOM: usize = 10;
const RIGHT: usize = 10;

static NEXT: AtomicU64 = AtomicU64::new(0);

struct Fixture {
    path: PathBuf,
}

impl Fixture {
    fn new() -> Self {
        let path = std::env::temp_dir().join(format!(
            "osfr-mining-lifecycle-{}-{}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir(&path).unwrap();
        write_content(&path, MINING_GAME_ID).unwrap();
        let empty = 0_i32.to_le_bytes();
        let definition = [ORE_ITEM.to_le_bytes(), 8_i32.to_le_bytes()].concat();
        let content = json!({
            "schema_version": 1,
            "player_guid": GUID,
            "default_state": {
                "coins": 0,
                "items": [],
                "equipment": [],
                "next_instance_id": null
            },
            "profiles": [{"id": 1, "allowed_classes": [1], "slots": [3]}],
            "spans": [
                span("coins", 13, 0, &0_i32.to_le_bytes()),
                span("items", 17, 0, &empty),
                span("equipment", 21, 1, &empty)
            ],
            "definitions": [{
                "id": ORE_ITEM,
                "slot": 0,
                "class_id": 0,
                "default_tint": 0,
                "max_stack": -1,
                "model": "",
                "texture": "",
                "tint_alias": "dyetint",
                "effect": 0,
                "wield_type": 0,
                "serialized_hex": hex(&definition),
                "sha256": digest(&definition)
            }]
        });
        fs::write(
            path.join("inventory.json"),
            serde_json::to_vec(&content).unwrap(),
        )
        .unwrap();
        Self { path }
    }

    fn engine(&self) -> Type8Engine {
        Type8Engine::load(
            &self.path,
            CONTENT_FILE,
            MINING_GAME_ID,
            FIRST_MINING_INSTANCE,
            None,
        )
        .unwrap()
    }

    fn lifecycle(&self) -> MiningLifecycle {
        MiningLifecycle::new(self.engine(), GUID).unwrap()
    }

    fn rewards(&self, ore_count: u32) -> RewardState {
        let mut inventory = Inventory::load(&self.path, None).unwrap();
        if ore_count > 0 {
            inventory.grant(0, ORE_ITEM, ore_count).unwrap();
        }
        RewardState::new(
            inventory,
            ProfileState {
                version: 1,
                active: MINER_PROFILE_ID,
                unlocked: BTreeSet::from([MINER_PROFILE_ID]),
                experience: BTreeMap::new(),
            },
            8,
        )
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = fs::remove_file(self.path.join("inventory.json"));
        let _ = fs::remove_file(self.path.join(CONTENT_FILE));
        let _ = fs::remove_dir(&self.path);
    }
}

fn span(kind: &str, offset: usize, profile_id: i32, bytes: &[u8]) -> Value {
    json!({
        "kind": kind,
        "offset": offset,
        "length": bytes.len(),
        "profile_id": profile_id,
        "sha256": digest(bytes)
    })
}

fn digest(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn header(sub: u8, id: i32) -> Vec<u8> {
    let mut bytes = vec![39, 0, sub];
    for value in [id, -1, -1] {
        bytes.extend(value.to_le_bytes());
    }
    bytes
}

fn movie(id: i32, message: &str) -> Vec<u8> {
    let mut bytes = header(14, id);
    bytes.extend(((message.len() + 1) as i32).to_le_bytes());
    bytes.extend(message.as_bytes());
    bytes.push(0);
    bytes
}

fn acknowledge_idle(lifecycle: &mut MiningLifecycle, id: i32) {
    let Some(run) = lifecycle.activity_state().active.as_ref() else {
        return;
    };
    if run.phase != Type8Phase::Playing {
        return;
    }
    let mut idle = String::new();
    for y in TOP..=BOTTOM {
        for x in LEFT..=RIGHT {
            let index = y * SIDE + x;
            if run.board[index] != 0 && !run.idle[index] {
                idle.push_str(&format!("{x},{y},"));
            }
        }
    }
    if !idle.is_empty() {
        lifecycle
            .handle(&movie(id, &format!("OnIdleMsg\t{idle}")), None)
            .unwrap();
    }
}

fn begin_play(lifecycle: &mut MiningLifecycle) -> i32 {
    let offer = lifecycle.begin(MINER_PROFILE_ID).unwrap();
    assert_eq!(offer.state, Some(RunState::Offered));
    assert_eq!(offer.replies[0][..3], [39, 0, 16]);
    let id = FIRST_MINING_INSTANCE;
    let start = lifecycle.handle(&header(5, id), None).unwrap();
    assert_eq!(start.state, Some(RunState::Starting));
    assert_eq!(start.replies.len(), 2);
    lifecycle.handle(&movie(id, "OnConnectMsg"), None).unwrap();
    lifecycle
        .handle(&movie(id, "OnStartGameMsg"), None)
        .unwrap();
    lifecycle
        .handle(&movie(id, "OnStartLevelMsg"), None)
        .unwrap();
    assert_eq!(lifecycle.run_state(), Some(RunState::Playing));
    id
}

fn find_chain(run: &Type8Run) -> Option<Vec<(usize, usize)>> {
    const MAX_PATH_LEN: usize = 12;
    const NODE_BUDGET: usize = 50_000;

    type Rank = (bool, usize, usize, i32, usize, usize);

    fn rank(run: &Type8Run, path: &[(usize, usize)], ores: &[(usize, usize)]) -> Rank {
        let mut collect_now = false;
        let mut helped = 0;
        let mut cleared_total = 0;
        let mut remaining_min = None;
        for &(ore_row, ore_col) in ores {
            let cleared = path
                .iter()
                .filter(|&&(row, col)| {
                    col == ore_col && row > ore_row && run.board[row * SIDE + col] != 0
                })
                .count();
            if cleared == 0 {
                continue;
            }
            helped += 1;
            cleared_total += cleared;
            let total = ((ore_row + 1)..=BOTTOM)
                .filter(|&row| run.board[row * SIDE + ore_col] != 0)
                .count();
            let remaining = total.saturating_sub(cleared);
            remaining_min = Some(remaining_min.map_or(remaining, |old: usize| old.min(remaining)));
            collect_now |= remaining == 0;
        }
        (
            collect_now,
            helped,
            cleared_total,
            -(remaining_min.unwrap_or(0) as i32),
            path.len(),
            path.iter().map(|(row, _)| *row).max().unwrap_or(0),
        )
    }

    fn explore(
        run: &Type8Run,
        ores: &[(usize, usize)],
        path: &mut Vec<(usize, usize)>,
        seen: &mut BTreeSet<(usize, usize)>,
        reference: Option<u16>,
        budget: &mut i32,
        best: &mut Option<Vec<(usize, usize)>>,
        best_rank: &mut Option<Rank>,
    ) {
        *budget -= 1;
        if *budget < 0 {
            return;
        }
        if path.len() >= 3 && reference.is_some() {
            let candidate = rank(run, path, ores);
            if best_rank.is_none_or(|current| candidate > current) {
                *best_rank = Some(candidate);
                *best = Some(path.clone());
            }
        }
        if path.len() >= MAX_PATH_LEN {
            return;
        }
        let &(row, col) = path.last().unwrap();
        for (next_row, next_col) in [
            (row + 1, col),
            (row, col + 1),
            (row, col.wrapping_sub(1)),
            (row.wrapping_sub(1), col),
        ] {
            if !(TOP..=BOTTOM).contains(&next_row)
                || !(LEFT..=RIGHT).contains(&next_col)
                || seen.contains(&(next_row, next_col))
            {
                continue;
            }
            let index = next_row * SIDE + next_col;
            let cell = run.board[index];
            if !run.idle[index]
                || (!(401..=405).contains(&cell) && cell != TILE_WILDCARD)
                || (cell != TILE_WILDCARD && reference.is_some_and(|value| value != cell))
            {
                continue;
            }
            seen.insert((next_row, next_col));
            path.p

mining_move_detection.excerpt:
//! Mining `has_move` regression: wildcard false positives after a chain.
//!
//! Native run 143211 paused with 21 chains, every tile idle and one reshuffle already applied;
//! the client showed no legal path while the engine believed a move existed. Its snapshot
//! (`lab/runs/client-baseline-20261009T143211Z/character-chain21-no-move.json`, sha256
//! `e3885ebeaab33c9f15232f13a9e70333b4d8a8ccd24db8077b30d14927b1bd24`) has a wildcard 200 at
//! (3,3), a collectable 602 at (3,4) and a 403 at (4,3).
//!
//! The old `has_move` seeds a flood from the wildcard and treats *any* neighbour as a match
//! (`value == TILE_WILDCARD` short-circuits the value test), so the flood counts goals and
//! mixed-colour tiles and reports a move that does not exist. An exhaustive three-tile finder
//! over the snapshot returns zero legal paths.
//!
//! These vectors drive the real engine's post-chain path (`OnLevelEventMsg 50` -> collect ->
//! `gravity` -> `has_move`): a board with no legal three-tile path must reshuffle, a board with
//! one must not. `has_move` is a future-move check, so idle flags are ignored on purpose.
//!
//! Fixtures copy nothing shared: a private temp directory gets the standard `mining.json`, and
//! every state is either the frozen snapshot or a synthetic board built in this file.

use osfr_tools::mining::{
    self, FIRST_MINING_INSTANCE, MINING_GAME_ID, Type8Engine, Type8Phase, Type8Run, Type8State,
};
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::{
    fs,
    path::PathBuf,
    sync::atomic::{AtomicU64, Ordering},
};

const SIDE: usize = 14;
const LEFT: usize = 3;
const TOP: usize = 3;
const PLAYABLE: usize = 8;
const BOTTOM: usize = TOP + PLAYABLE - 1;
const TRIGGER_COLUMN: usize = 7;
const SNAPSHOT_SHA256: &str = "e3885ebeaab33c9f15232f13a9e70333b4d8a8ccd24db8077b30d14927b1bd24";

static NEXT: AtomicU64 = AtomicU64::new(0);

fn snapshot_path() -> PathBuf {
    std::env::var_os("OSFR_MINING_NO_MOVE_SNAPSHOT")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(
                "../../../lab/runs/client-baseline-20261009T143211Z/character-chain21-no-move.json",
            )
        })
}

struct Fixture {
    directory: PathBuf,
}

impl Fixture {
    fn new() -> Self {
        let directory = std::env::temp_dir().join(format!(
            "osfr-mining-move-{}-{}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir(&directory).unwrap();
        mining::write_content(&directory, MINING_GAME_ID).expect("mining content writes");
        Self { directory }
    }

    fn load(&self, state: Type8State) -> std::io::Result<Type8Engine> {
        Type8Engine::load(
            &self.directory,
            mining::CONTENT_FILE,
            MINING_GAME_ID,
            FIRST_MINING_INSTANCE,
            Some(state),
        )
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = fs::remove_file(self.directory.join(mining::CONTENT_FILE));
        let _ = fs::remove_dir(&self.directory);
    }
}

fn header(sub: u8, id: i32, game: i32) -> Vec<u8> {
    let mut bytes = 39_u16.to_le_bytes().to_vec();
    bytes.push(sub);
    for number in [id, -1, game] {
        bytes.extend(number.to_le_bytes());
    }
    bytes
}

/// Client `39/14` payload: current instance, two `-1` sentinels, length + text + NUL.
fn client_payload(id: i32, text: &str) -> Vec<u8> {
    let mut bytes = header(14, id, -1);
    bytes.extend(((text.len() + 1) as i32).to_le_bytes());
    bytes.extend(text.as_bytes());
    bytes.push(0);
    bytes
}

fn index(x: usize, y: usize) -> usize {
    y * SIDE + x
}

fn set(board: &mut [u16], x: usize, y: usize, value: u16) {
    board[index(x, y)] = value;
}

/// Playable area filled with a goal collectable so no accidental chain exists there.
fn background() -> Vec<u16> {
    let mut board = vec![0_u16; SIDE * SIDE];
    for y in TOP..TOP + PLAYABLE {
        for x in LEFT..LEFT + PLAYABLE {
            set(&mut board, x, y, 601);
        }
    }
    board
}

fn synthetic_state(board: Vec<u16>, idle: Vec<bool>, reshuffles: u32) -> Type8State {
    Type8State {
        version: 1,
        next_instance_id: FIRST_MINING_INSTANCE + 1,
        completed: 0,
        active: Some(Type8Run {
            instance_id: FIRST_MINING_INSTANCE,
            phase: Type8Phase::Playing,
            board,
            idle,
            tile_queue: vec![401; 64],
            random_queue: Vec::new(),
            rng: 1,
            collected: vec![0, 0],
            score: 0,
            remaining_ms: 30_000,
            wall_ms: 0,
            paused: true,
            chains: 1,
            reshuffles,
            end_sent: false,
        }),
    }
}

/// Sends the recovered fall event and returns the reshuffle counter afterwards.
fn fall_and_reshuffles(engine: &mut Type8Engine) -> u32 {
    let instance = engine
        .state()
        .active
        .as_ref()
        .expect("active run")
        .instance_id;
    engine
        .handle(&client_payload(
            instance,
            &format!("OnLevelEventMsg\t50\t{TRIGGER_COLUMN}\t{BOTTOM}"),
        ))
        .expect("fall event is accepted");
    engine.state().active.as_ref().unwrap().reshuffles
}

#[test]
#[ignore = "requires private native Mining snapshot"]
fn chain21_snapshot_with_no_legal_path_must_reshuffle() {
    let raw = fs::read(snapshot_path()).expect("the chain21 snapshot is readable");
    assert_eq!(
        format!("{:x}", Sha256::digest(&raw)),
        SNAPSHOT_SHA256,
        "the frozen chain21 snapshot changed"
    );
    let document: Value = serde_json::from_slice(&raw).unwrap();
    let mut state: Type8State = serde_json::from_value(document["gameplay"]["mining"].clone())
        .expect("mining state parses");
    let run = state
        .active
        .as_mut()
        .expect("the snapshot has an active run");
    assert!(run.idle.iter().all(|flag| *flag), "every tile is idle");
    assert_eq!(run.reshuffles, 1, "the snapshot already reshuffled once");
    // Trigger reachability: the engine only collects a goal collectable from the bottom row, and
    // column 7 still has no three-tile path after the refill.
    set(&mut run.board, TRIGGER_COLUMN, BOTTOM, 601);
    run.tile_queue = vec![401; 64];

    let fixture = Fixture::new();
    let mut engine = fixture.load(state).expect("snapshot state loads");
    assert_eq!(
        fall_and_reshuffles(&mut engine),
        2,
        "a board with no legal three-tile path must reshuffle"
    );
}

#[test]
fn wildcard_star_between_two_colours_has_no_move() {
    let mut board = background();
    set(&mut board, 3, 3, 200);
    set(&mut board, 3, 4, 401);
    set(&mut board, 4, 3, 402);
    let fixture = Fixture::new();
    let mut engine = fixture
        .load(synthetic_state(board, vec![true; SIDE * SIDE], 1))
        .unwrap();
    assert_eq!(fall_and_reshuffles(&mut engine), 2);
}

#[test]
fn wildcard_next_to_a_goal_has_no_move() {
    let mut board = background();
    set(&mut board, 3, 3, 200);
    set(&mut board, 3, 4, 602);
    set(&mut board, 4, 3, 403);
    let fixture = Fixture::new();
    let mut engine = fixture
        .load(synthetic_state(board, vec![true; SIDE * SIDE], 1))
        .unwrap();
    assert_eq!(fall_and_reshuffles(&mut engine), 2);
}

#[test]
fn valid_three_tile_paths_keep_the_board_and_ignore_idle() {
    let cases: [(&str, [(usize, usize, u16); 3]); 4] = [
        ("straight", [(5, 4, 401), (5, 5, 401), (5, 6, 401)]),
        ("bent", [(5, 4, 402), (5, 5, 402), (6, 5, 402)]),
        ("wildcard bridge", [(5, 4, 401), (5, 5, 200), (5, 6, 401)]),
        ("pure wildcard", [(5, 4, 200), (5, 5, 200), (5, 6, 200)]),
    ];
    for (name, cells) in cases {
        let mut board = background();
        let mut idle = vec![true; SIDE * SIDE];
        for (x, y, value) in cells {
            set(&mut board, x, y, value);
            idle[index(x, y)] = false; // future moves ignore idle
        }
        let fixture = Fixture::new();
        let mut engine = fixture
            .load(synthetic_state(board, idle, 1))
            .unwrap_or_else(|error| panic!("{name}: state loads: {error}"));
        assert_eq!(
            fall_and_reshuffles(&mut engine),
            1,
            "{name}: a legal three-tile path must not reshuffle"
        );
    }
}

mining_powerups.excerpt:
//! Clickable Mining powerup (`950..=953`) behavioral tests.
//!
//! Every fixture is synthetic and private: no user save, native client or gateway state is read or written. The recovered originals are
//! `core/ServerGrid.as` `StartWildTiles`/`StartDestruction`/`StartShuffle` and
//! `GameLevel.OnActionMsg`.
#[path = "../src/mining.rs"]
#[allow(dead_code)] // The full Type8 engine is included; this target exercises powerups.
mod mining;
use mining::{
    MINING_GAME_ID, SIDE, TILE_BLOCKER, TILE_EMPTY, TILE_POWERUP_DESTRUCT, TILE_POWERUP_DYNAMITE,
    TILE_POWERUP_SHUFFLE, TILE_POWERUP_START, TILE_POWERUP_WILDTILE, TILE_WILDCARD, Type8BoardSpec,
    Type8Engine, Type8Goal, Type8Outcome, Type8Phase, Type8PowerupDefinition, Type8State,
};
use serde_json::json;
use std::fs;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};

const LEFT: usize = 3;
const TOP: usize = 3;
const PLAYABLE: usize = 8;
const PROFILE: i32 = 14;
const FIRST_INSTANCE: i32 = 18_000_001;
const ORE: u16 = 601;
const ORE_TWO: u16 = 602;
const SELECTABLE: u16 = 401;
const SELECTABLE_TWO: u16 = 402;

static NEXT: AtomicU64 = AtomicU64::new(0);

struct Fixture {
    directory: PathBuf,
}

impl Fixture {
    /// `powerup_percent` selects how often a powerup replaces the selectable
    /// branch; the definitions are the authored private rows. `None` omits the
    /// key entirely, matching every existing content file.
    fn new(powerup_percent: u32, definitions: Option<Vec<Type8PowerupDefinition>>) -> Self {
        let directory = std::env::temp_dir().join(format!(
            "osfr-mining-powerups-{}-{}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir(&directory).unwrap();
        let mut spec = spec();
        spec.powerup_percent = powerup_percent;
        let mut content = json!({
            "schema_version": 1,
            "game_id": MINING_GAME_ID,
            "profile_id": PROFILE,
            "name_id": 7910,
            "description_id": 7911,
            "icon_id": 909,
            "spec": spec,
        });
        if let Some(definitions) = definitions {
            content["powerup_definitions"] = serde_json::to_value(definitions).unwrap();
        }
        fs::write(
            directory.join("mining.json"),
            serde_json::to_vec(&content).unwrap(),
        )
        .unwrap();
        Self { directory }
    }

    fn load(&self, state: Option<Type8State>) -> Type8Engine {
        Type8Engine::load(
            &self.directory,
            "mining.json",
            MINING_GAME_ID,
            FIRST_INSTANCE,
            state,
        )
        .unwrap()
    }

    fn try_load(&self) -> std::io::Result<Type8Engine> {
        Type8Engine::load(
            &self.directory,
            "mining.json",
            MINING_GAME_ID,
            FIRST_INSTANCE,
            None,
        )
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = fs::remove_file(self.directory.join("mining.json"));
        let _ = fs::remove_dir(&self.directory);
    }
}

fn spec() -> Type8BoardSpec {
    let mut shape = vec![0_i32; SIDE * SIDE];
    for y in TOP..TOP + PLAYABLE {
        for x in LEFT..LEFT + PLAYABLE {
            shape[y * SIDE + x] = 1;
        }
    }
    for x in LEFT..LEFT + PLAYABLE {
        shape[(TOP + PLAYABLE) * SIDE + x] = 4;
    }
    Type8BoardSpec {
        width: SIDE,
        height: SIDE,
        shape,
        selectable: vec![SELECTABLE, SELECTABLE_TWO, 403, 404],
        collectable: vec![ORE, ORE_TWO],
        tiles: vec![
            mining::Type8Kind {
                value: SELECTABLE,
                category: 400,
                icon_id: 1,
            },
            mining::Type8Kind {
                value: ORE,
                category: 600,
                icon_id: 909,
            },
        ],
        goals: vec![Type8Goal {
            index: 0,
            value: ORE,
            quota: 15,
            per_reward: 1,
            icon_id: 909,
        }],
        outputs: Vec::new(),
        duration_seconds: 180,
        seed: 18,
        wildcard_percent: 0,
        collectable_percent: 0,
        blocker_percent: 0,
        powerup_percent: 0,
        meter_id: 0,
        reconstructed_rules: true,
        rule_notice: "Synthetic private fixture. Original server level tables unrecovered.".into(),
    }
}

fn definition(value: u16, power: u32) -> Type8PowerupDefinition {
    Type8PowerupDefinition {
        value,
        spawn_chance: 25,
        duration: 5,
        power,
    }
}

fn clickable_definitions() -> Vec<Type8PowerupDefinition> {
    vec![
        definition(TILE_POWERUP_DYNAMITE, 2),
        definition(TILE_POWERUP_WILDTILE, 2),
        definition(TILE_POWERUP_DESTRUCT, 2),
        definition(TILE_POWERUP_SHUFFLE, 2),
    ]
}

fn header(sub: u8, id: i32, game: i32) -> Vec<u8> {
    let mut b = 39_u16.to_le_bytes().to_vec();
    b.push(sub);
    for n in [id, -1, game] {
        b.extend(n.to_le_bytes());
    }
    b
}

fn client_payload(id: i32, s: &str) -> Vec<u8> {
    let mut b = header(14, id, -1);
    b.extend(((s.len() + 1) as i32).to_le_bytes());
    b.extend(s.as_bytes());
    b.push(0);
    b
}

fn payload_text(packet: &[u8]) -> Option<String> {
    if packet.len() < 19 || packet[0..3] != [39, 0, 14] {
        return None;
    }
    let n = i32::from_le_bytes(packet[15..19].try_into().unwrap());
    assert!(n >= 1);
    let end = 19 + n as usize - 1;
    assert_eq!(packet.len(), end + 1);
    assert_eq!(packet[end], 0);
    Some(String::from_utf8(packet[19..end].to_vec()).unwrap())
}

fn texts(outcome: &Type8Outcome) -> Vec<String> {
    outcome
        .replies
        .iter()
        .filter_map(|p| payload_text(p))
        .collect()
}

fn enter_playing(engine: &mut Type8Engine) -> Type8Outcome {
    let id = FIRST_INSTANCE;
    engine.begin(PROFILE).unwrap();
    engine.handle(&header(5, id, -1)).unwrap();
    engine.handle(&client_payload(id, "OnConnectMsg")).unwrap();
    engine
        .handle(&client_payload(id, "OnStartGameMsg"))
        .unwrap();
    let started = engine
        .handle(&client_payload(id, "OnStartLevelMsg"))
        .unwrap();
    assert_eq!(
        engine.state().active.as_ref().unwrap().phase,
        Type8Phase::Playing
    );
    started
}

/// One action fixture: clear the playable rectangle, seed the pressed powerup
/// and the tiles the action names, plus a bottom-row chain that keeps the
/// post-action `has_move` check from reshuffling the board under the assertion.
fn action_engine(value: u16, seeds: &[(usize, usize, u16)]) -> (Fixture, Type8Engine, Vec<u8>) {
    action_engine_with(value, seeds, "3,3,4,3,")
}

fn action_engine_with(
    value: u16,
    seeds: &[(usize, usize, u16)],
    list: &str,
) -> (Fixture, Type8Engine, Vec<u8>) {
    wide_action_engine(value, seeds, list, 2)
}

fn wide_action_engine(
    value: u16,
    seeds: &[(usize, usize, u16)],
    list: &str,
    power: u32,
) -> (Fixture, Type8Engine, Vec<u8>) {
    // `powerup_percent = 0` keeps the spawn roll out of the action fixture; the
    // authored definition is what licenses the action, and a clean selectable
    // board makes the refill values deterministic.
    let fixture = Fixture::new(0, Some(vec![definition(value, power)]));
    let mut engine = fixture.load(None);
    let _ = enter_playing(&mut engine);
    let mut cells: Vec<(usize, usize, u16)> = Vec::new();
    for y in TOP..TOP + PLAYABLE {
        for x in LEFT..LEFT + PLAYABLE {
            cells.push((x, y, TILE_EMPTY));
        }
    }
    // A move has to survive the post-action `has_move` check without joining the
    // recovered draw pool: a stacked blocker column is a legal move, never moves
    // under gravity, and is not a selectable, wildcard or visible tile.
    for y in TOP..TOP + 3 {
        cells.push((10, y, TILE_BLOCKER));
    }
    // Seed the action tiles last: identical coordinates are overwritten, so the
    // fixture's own cells always win over the anchor.
    for &(x, y, value) in seeds {
        cells.retain(|(cx, cy, _)| (*cx, *cy) != (x, y));
        cells.push((x, y, value));
    }
    engine.seed_board(&cells).unwrap();
    let action = client_payload(FIRST_INSTANCE, &format!("OnActionMsg\t{value}\t{list}"));
    (fixture, engine, action)
}

fn board_at(engine: &Type8Engine, x: usize, y: usize) -> u16 {
    let spec = engine.spec();
    engine.state().active.as_ref().unwrap().board[y * spec.width + x]
}

fn board_count(engine: &Type8Engine, value: u16) -> usize {
    engine
        .state()
        .active
        .as_ref()
        .unwrap()
        .board
        .iter()
        .filter(|v| **v == value)
        .count()
}

