const ITEM_DEFINITION: i32 = 70;
const MOUNT_ID: i32 = 7;
/// The live boarding and dismount composite effect (PFX_Teleport_Flash, T483).
const FLASH: i32 = 46;

fn source() -> Vec<MountSource> {
