    )
    .unwrap()
}

fn inventory(definitions: &[i32]) -> InventoryState {
    InventoryState {
        coins: 0,
        items: definitions
            .iter()
            .enumerate()
            .map(|(index, definition_id)| InventoryItem {
                definition_id: *definition_id,
                tint: 0,
                id: index as i32 + 1,
                count: 1,
                consumed_count: 0,
                stored_count: 0,
                last_cast_time: i64::from(i32::MAX),
                rental: None,
                ability_count: 0,
                activate_enabled: false,
            })
            .collect(),
