node_guid_namespace.excerpt:
//! F701: every live node source and its effect companions share one guid namespace.
//!
//! A node guid is "NOD", one tag byte, then the content spawn id. T524's invisible effect
//! companions also use the tag byte (tag 4), so a source that reuses a tag aliases its spawns.
//! Each node file is loaded on its own through the real `GatheringNodes::load`, which makes the
//! tag the production loader assigns that source observable, then all guids and tags are
//! combined.

use osfr_tools::harvest_nodes::GatheringNodes;
use std::{
    collections::BTreeSet,
    fs,
    path::{Path, PathBuf},
    sync::atomic::{AtomicU64, Ordering},
};

const FILES: [&str; 4] = [
    "harvest_nodes.json",
    "mining_nodes.json",
    "quest_nodes.json",
    "collection_nodes.json",
];
/// T524: the invisible effect companion of a collection node keeps the spawn id and uses tag 4.
const COMPANION_TAG: u64 = 4;
static NEXT: AtomicU64 = AtomicU64::new(0);

struct TempDir(PathBuf);

impl TempDir {
    fn new() -> Self {
        let path = std::env::temp_dir().join(format!(
            "osfr-node-guid-{}-{}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir_all(&path).unwrap();
        Self(path)
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn content_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("data/content")
}

fn tag(guid: u64) -> u64 {
    (guid >> 32) & 0xff
}

/// The guids the real loader places from `file` alone. `None` means the file is not wired into
/// `GatheringNodes::load` yet (`collection_nodes.json` is dormant until T524).
fn load_one(file: &str) -> Option<Vec<u64>> {
    let dir = TempDir::new();
    fs::copy(content_dir().join(file), dir.0.join(file)).unwrap();
    GatheringNodes::load(&dir.0)
        .unwrap()
        .map(|nodes| nodes.actors().map(|actor| actor.guid).collect())
}

#[test]
fn no_two_live_node_guids_share_a_tag_or_a_value() {
    let mut all = BTreeSet::new();
    let mut tags = BTreeSet::new();
    for file in FILES {
        let Some(guids) = load_one(file) else {
            assert_eq!(
                file, "collection_nodes.json",
                "{file} is missing from the node loader"
            );
            continue;
        };
        let source_tags: BTreeSet<u64> = guids.iter().map(|guid| tag(*guid)).collect();
        assert_eq!(
            source_tags.len(),
            1,
            "{file} was placed under more than one tag: {source_tags:?}"
        );
        let source_tag = *source_tags
            .first()
            .expect("a loaded node source has actors");
        assert!(
            source_tag < 256,
            "{file} tag {source_tag} does not fit one byte"
        );
        assert!(
            tags.insert(source_tag),
            "{file} reuses node tag {source_tag} already owned by another source"
        );
        for guid in &guids {
            assert!(
                all.insert(*guid),
                "{file} guid {guid:#x} is also another source's guid"
            );
        }
        if file == "collection_nodes.json" {
            // T524: every collection node's effect companion keeps the spawn id and uses tag 4.
            assert_ne!(
                source_tag, COMPANION_TAG,
                "collection tag aliases its own effect companions"
            );
            for guid in &guids {
                let companion = (*guid & !(0xff_u64 << 32)) | (COMPANION_TAG << 32);
                assert!(
                    !all.contains(&companion),
                    "collection node {guid:#x} and its companion {companion:#x} collide"
                );
            }
        }
    }
    assert!(
        !tags.contains(&COMPANION_TAG),
        "a live node source uses the tag-4 effect-companion namespace"
    );
}

npc_greetings_enabled_quests.excerpt:
//! T378: every enabled quest giver and talk target carries a recovered greeting.
//!
//! Content only: `NpcInteraction::dialogue_context` already copies `greeting_string_id`
//! into `DialogueContext.body_string_id`, and `gameplay/npc.rs::dialogue_packet_with`
//! writes it into the first 26/3 payload dword, so this slice adds no packet, handler,
//! selector, table or flag.
//!
//! Client evidence re-checked in IDA for T378: 26/3 handler `0x00aa12e0` calls payload
//! reader `0x00a9ef10`, which stores the first payload dword at object `+16`
//! (`*(this + 16) = *v3`), then calls display routine `0x009f5ae0`, which passes
//! `*(a2 + 16)` to the `Global.Text.<id>` lookup `0x0097c1e0` immediately before
//! `:SetDialogText`. That is the first dword after the four-byte family/subtype header,
//! matching `encode_dialogue_26_3`'s `initial_dwords[0]`; `patch_npc_actor` overwrites
//! only bytes 12..20 with the runtime actor GUID. The full byte order is pinned by
//! `tests/npc_interaction.rs::dialogue_26_3_synthetic_fixture_round_trips_exact_native_field_order`.
//!
//! Locale ids, JenkinsLookup2 hashes, `en_us_data.dat` lines, speaker proofs, the
//! reconstructed-field flags and every blank row's reason are in
//! `notes/Autopilot/T378.md`.
//!
//! The enabled quest set is derived from the production split loader
//! (`QuestEngine::from_split_content`, the call `Gameplay::bind_npc_quest_catalogue`
//! makes from the same directory). `QuestEngine` has no public all-definitions
//! iterator, so the test enumerates the same `quests/*.json` records the loader reads
//! and validates every enabled flag and giver through `QuestEngine::is_enabled` and
//! `QuestEngine::giver_npc_id`; a `talk_to_npc` objective contributes its `npc_id`.
//!
//! The packet builders, the locale line convention and the 26/3 body offset live in
//! the shared `tests/common/npc_greetings.rs` harness.

#[path = "common/npc_greetings.rs"]
mod npc_greetings;

use npc_greetings::{
    GREETING_HEADER, MENU_HEADER, character_at, content_dir, gameplay_dir, gameplay_talk_body,
    greeting_bindings, interact, lab_report, locale_id_to_text, locale_rows, npc_position,
    npc_record, npc_records, read_json, select, service, service_talk_body,
};
use osfr_tools::{
    gameplay::Gameplay,
    npc_interaction::{NpcAction, NpcInteractionError, NpcSelection},
    quest_engine::{CharacterEligibility, QuestEngine},
    world::NpcVisibility,
    world_text::locale_hash,
};
use serde_json::Value;
use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    path::{Path, PathBuf},
};

