    assert_eq!(
        decode_housing_error(&[2, 0, 0, 0, 0]),
        Err(PermissionError::TrailingBytes)
    );
    assert_eq!(
        decode_housing_error(&[2, 0]),
        Err(PermissionError::Truncated)
    );
}

