    assert_eq!(CollectionUpdateOp::Remove.opcode(), 9);
    assert_eq!(CollectionUpdateOp::AddEntry.opcode(), 10);
    assert_eq!(CollectionUpdateOp::RemoveEntry.opcode(), 11);
    assert_eq!(
