#[path = "../src/restoration/piece_039.rs"]
#[allow(dead_code)]
mod piece_039;

use piece_039::{
    Curve, FARM_INSTANCE_IDS, FARM_MEMBERS_ONLY_FROM_RANK, FARM_NAME_STRING_ID, FARM_RANKS_58,
