}

#[test]
fn rank_boundaries_follow_the_cumulative_table() {
    assert_eq!(rank_for_xp(&FARM_RANKS_58, 0), 1);
    assert_eq!(rank_for_xp(&FARM_RANKS_58, 179), 1);
    assert_eq!(rank_for_xp(&FARM_RANKS_58, 180), 2);
