fn decoded(item_id: i32) -> Vec<(u32, f32)> {
    let item = gear_stat_item(item_id).unwrap();
    item.raw_stats
        .iter()
        .map(|(id, bits)| (id.to_owned(), decode_item_stat(*id, *bits).unwrap().value))
        .collect()
}

