const DAY_MS: u64 = 86_400_000;

fn row(
    quest: u32,
    prereq: Option<u32>,
    excludes: Vec<u32>,
    requirements: Vec<Requirement>,
) -> QuestRow<u32> {
    QuestRow {
        quest,
