    catalogue: &CollectionCatalogue,
    entries: &[i32],
) -> Vec<CollectOutcome> {
    entries
        .iter()
        .map(|entry| {
            ledger
                .collect(catalogue, *entry)
                .expect("a catalogued entry is collectable")
        })
        .collect()
}

