fn category_bucket_is_the_recovered_modulo() {
    assert_eq!(category_bucket(1), Some(1));
    assert_eq!(category_bucket(10), Some(0));
    assert_eq!(
        category_bucket(11),
        Some(1),
        "FUN_009fd050 hashes with % 10"
    );
    assert_eq!(
        category_bucket(0),
        None,
        "category 0 is not one of the ten recovered rows"
    );
