    assert_eq!(TradePacket::ALL.len(), 18);

    let rows: Vec<(TradePacket, u8, &str)> = TradePacket::ALL
        .iter()
        .map(|packet| (*packet, packet.code(), packet.name()))
        .collect();
    assert_eq!(
