fn session_replacement_rejects_stale_datagrams_and_restarts_exactly() {
    let config = StressConfig {
        clients: 2,
        latency_ticks: 3,
        loss_percent: 0,
        duplicate_percent: 0,
        reorder_percent: 0,
        ack_loss_percent: 0,
        ack_duplicate_percent: 0,
