    assert!(stats.discarded > 0, "the replaced sender retained nothing");
    assert_eq!(stats.corrupt_rejected, 0);
    assert_eq!(delivered[..boundary], messages(0, 0..boundary)[..]);
    assert_eq!(delivered[boundary..], messages(0, 100..110)[..]);
