fn dangling_locale_class_category_and_model_references_are_reported() {
    let items = vec![
        // Fully resolvable row.
        item(
            1,
            Some(10),
            Some(11),
            Some("tool_pickaxe_01.adr"),
            Some(1),
            Some(5),
