    /// Achievement count and points (`00940e60`), then the eight scalars.
    tail: Vec<i32>,
    /// (id, type, value) in list order (`00ad7f40`, entries `008e7640`).
    stats: Vec<(i32, i32, i32)>,
    text: Vec<u8>,
}

fn parse_inspect(packet: &[u8]) -> (u64, bool, Payload) {
    assert_eq!(&packet[..3], &[149, 0, 1]);
    let guid = u64::from_le_bytes(packet[3..11].try_into().unwrap());
    let pedestal = packet[11] == 1;
    let len = u32::from_le_bytes(packet[12..16].try_into().unwrap()) as usize;
    assert_eq!(
        packet.len(),
        16 + len,
        "length prefix covers the whole payload"
    );
    let body = &packet[16..];
    let mut at = 0;
    let i32_at = |at: &mut usize| {
        let v = i32::from_le_bytes(body[*at..*at + 4].try_into().unwrap());
        *at += 4;
        v
    };
    let n = i32_at(&mut at);
    let profiles = (0..n).map(|_| (i32_at(&mut at), i32_at(&mut at))).collect();
    let active = i32_at(&mut at);
    let n = i32_at(&mut at);
    let mut items = Vec::new();
    for _ in 0..n {
        let (slot, def, tint) = (i32_at(&mut at), i32_at(&mut at), i32_at(&mut at));
        // This test's records are: id + filler; the filler is 7s up to the next slot,
        // so read until the fixed 12-field tail starts.
        let record_len = 4 + body[at + 4..].iter().take_while(|&&b| b == 7).count();
        items.push((slot, def, tint, body[at..at + record_len].to_vec()));
        at += record_len;
    }
    let tail: Vec<i32> = (0..10).map(|_| i32_at(&mut at)).collect();
    assert_eq!(tail[0], 0, "achievement records are not decoded here");
    // `00ad7f40` refuses a negative count or one larger than the bytes left.
    let n = i32_at(&mut at);
    assert!(n >= 0 && n as usize <= body.len() - at, "stat count {n}");
    let stats = (0..n)
        .map(|_| {
            let (id, kind) = (i32_at(&mut at), i32_at(&mut at));
            // `008e7640`: a value follows only for type 0 (int) and 1 (float).
            let value = if kind == 0 || kind == 1 {
                i32_at(&mut at)
            } else {
                0
            };
            (id, kind, value)
        })
        .collect();
    let n = i32_at(&mut at) as usize; // `008e2470`
    let text = body[at..at + n].to_vec();
    at += n;
    assert_eq!(at, body.len(), "payload fully consumed");
    (
        guid,
        pedestal,
        Payload {
            profiles,
            active,
            items,
            tail,
            stats,
            text,
        },
    )
}

