fn spawn_message(messages: &[OutboundMessage], recipient: u64, guid: u64) -> &[u8] {
    messages
        .iter()
        .find(|message| {
            message.recipient == SessionId(recipient)
                && message.kind == MessageKind::Spawn
                && u64::from_le_bytes(message.bytes[11..19].try_into().unwrap()) == guid
        })
