    assert_eq!(
        grid.join(SessionId(2), 102, 202, zone, [1.0; 3], 0.0),
        old.join(SessionId(2), 102, 202, zone, [1.0; 3], 0.0)
    );
    assert_eq!(grid.leave(SessionId(1)), old.leave(SessionId(1)));
}

