postman_trail_of_mail.excerpt:
//! F343: the live one-Talk turn-in for Postmaster Lane's "Trail of Mail"
//! (3130032), the row T314 gave a reward.
//!
//! The quest is content-only: Postmaster Lane (9000000173) offers it, one Talk
//! to Postchug Runalug (9000000172) completes the only objective and opens the
//! 49/13 end screen, and the 49/14 reply settles 5 coins + 5 Postman (profile
//! 4) XP. These tests drive the production in-world router
//! (`Gameplay::handle_in_world` -> `gameplay/npc.rs` -> `QuestEngine`); they do
//! not call `QuestOutcome` or `finish_turnin` directly.
//!
//! Client wire evidence used here is the shared NPC quest chain:
//! - 26/8 interact constructor `0x008b6bc0`; 26/10 menu-select constructor
//!   `0x00a36f80`; 26/6 dialogue-response constructor `0x009f5890`.
//! - 49/1 offer reader `0x00c7bb60`; 49/2 accept constructor `0x00a86400`;
//!   49/13 end-screen reader `0x00c7b990` (actor `6..14`, quest `14..18`, end
//!   text `18..22`, reward bundle `0x008e7930`); 49/14 reply constructor
//!   `0x00a864c0`.
//!
//! The shared fixture and packet builders live in
//! `tests/support/npc_quest_chain.rs`.

#[path = "support/npc_quest_chain.rs"]
mod npc_quest_chain;

use npc_quest_chain::{
    CHARACTER, Fixture, accept, assert_packet_changes_nothing, character_at_for, coins,
    content_position, counts, end_screen_reward, finish_quest, has_family, offer, pending_turnin,
    profile_xp, quest_end_reply, quest_status, saved, send, talk_step,
};
use osfr_tools::{character_store::CharacterState, gameplay::Gameplay, quest_engine::QuestStatus};

const QUEST: u32 = 3_130_032;
const GIVER: u64 = 9_000_000_173;
const TARGET: u64 = 9_000_000_172;
const END_TEXT: u32 = 141_831;
const POSTMAN: i32 = 4;
const REWARD_COINS: u32 = 5;
const REWARD_XP: u32 = 5;

fn at(npc_id: u64, file: &str) -> CharacterState {
    // The open-world zone resolves every regional label by distance (npc_interaction
    // `check_range`), so the character stands on the authored content position.
    character_at_for(CHARACTER, 0, content_position(file, npc_id))
}

/// The opening fixture with Postman unlocked: its starter profile set is
/// `[1, 43]` (pinned by [`a_locked_postman_profile_is_paid_nothing`]), and the
/// reward's profile-4 XP must be grantable (T249's unlock rule).
fn postman_game(fixture: &Fixture) -> Gameplay {
    let mut state = fixture.game(None).state();
    state
        .profiles
        .as_mut()
        .expect("the opening fixture stores profiles")
        .unlocked
        .insert(POSTMAN);
    fixture.game(Some(state))
}

#[test]
fn postmaster_lane_pays_trail_of_mail_once() {
    let fixture = Fixture::new();
    let mut game = postman_game(&fixture);
    let giver = at(GIVER, "shrouded_glade.json");
    let target = at(TARGET, "wugachug.json");
    let mut now = 1_000;

    offer(&mut game, &giver, GIVER, QUEST, now);
    now += 10;
    accept(&mut game, &giver, QUEST, now);
    now += 10;
    talk_step(&mut game, &target, TARGET, now, "Postman: Trail of Mail");
    assert_eq!(counts(&game, QUEST), [1]);
    assert_eq!(pending_turnin(&game), Some(QUEST));

    // A reconnect between the final Talk and 49/14 must keep the pending
    // turn-in through the serialized save state, not only the live clone.
    let held = saved(&game);
    let mut game = fixture.reload_serialized(&game);
    assert_eq!(
        saved(&game),
        held,
        "reload changed the saved pending turn-in"
    );
    assert_eq!(quest_status(&game, QUEST), QuestStatus::Active);
    assert_eq!(pending_turnin(&game), Some(QUEST));

    // The production relog batch re-sends the held 49/13 after its speaker's
    // 35/2 (`gateway.rs` -> `update_npc_visibility` ->
    // `append_pending_turnin_screen`); `ShowQuestEndScreen` (`00a95420`)
    // resolves the actor through the client table and never retries.
    let packets = game
        .update_npc_visibility(&target)
        .expect("relog NPC visibility");
    let spawn = packets.iter().position(|packet| {
        osfr_tools::startup_world::parse_add_npc(packet).is_ok_and(|npc| npc.actor_id == TARGET)
    });
    let end = packets
        .iter()
        .position(|packet| has_family(packet, 49, 13, Some(QUEST)))
        .expect("the held end screen is re-sent after relog");
    assert!(
        spawn.is_some_and(|spawn| spawn < end),
        "the speaker's 35/2 must precede its 49/13"
    );
    assert_eq!(
        u64::from_le_bytes(packets[end][6..14].try_into().unwrap()),
        TARGET,
        "the re-sent end screen must name the runtime speaker"
    );
    assert_eq!(
        u32::from_le_bytes(packets[end][18..22].try_into().unwrap()),
        END_TEXT,
        "the re-sent end screen must carry the quest's debrief text"
    );
    assert_eq!(
        packets[end].len(),
        99,
        "the no-display-row reward bundle keeps the client-reader length"
    );
    assert_eq!(end_screen_reward(&packets[end]), (REWARD_COINS, REWARD_XP));

    now += 10;
    finish_quest(
        &mut game,
        &target,
        QUEST,
        POSTMAN,
        REWARD_COINS,
        REWARD_XP,
        now,
    );
    assert_eq!(quest_status(&game, QUEST), QuestStatus::Completed);
    assert_eq!(coins(&game), REWARD_COINS);
    assert_eq!(profile_xp(&game, POSTMAN), REWARD_XP);

    // A second 49/14 must not pay twice or change any saved state.
    let finished = saved(&game);
    now += 10;
    assert_packet_changes_nothing(
        &mut game,
        &target,
        &quest_end_reply(QUEST),
        now,
        "duplicate Trail of Mail turn-in",
    );
    assert_eq!(coins(&game), REWARD_COINS);
    assert_eq!(profile_xp(&game, POSTMAN), REWARD_XP);

    // The completed ledger and the paid reward survive the serialized reconnect;
    // the reward is not paid again on load.
    let reloaded = fixture.reload_serialized(&game);
    assert_eq!(
        saved(&reloaded),
        finished,
        "reload changed completed history"
    );
    assert_eq!(quest_status(&reloaded, QUEST), QuestStatus::Completed);
    assert_eq!(coins(&reloaded), REWARD_COINS);
    assert_eq!(profile_xp(&reloaded, POSTMAN), REWARD_XP);
}

/// The reward names profile 4, so a character without Postman is refused at
/// turn-in by the F249 reward gate (`QuestDenial::Job`): the end screen clears,
/// nothing is paid, and the quest stays active for a later Talk. The content has
/// no job gate on `3130032` (pre-existing T314 gap named in `notes/Autopilot/
/// F365.md`); the first test unlocks Postman as its setup.
#[test]
fn a_locked_postman_profile_is_paid_nothing() {
    let fixture = Fixture::new();
    let mut game = fixture.game(None);
    assert!(
        !game
            .state()
            .profiles
            .as_ref()
            .expect("the opening fixture stores profiles")
            .unlocked
            .contains(&POSTMAN),
        "the opening fixture starts without Postman"
    );
    let giver = at(GIVER, "shrouded_glade.json");
    let target = at(TARGET, "wugachug.json");
    let mut now = 2_000;

    offer(&mut game, &giver, GIVER, QUEST, now);
    now += 10;
    accept(&mut game, &giver, QUEST, now);
    now += 10;
    talk_step(&mut game, &target, TARGET, now, "Postman: Trail of Mail");
    assert_eq!(pending_turnin(&game), Some(QUEST));
    let coins_before = coins(&game);

    now += 10;
    let settled = send(&mut game, &target, &quest_end_reply(QUEST), now);
    assert!(
        settled.changed,
        "the locked-profile refusal still releases the end screen"
    );
    assert!(
        !settled
            .replies
            .iter()
            .any(|packet| has_family(packet, 49, 4, Some(QUEST))),
        "a locked profile must not report quest completion"
    );
    assert_eq!(pending_turnin(&game), None);
    assert_eq!(coins(&game), coins_before);
    assert_eq!(profile_xp(&game, POSTMAN), 0);
    assert_eq!(quest_status(&game, QUEST), QuestStatus::Active);
    assert_eq!(counts(&game, QUEST), [1]);
}

postman_trainer.excerpt:
//! T407: Postman (profile 4) is learnable from a drawn trainer, and every job an
//! enabled quest pays or gates has a learn path.
//!
//! Before T407 the only enabled Postman quest, "Postman: Trail of Mail" (3130032),
//! paid 5 Postman XP no player could receive: `job_trainers.json` had no profile-4
//! row, so the locked-profile reward gate (`rewards::locked_job_profile`) refused
//! every turn-in. The fix is one content row (Flitter in Sanctuary, menu label
//! 412445 "Become a Postman"); no production Rust changed.
//!
//! Every packet goes through `Gameplay::handle_in_world`, the router the gateway
//! session calls. Client wire evidence, unchanged by this slice: 26/8 interact
//! `0x008b6bc0`; 26/9 menu `0x00aa2360 -> 0x00aa2220 -> 0x00aa1600 -> 0x00aa04d0`
//! (option count, then seven dwords per option read by `0x00a9dca0`, the label
//! third); 26/10 select `0x00a36f80`; 26/13 job select, applied by
//! `ProcessProfileSwap` `0x00bfb620` only with Chest and Legs; 26/6 `0x009f5890`;
//! 49/1 `0x00c7bb60`; 49/2 `0x00a86400`; 49/13 `0x00c7b990`; 49/14 `0x00a864c0`.

#[path = "common/job_playtest.rs"]
mod job_playtest;
#[path = "support/npc_quest_chain.rs"]
mod npc_quest_chain;

use npc_quest_chain::{
    CHARACTER, Fixture, accept, active_job, assert_packet_changes_nothing, character_at_for,
    content_dir, content_position, end_screen_reward, finish_quest, interact, menu_option,
    npc_interact, npc_select, offer, profile_xp, quest_end_reply, read_json, release_end_screen,
    saved, select_job, send, talk_step,
};
use osfr_tools::{
    character_store::CharacterState,
    gameplay::{Gameplay, Outcome},
    profiles::Profiles,
    quest_engine::{CharacterEligibility, QuestEngine},
};
use std::{collections::BTreeSet, fs};

/// Flitter, `sanctuary.json`: the profile-4 row of `job_trainers.json`.
const TRAINER: u64 = 9_000_000_091;
const BECOME_A_POSTMAN: u32 = 412_445;
const POSTMAN: i32 = 4;
const ADVENTURER: i32 = 1;
/// The opening save's other job; unlike Adventurer it wears a Chest/Legs outfit.
const BRAWLER: i32 = 43;
const QUEST: u32 = 3_130_032;
const GIVER: u64 = 9_000_000_173;
const TARGET: u64 = 9_000_000_172;
const END_TEXT: u32 = 141_831;
/// The play package's Postman Chest and Legs starter pieces.
const CHEST_AND_LEGS: [i32; 2] = [12_827, 13_197];

fn at(npc: u64, file: &str) -> CharacterState {
    character_at_for(CHARACTER, 0, content_position(file, npc))
}

fn unlocked(game: &Gameplay) -> BTreeSet<i32> {
    game.state().profiles.expect("profiles").unlocked
}

fn owned(game: &Gameplay, definition: i32) -> u32 {
    let items = game.state().inventory.items;
    items
        .iter()
        .filter(|item| item.definition_id == definition)
        .map(|item| item.count)
        .sum()
}

fn said(outcome: &Outcome, text: &str) -> bool {
    outcome
        .replies
        .iter()
        .any(|reply| String::from_utf8_lossy(reply).contains(text))
}

/// A refusal may answer with a chat line or an error; either way the save is unchanged.
fn assert_refused(game: &mut Gameplay, who: &CharacterState, packet: &[u8], now: u64, label: &str) {
    let before = saved(game);
    let outcome = game.handle_in_world(packet, who, now);
    assert!(!outcome.is_ok_and(|outcome| outcome.changed), "{label}");
    assert_eq!(saved(game), before, "{label} changed the save");
}

#[test]
fn a_new_player_learns_postman_at_flitter_and_is_paid_for_trail_of_mail() {
    let fixture = Fixture::new();
    job_playtest::install_starter_outfits(fixture.path());
    let mut game = fixture.game(None);
    assert!(
        !unlocked(&game).contains(&POSTMAN),
        "the opening save lacks Postman"
    );
    let trainer = at(TRAINER, "sanctuary.json");
    let [x, y, z] = trainer.position;
    let far = character_at_for(CHARACTER, 0, [x + 500.0, y, z]);
    let mut now = 1_000;

    assert_refused(&mut game, &far, &npc_interact(TRAINER), now, "far 26/8");
    assert_refused(
        &mut game,
        &trainer,
        &npc_select(TRAINER, 1),
        now,
        "26/10, no menu",
    );
    let menu = interact(&mut game, &trainer, TRAINER, now);
    let choice = menu_option(&menu, BECOME_A_POSTMAN);
    let forged = npc_select(TRAINER, choice + 50);
    assert_refused(&mut game, &trainer, &forged, now + 1, "unoffered 26/10");
    assert_refused(&mut game, &trainer, &forged[..12], now + 1, "short 26/10");
    assert!(!unlocked(&game).contains(&POSTMAN));

    // The refusals left the open menu usable: its Learn choice unlocks Postman.
    let learned = send(&mut game, &trainer, &npc_select(TRAINER, choice), now + 2);
    assert!(learned.changed && said(&learned, "You learned the Postman job"));
    assert!(unlocked(&game).contains(&POSTMAN));
    assert_eq!(
        active_job(&game),
        ADVENTURER,
        "learning does not switch jobs"
    );
    for piece in CHEST_AND_LEGS {
        assert_eq!(owned(&game, piece), 1, "starter piece {piece} granted once");
    }

    // The starter outfit passes the client's Chest/Legs gate, so 26/13 activates
    // Postman. Switching back proves the reward follows the quest's job map.
    now += 10;
    let switched = send(&mut game, &trainer, &select_job(POSTMAN), now);
    assert!(
        switched
            .replies
            .iter()
            .any(|r| r.starts_with(&[38, 0, 21, 0]))
    );
    assert_eq!(active_job(&game), POSTMAN);
    send(&mut game, &trainer, &select_job(BRAWLER), now + 1);
    assert_eq!(active_job(&game), BRAWLER);

    let giver = at(GIVER, "shrouded_glade.json");
    let target = at(TARGET, "wugachug.json");
    now += 10;
    offer(&mut game, &giver, GIVER, QUEST, now);
    accept(&mut game, &giver, QUEST, now + 10);
    talk_step(
        &mut game,
        &target,
        TARGET,
        now + 20,
        "Postman: Trail of Mail",
    );
    let end = release_end_screen(&mut game, &target, QUEST, TARGET, END_TEXT, now + 30);
    assert_eq!(end_screen_reward(&end), (5, 5));
    let items = game.state().inventory.items;
    finish_quest(&mut game, &target, QUEST, POSTMAN, 5, 5, now + 40);
    assert_eq!(
        game.state().inventory.items,
        items,
        "the quest grants no item"
    );
    assert_eq!(profile_xp(&game, POSTMAN), 5);
    let replay = quest_end_reply(QUEST);
    assert_packet_changes_nothing(&mut game, &target, &replay, now + 50, "replayed 49/14");

    // Relog keeps the job, outfit, wallet and completed quest; the trainer then
    // refuses a second lesson without granting the outfit again.
    let paid = saved(&game);
    let mut game = fixture.reload_serialized(&game);
    assert_eq!(saved(&game), paid, "relog changed the save");
    let menu = interact(&mut game, &trainer, TRAINER, now + 60);
    let choice = menu_option(&menu, BECOME_A_POSTMAN);
    let again = send(&mut game, &trainer, &npc_select(TRAINER, choice), now + 61);
    assert!(!again.changed && said(&again, "already know"));
    assert_eq!(saved(&game), paid, "a second lesson changed the save");
}

