                        .is_some_and(|price| price > 0)
                })
        })
        .map(|vendor| PricedVendor {
            npc_id: vendor["npc_id"].as_u64().expect("vendor NPC id"),
            item_ids: vendor["item_ids"]
                .as_array()
                .expect("vendor item ids")
                .iter()
                .map(|id| {
                    i32::try_from(id.as_i64().expect("vendor item id"))
