use osfr_tools::progression_extras::{parse_collection_content, parse_title_content};
use serde::Deserialize;
use std::{
    collections::{HashMap, HashSet},
    fs,
    path::PathBuf,
};

#[derive(Deserialize)]
struct LocaleRow {
    id: u32,
    text: String,
}

#[derive(Deserialize)]
struct ItemDefinitionRow {
    #[serde(rename = "Id")]
    id: u32,
}

fn project_path(path: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(path)
}

fn lab_path(path: &str) -> PathBuf {
    project_path("../../../lab").join(path)
}

fn locale() -> HashMap<u32, String> {
    let bytes = fs::read(lab_path("reports/locale-id-to-text.json")).unwrap();
    serde_json::from_slice::<Vec<LocaleRow>>(&bytes)
        .unwrap()
        .into_iter()
        .map(|row| (row.id, row.text))
        .collect()
}

fn client_images() -> HashSet<u32> {
    fs::read_to_string(lab_path(
        "working/OSFR.Client/OSFR Client/Resources/Images/Images.txt",
    ))
    .unwrap()
    .lines()
    .filter_map(|line| line.split('^').next()?.parse().ok())
    .collect()
}

fn client_item_definitions() -> HashSet<u32> {
    let bytes = fs::read(lab_path(
        "references/FreeRealms-Legacy/src/Resources/ClientItemDefinitions.json",
    ))
    .unwrap();
    serde_json::from_slice::<Vec<ItemDefinitionRow>>(&bytes)
        .unwrap()
        .into_iter()
        .map(|row| row.id)
        .collect()
}

#[test]
fn title_and_collection_ids_resolve_to_client_data() {
    let locale = locale();
    let images = client_images();
    let items = client_item_definitions();
    let titles =
        parse_title_content(&fs::read(project_path("data/content/titles.json")).unwrap()).unwrap();
    let collections =
        parse_collection_content(&fs::read(project_path("data/content/collections.json")).unwrap())
            .unwrap();

    assert_eq!(titles.definitions.len(), 90);
    let title_ids: HashSet<u32> = titles
        .definitions
        .iter()
        .map(|title| title.client_id.unwrap())
        .collect();
    assert_eq!(title_ids.len(), titles.definitions.len());
    for title in &titles.definitions {
        let name = &locale[&title.name_id.unwrap()];
        assert!(!name.trim().is_empty());
        if let Some(id) = title.description_id {
            assert!(!locale[&id].trim().is_empty());
        }
        if let Some(image_id) = title.image_id {
            assert!(
                images.contains(&image_id),
                "unresolved title image {image_id}"
            );
        }
        assert!(title.source_tags.contains_key("client_id"));
    }

    assert_eq!(collections.definitions.len(), 241);
    let collection_ids: HashSet<u32> = collections
        .definitions
        .iter()
        .map(|collection| collection.client_id.unwrap())
        .collect();
    assert_eq!(collection_ids.len(), collections.definitions.len());
    for collection in &collections.definitions {
        for id in [collection.name_id, collection.description_id]
            .into_iter()
            .flatten()
        {
            assert!(
                !locale[&id].trim().is_empty(),
                "unresolved collection locale id {id}"
            );
        }
        if let Some(image_id) = collection.image_id {
            assert!(
                images.contains(&image_id),
                "unresolved collection image {image_id}"
            );
        }
        for entry in &collection.entries {
            if let Some(id) = entry.name_id {
                assert!(
                    !locale[&id].trim().is_empty(),
                    "unresolved entry locale id {id}"
                );
            }
            if let Some(id) = entry.item_definition_id {
                assert!(
                    items.contains(&id),
                    "unknown collection item definition {id}"
                );
            }
            if let Some(id) = entry.icon_id {
                assert!(images.contains(&id), "unresolved entry image {id}");
            }
        }
    }

    let briarwood = collections
        .definitions
        .iter()
        .find(|collection| collection.client_id == Some(17054))
        .unwrap();
    assert_eq!(briarwood.category_id, Some(10));
    assert_eq!(briarwood.wiki_category_id, Some(3));
    assert_eq!(briarwood.description_id, Some(17055));
    assert_eq!(briarwood.entries.len(), 8);
    assert!(
        briarwood
            .entries
            .iter()
            .all(|entry| entry.item_definition_id.is_some())
    );
}

quest_breadcrumb.excerpt:
//! W175 (Next 10 brief #5, second half): the 49/15 breadcrumb crosswalk.
//!
//! The client sends the ORIGINAL quest id of a world-map point of interest. The regional
//! catalogue does not use those ids, so `data/content/breadcrumb_quests.json` maps them to
//! regional quests and anything unlisted is refused (R). These tests pin the loader, the
//! shipped file and the journal behaviour behind it; the gateway route is covered by the
//! unit tests in `gameplay.rs` (see `lab/runs/claude/W175/apply.py`).

use osfr_tools::{
    quest_engine::{
        CharacterEligibility, ObjectiveKind, OutboundMessage, QuestDefinition, QuestDenial,
        QuestEngine, QuestMessage, QuestObjective, QuestOutcome, QuestRequirements, QuestStatus,
    },
    quest_journal::{Crosswalk, JournalRequest, handle, load_crosswalk, translate},
    rewards::{RewardDisplay, RewardGrant},
};
use serde_json::{Value, json};
use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    path::{Path, PathBuf},
    sync::atomic::{AtomicU32, Ordering},
};

const CHARACTER: u64 = 900;
const CANARY_COINS: u32 = 88_001;

fn bundled_content() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("data/content")
}

struct Scratch(PathBuf);
impl Scratch {
    fn new() -> Self {
        static SERIAL: AtomicU32 = AtomicU32::new(0);
        let dir = Path::new(env!("CARGO_TARGET_TMPDIR")).join(format!(
            "w175-{}-{}",
            std::process::id(),
            SERIAL.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir_all(&dir).unwrap();
        Self(dir)
    }
    fn write(&self, document: &Value) -> &Path {
        fs::write(self.0.join("breadcrumb_quests.json"), document.to_string()).unwrap();
        &self.0
    }
}
impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn record(original: u32, regional: Option<u32>) -> Value {
    json!({
        "original_quest_id": original,
        "poi_ids": [7],
        "poi_name": "Synthetic",
        "regional_quest_id": regional,
        "source": [{"kind": "reconstructed", "evidence": "(R) synthetic test row"}]
    })
}

fn file(records: Vec<Value>) -> Value {
    json!({"schema_version": 1, "records": records})
}

#[test]
fn the_shipped_crosswalk_loads_and_points_at_real_quests() {
    let content = bundled_content();
    let crosswalk = load_crosswalk(&content).unwrap();
    let document: Value =
        serde_json::from_slice(&fs::read(content.join("breadcrumb_quests.json")).unwrap()).unwrap();
    let rows = document["records"].as_array().unwrap();
    let originals: BTreeSet<u32> = rows
        .iter()
        .map(|row| row["original_quest_id"].as_u64().unwrap() as u32)
        .collect();
    assert_eq!(
        originals,
        BTreeSet::from([
            1799, 1801, 1802, 1803, 1804, 1805, 1806, 1807, 1808, 1809, 1810, 1811, 1812, 1813,
            1814, 1815, 1880, 1881,
        ])
    );
    assert_eq!(rows.len(), 18);
    let mut points = BTreeSet::new();
    for row in rows {
        for point in row["poi_ids"].as_array().unwrap() {
            assert!(points.insert(point.as_u64().unwrap() as u32));
        }
    }
    // The startup snapshot names 43 POIs carrying these 18 non-zero original quest ids.
    assert_eq!(points.len(), 43);
    // Only title/activity matches are mapped. 1811 is authored below; the other three
    // targets stay hollow/disabled, so the regular offer path still refuses them.
    assert_eq!(
        crosswalk,
        BTreeMap::from([
            (1805, 3_050_009),
            (1808, 3_050_013),
            (1811, 3_050_004),
            (1881, 3_140_001),
        ])
    );
    let mut catalogue = BTreeSet::new();
    let mut offerable = BTreeMap::new();
    let mut cooking_starter = None;
    for entry in fs::read_dir(content.join("quests")).unwrap() {
        let document: Value =
            serde_json::from_slice(&fs::read(entry.unwrap().path()).unwrap()).unwrap();
        for quest in document["records"].as_array().unwrap() {
            if let Some(id) = quest["id"].as_u64() {
                catalogue.insert(id);
                offerable.insert(
                    id,
                    (
                        quest["enabled"].as_bool().unwrap_or(true),
                        quest["objectives"].as_array().map_or(0, Vec::len),
                    ),
                );
                if id == 3_050_004 {
                    cooking_starter = Some(quest.clone());
                }
            }
        }
    }
    for (original, regional) in &crosswalk {
        assert!(*original > 0 && *original <= i32::MAX as u32);
        assert!(
            catalogue.contains(&u64::from(*regional)),
            "original {original} maps to missing quest {regional}"
        );
        // The two id spaces must not overlap, or a regional id could pass as an original one.
        assert!(!catalogue.contains(&u64::from(*original)));
    }
    // The Cooking Table starter is reachable, not merely a title-to-id mapping:
    // it has an ordered journey to the trainer table and a content-defined 45/11 goal.
    let starter = cooking_starter.expect("Cooking 101 exists");
    assert_ne!(starter["enabled"], json!(false));
    assert_eq!(starter["objectives"][0]["kind"], "visit_position");
    assert_eq!(starter["objectives"][1]["kind"], "client_reported");
    assert_eq!(
        starter["objectives"][1]["trigger"],
        json!({"type": "first_movement", "mouse": false})
    );
    for (original, regional) in &crosswalk {
        if *original != 1811 {
            let (enabled, objectives) = offerable[&u64::from(*regional)];
            assert!(
                !enabled || objectives == 0,
                "unsupported mapping {original} -> {regional} must stay unavailable"
            );
        }
    }
}

