                "prerequisite_quest_ids": [],
                "objectives": [{
                    "kind": "interact_actor",
                    "id": INTERACT_OBJECTIVE,
                    "actor_guid": actor_id,
                    "source": source.clone()
                }],
                "rewards": [{
                    "coins": 7,
                    "items": [],
                    "job_xp": {},
                    "source": source.clone()
                }],
                "source": source.clone()
            },
            {
                "id": DUNGEON_QUEST,
                "title_string_id": 2,
                "giver_npc_id": INTERACT_ACTOR,
                "prerequisite_quest_ids": [],

