            .replies
            .iter()
            .map(|packet| String::from_utf8_lossy(packet))
            .collect::<Vec<_>>()
    );
    assert_eq!(active_job(game), profile);
}

fn introduce_yourself(game: &mut Gameplay, character: &CharacterState, now: &mut u64) {
    let merigold = CharacterState {
        guid: character.guid,
        ..character_at(MERIGOLD)
    };
    *now += 10;
