};
use std::{collections::BTreeMap, path::PathBuf};

const CHARACTER: u64 = 7;
const QUEST_GIVER: u64 = 9_000_000_047;
const EMPTY_QUEST: u32 = 3_110_005;
const VALID_QUEST: u32 = 3_110_006;

