quest_offer_reward.excerpt:
//! T318: the 49/1 quest offer card carries the offered quest's authored reward.
//!
//! The offer card and the turn-in screen read the same `ClientRewardBundle` body:
//! - 49/1 `QuestInfoPacket` reader `00c7bb60` -> `ReadFields` `00c7b7a0` reads six
//!   dwords (quest id + five screen fields), a bool, then calls the shared bundle
//!   reader `sub_8E7930`: the body starts at packet offset 31 (6-byte header, quest id,
//!   five fields, bool), followed by an 8-byte actor, a float and two bools (the final
//!   14 bytes).
//! - 49/13 `QuestEndPacket::ReadFields` `00c7b990` reads the 8-byte actor, quest id,
//!   end text and animation dword, then calls the same `sub_8E7930` at packet offset
//!   26, then a trailing float.
//!
//! IDA xrefs to `0x008e7930` list both callers: `sub_C7B7A0+0x10c` and
//! `sub_C7B990+0xab`. The reader starts with the success byte (bundle+0) and the
//! coin dword (bundle+1..5); the next dword is the summed job-XP stars
//! (bundle+5..9); after 6 i32, a float, two i32 and two u64 the counted display rows
//! start at bundle+65 (row count at bundle+61..65). The 69-byte empty base is
//! 1 + 6*4 + 4 + 2*4 + 2*8 + 3*4 + 4, and a populated reward appends counted rows.
//!
//! These tests drive the production in-world router (`Gameplay::handle_in_world` ->
//! `gameplay/npc.rs` -> `QuestEngine`) with the same 26/8, 26/10, 26/6, 49/2 and
//! 49/14 packets the gateway accepts, so the bytes are the bytes a client receives.

#[path = "support/npc_quest_chain.rs"]
mod npc_quest_chain;

use npc_quest_chain::{
    Fixture, accept, assert_packet_changes_nothing, character_at_for, coins, content_dir,
    end_screen_reward, finish_quest, offer, pending_turnin, profile_xp, quest_end_reply,
    release_end_screen, talk_step,
};
use osfr_tools::{
    character_store::CharacterState,
    gameplay::Gameplay,
    npc_interaction::{NpcInteraction, decode_quest_offer_49_1},
    quest_engine::{CharacterEligibility, QuestEngine, QuestProgress, QuestStatus},
};

const CHARACTER: u64 = 318_001;
/// Adventurer, the profile the paying test quests use.
const ADVENTURER: i32 = 1;
/// Cobblestone Village giver 9000000189; gives quest 3000021 ("Introduce Yourself").
const COBBLESTONE_GIVER: u64 = 9_000_000_189;
/// Ricky Danger 9_500_000_254, the one-talk objective target of quest 3000021.
const COBBLESTONE_TARGET: u64 = 9_500_000_254;
/// Grumpore 9000000337; gives the no-reward quest 3100020.
const MINER_GIVER: u64 = 9_000_000_337;
/// 3100020's prerequisite. Later content disabled it, so the test restores the
/// completed-quest save state that `repair_counters` preserves for exactly this case.
const DISABLED_PREREQUISITE: u32 = 3_100_019;
/// One Talk, 5 coins and 20 Adventurer XP, no items and no display rows.
const REWARD_QUEST: u32 = 3_000_021;
/// Enabled record with empty `rewards`, so its bundle is the 69-byte base.
const EMPTY_REWARD_QUEST: u32 = 3_100_020;
/// Greenwood Forest giver 9000000444; quest 3000024 pays 13 coins and 25 Adventurer XP.
const SECOND_GIVER: u64 = 9_000_000_444;
const SECOND_REWARD_QUEST: u32 = 3_000_024;

fn character_at(guid: u64, npc_id: u64) -> CharacterState {
    let content = content_dir();
    let (zone_id, position) =
        NpcInteraction::load(&content.join("npcs"), &content.join("stores.json"))
            .expect("NPC content loads")
            .location(npc_id)
            .unwrap_or_else(|| panic!("NPC {npc_id} is a positioned content spawn"));
    character_at_for(guid, zone_id, position)
}

/// The production split catalogue for one character; the display GUIDs are
/// character-owned, so the accessor must be built with the same character id.
fn engine(character_id: u64) -> QuestEngine {
    QuestEngine::from_split_content(
        &content_dir(),
        character_id,
        CharacterEligibility::default(),
        None,
    )
    .expect("split quest content loads")
}

/// A session whose save already completed 3100020's prerequisite before content
/// disabled it: `repair_counters` preserves that historical progress, and the real
/// Talk path then offers the enabled no-reward quest. No other enabled quest has an
/// empty reward and an offerable giver on this content.
fn game_with_completed_prerequisite(fixture: &Fixture) -> Gameplay {
    let mut state = fixture.game(None).state();
    state
        .npc_quests
        .as_mut()
        .expect("the fixture binds the quest catalogue")
        .quests
        .insert(
            DISABLED_PREREQUISITE,
            QuestProgress {
                status: QuestStatus::Completed,
                counts: Vec::new(),
            },
        );
    fixture.game(Some(state))
}

fn offer_packet(offered: &osfr_tools::gameplay::Outcome) -> Vec<u8> {
    let packets: Vec<_> = offered
        .replies
        .iter()
        .filter(|packet| packet.starts_with(&[49, 0, 1, 0]))
        .cloned()
        .collect();
    assert_eq!(packets.len(), 1, "one Talk offers exactly one quest");
    packets.into_iter().next().unwrap()
}

/// The 49/1 fields after the bundle: the runtime actor the client clicked (8 bytes),
/// one unresolved dword (the float) and two (R) bools.
fn assert_trailing_fields(packet: &[u8], actor: u64) {
    assert!(packet.len() >= 14);
    let tail = &packet[packet.len() - 14..];
    assert_eq!(
        u64::from_le_bytes(tail[..8].try_into().unwrap()),
        actor,
        "the offer's trailing actor is the clicked NPC"
    );
    assert_eq!(&tail[8..], &[0; 6], "float bits and both bools are zero");
}

fn assert_no_grant(
    game: &Gameplay,
    inventory_before: &osfr_tools::inventory::InventoryState,
    coins_before: u32,
    xp_before: u32,
    label: &str,
) {
    assert_eq!(coins(game), coins_before, "{label}: coins changed");
    assert_eq!(
        &game.state().inventory,
        inventory_before,
        "{label}: inventory changed"
    );
    assert_eq!(
        profile_xp(game, ADVENTURER),
        xp_before,
        "{label}: job XP changed"
    );
}

#[test]
fn the_offer_card_carries_the_authored_reward() {
    let fixture = Fixture::for_character(CHARACTER);
    let mut game = fixture.game(None);
    let character = character_at(CHARACTER, COBBLESTONE_GIVER);
    let offered = offer(
        &mut game,
        &character,
        COBBLESTONE_GIVER,
        REWARD_QUEST,
        1_000,
    );
    let packet = offer_packet(&offered);
    let decoded = decode_quest_offer_49_1(&packet).expect("the offered 49/1 decodes");
    assert_eq!(decoded.quest_id, REWARD_QUEST);

    let bundle = engine(CHARACTER)
        .quest_reward_bundle(REWARD_QUEST)
        .expect("the authored reward encodes");
    assert_eq!(
        decoded.reward_bundle_body, bundle,
        "the card carries the same bundle the 49/13 turn-in builds"
    );
    // No enabled content record authors display rows, so the real cardinality is
    // the 69-byte base; the coin and star words are no longer zeros.
    assert_eq!(decoded.reward_bundle_body.len(), 69);
    assert_eq!(
        i32::from_le_bytes(bundle[1..5].try_into().unwrap()),
        5,
        "the card's coin word is the authored reward"
    );
    assert_eq!(
        i32::from_le_bytes(bundle[5..9].try_into().unwrap()),
        20,
        "the card's star word is the summed job XP"
    );
    assert_eq!(
        i32::from_le_bytes(bundle[61..65].try_into().unwrap()),
        0,
        "the record authors no display rows"
    );
    assert_ne!(
        bundle,
        vec![0; 69],
        "the offer no longer sends the all-zero placeholder"
    );
    assert_trailing_fields(&packet, COBBLESTONE_GIVER);
}

#[test]
fn an_empty_reward_quest_still_sends_the_69_byte_base() {
    let fixture = Fixture::for_character(CHARACTER);
    let mut game = game_with_completed_prerequisite(&fixture);
    let character = character_at(CHARACTER, MINER_GIVER);
    let offered = offer(
        &mut game,
        &character,
        MINER_GIVER,
        EMPTY_REWARD_QUEST,
        2_000,
    );
    let packet = offer_packet(&offered);
    let decoded = decode_quest_offer_49_1(&packet).expect("the offered 49/1 decodes");
    assert_eq!(decoded.quest_id, EMPTY_REWARD_QUEST);

    let bundle = engine(CHARACTER)
        .quest_reward_bundle(EMPTY_REWARD_QUEST)
        .expect("an empty reward still encodes");
    assert_eq!(decoded.reward_bundle_body, bundle);
    assert_eq!(decoded.reward_bundle_body.len(), 69);
    assert_eq!(
        i32::from_le_bytes(bundle[1..5].try_into().unwrap()),
        0,
        "no coins"
    );
    assert_eq!(
        i32::from_le_bytes(bundle[5..9].try_into().unwrap()),
        0,
        "no stars"
    );
    assert_eq!(
        u64::from_le_bytes(bundle[37..45].try_into().unwrap()),
        MINER_GIVER,
        "the display source GUID is the quest's giver"
    );
    assert_eq!(
        u64::from_le_bytes(bundle[45..53].try_into().unwrap()),
        CHARACTER,
        "the display player GUID is this character"
    );
    assert_trailing_fields(&packet, MINER_GIVER

quest_pickup_nodes.excerpt:
//! T503: quest-only pickup nodes with a counted `collect_node` goal, proved end to end
//! by A Booming Problem (`3000361`, Heddy Heathcliff, 5 tin ore).
//!
//! Every test drives the production router: a 26/8 click through `Gameplay::handle_in_world`,
//! the split quest loader through `Fixture::game_as`, the offer/accept/turn-in packets of
//! `tests/support/npc_quest_chain.rs` (49/1, 49/2, 26/3/26/6, 49/13, 49/14) and the 49/9
//! objective update. The node content is `data/content/quest_nodes.json`, copied into the
//! private fixture so `GatheringNodes::load` reads it the way a session does.
//!
//! Client wire, unchanged (the pickup adds no packet):
//! - 26/8 interact: constructor `0x008b6bc0` (two caller words = u64 target, one flag byte),
//!   sender `0x0092efe0`; decoded by `decode_npc_interact_26_8`.
//! - 49/9 objective update: reader `0x00c7af60` reads quest, objective and current counters,
//!   then the progress float, a notification byte and one unresolved dword; encoded by
//!   `QuestMessage::encode_exact`.
//! - 35/2 add and 35/3 remove: the existing node visibility path (`NpcVisibility::refresh`).

#[path = "support/npc_quest_chain.rs"]
mod npc_quest_chain;

use npc_quest_chain::{
    CHARACTER, Fixture, accept, character_at_for, coins, content_dir, content_position, counts,
    end_screen_reward, finish_quest, npc_interact, objective_activated, objective_complete,
    objective_update, offer, pending_turnin, profile_xp, quest_status, release_end_screen, saved,
    seed_active_profile, send, talk, zone_player,
};
use osfr_tools::{
    gameplay::{Gameplay, Outcome},
    harvest_nodes::{GatheringNodes, NodeActor, NodeChange},
    mining::MINER_PROFILE_ID,
    quest_engine::QuestStatus,
};
use serde_json::{Value, json};
use std::{
    collections::BTreeSet,
    fs, io,
    path::{Path, PathBuf},
    sync::atomic::{AtomicU64, Ordering},
};

const HEDDY: u64 = 9_500_000_588;
const QUEST: u32 = 3_000_361;
const ADVENTURER: i32 = 1;
/// A Booming Problem's fork reward (R): 40 coins and the T202 collect rung of 25 XP.
const COINS: u32 = 40;
const XP: u32 = 25;
const END_TEXT: u32 = 400_436;
const RESPAWN_MS: u64 = 30_000;
const OTHER: u64 = CHARACTER + 1;
static NEXT: AtomicU64 = AtomicU64::new(0);

fn fixture() -> Fixture {
    // The opening content is required by `Gameplay::load` whenever mining.json is
    // present (the busy case starts a real mining run), so this is `new`, not `minimal`.
    let fixture = Fixture::new();
    fixture.overlay_content(&content_dir());
    // This slice starts no Type8 harvesting, and the opening fixture's inventory has no
    // harvesting reward rows; drop the overlayed opt-in board instead of fabricating items.
    let harvesting = fixture.path().join("harvesting.json");
    if harvesting.is_file() {
        fs::remove_file(&harvesting).expect("drop the unused harvesting board");
    }
    fixture
}

fn shipped_nodes() -> GatheringNodes {
    GatheringNodes::load(&content_dir())
        .expect("the shipped node tables load")
        .expect("the shipped node tables are present")
}

fn node_named(name: &str) -> NodeActor {
    shipped_nodes()
        .actors()
        .find(|actor| actor.name == name)
        .unwrap_or_else(|| panic!("a {name} node is shipped"))
        .clone()
}

fn tin_ore() -> Vec<NodeActor> {
    let mut rows: Vec<NodeActor> = shipped_nodes()
        .actors()
        .filter(|actor| actor.name == "Tin Ore")
        .cloned()
        .collect();
    rows.sort_by_key(|actor| actor.guid);
    rows
}

/// The client's click (26/8) on `guid` from `position`, after the location report and the
/// pose-driven NPC view update a moving player sends (which is what puts the node in this
/// character's visible set, so the click's `NpcVisibility::refresh` can remove it).
fn click_from(
    game: &mut Gameplay,
    player: u64,
    guid: u64,
    zone_id: u32,
    position: [f32; 3],
    now: u64,
) -> Outcome {
    let character = character_at_for(player, zone_id, position);
    game.on_location(&character, now)
        .expect("the location report is accepted");
    game.update_npc_visibility(&character)
        .expect("the NPC view update is served");
    send(game, &character, &npc_interact(guid), now + 1)
}

fn has_guid(packet: &[u8], guid: u64) -> bool {
    packet.windows(8).any(|window| window == guid.to_le_bytes())
}

fn removed(outcome: &Outcome, guid: u64) -> bool {
    outcome
        .replies
        .iter()
        .any(|packet| packet.starts_with(&[35, 0, 3, 0]) && has_guid(packet, guid))
}

fn added(outcome: &Outcome, guid: u64) -> bool {
    outcome
        .replies
        .iter()
        .any(|packet| packet.starts_with(&[35, 0, 2, 0]) && has_guid(packet, guid))
}

fn said(outcome: &Outcome, needle: &str) -> bool {
    outcome.replies.iter().any(|packet| {
        if !packet.starts_with(&[15, 0, 3, 0]) || packet.len() < 9 {
            return false;
        }
        let length = u32::from_le_bytes(packet[4..8].try_into().unwrap()) as usize;
        packet
            .get(8..8 + length)
            .is_some_and(|text| String::from_utf8_lossy(text).contains(needle))
    })
}

fn at(player: u64, npc: u64) -> osfr_tools::character_store::CharacterState {
    character_at_for(player, 0, content_position("seaside.json", npc))
}

/// Offer and accept A Booming Problem at Heddy.
fn accept_booming(game: &mut Gameplay, player: u64, now: &mut u64) {
    let heddy = at(player, HEDDY);
    offer(game, &heddy, HEDDY, QUEST, *now);
    accept(game, &heddy, QUEST, *now + 2);
    *now += 20;
}

/// One pickup click; returns the outcome and the exact timestamp the handler saw.
fn pick(game: &mut Gameplay, player: u64, node: &NodeActor, now: &mut u64) -> (Outcome, u64) {
    let clicked_at = *now + 1;
    let clicked = click_from(game, player, node.guid, 0, node.position, *now);
    *now += 10;
    (clicked, clicked_at)
}

fn tick(game: &mut Gameplay, now: u64) -> Outcome {
    game.tick(&character_at_for(CHARACTER, 0, [0.0, 0.0, 0.0]), now)
        .unwrap_or_else(|error| panic!("tick at {now}: {error}"))
}

fn mining_active(game: &Gameplay) -> bool {
    serde_json::to_value(game.state()).unwrap()["mining"]["active"].is_object()
}

/// The five pickups of A Booming Problem, asserting each counted update; returns the
/// timestamp of the fifth click.
fn pick_all_five(game: &mut Gameplay, player: u64, now: &mut u64) -> u64 {
    let nodes = tin_ore();
    assert_eq!(nodes.len(), 5, "five tin-ore spawns are shipped");
    let mut last = *now;
    for (index, node) in nodes.iter().enumerate() {
        let current = index as u32 + 1;
        let (clicked, clicked_at) = pick(game, player, node, now);
        last = clicked_at;
        assert!(
            !said(&clicked, "You don't need that right now."),
            "pickup {current} was refused"
        );
        assert!(
            removed(&clicked, node.guid),
            "pickup {current} must hide the node for this player"
        );
        assert!(
            objective_update(&clicked, QUEST, 1, current),
            "pickup {current} must send the counted 49/9 update"
        );
        assert_eq!(counts(game, QUEST), [current, 0]);
        if current == 5 {
            assert!(
                objective_complete(&clicked, QUEST, 1),
                "the fifth pickup completes the collect step"
            );
            assert!(
                objective_activated(&clicked, QUEST, 2),
                "the ordered talk step opens after the collect step"
            );
        }
    }
    last
}

fn turn_in(game: &mut Gameplay, player: u64, now: u64) {
    let heddy = at(player, HEDDY);
    let talked = talk(game, &heddy, HEDDY, now);
    assert!(talked.changed, "the final Talk advances the talk step");
    assert_eq!(pending_turnin(game), Some(QUEST));
    let end = release_end_screen(game, &heddy, QUEST, HEDDY, END_TEXT, now + 2);
    assert_eq!(end_screen_reward(&end), (COINS, XP));
    finish_quest(game, &heddy, QUEST, ADVENTURER, COINS, XP, now + 4);
}

