    for bad in [vec![26, 0, 24, 0], vec![26, 0, 24, 0, 1, 0, 0, 0, 0]] {
        // The gateway drops a rejected single packet; nothing may change.
        let _ = g.handle_at(&wrap(&bad), 1000);
        assert_same(&g.snapshot(), &ready, "malformed");
    }
}

