    }
}

fn reward_state(wallet: Wallet, ceiling: u32) -> RewardState {
    RewardState::new(inventory(), profiles(), 100).with_wallet(wallet, ceiling)
}

fn sc_grant(sc: u32) -> RewardGrant {
