    };
    let source = json!([{"kind":"reconstructed","evidence":"(R) synthetic bound test"}]);
    let base = json!({
        "schema_version": 1,
        "enabled": true,
        "kart_race": 3,
        "derby_match": 3,
        "soccer_match": 3,
        "chess_game": 2,
        "dungeon_clear": 10,
        "hardest_dungeon_clear": 25,
        "hardest_dungeons": [411],
        "quest_complete": 1,
        "daily_first_activity": 5,
        "source": source,
    });
    assert!(
        EarnTable::load(&directory.join("absent.json"))
            .unwrap()
