    write("stray-ride.json", stray_ride);
    assert!(
        EarnTable::load(&directory.join("stray-ride.json")).is_err(),
        "the first-clear ride must name a hardest dungeon"
    );

    let mut unknown = base.clone();
    unknown["mystery"] = json!(1);
