snowhill_reference_placements.excerpt:
//! T695: Snowhill's remaining undrawn NPC rows stand at the one reference spawn that
//! names them.
//!
//! `lab/fleet/quests/talk_spawns.py` joins a regional NPC row to a FreeRealms-Legacy /
//! Sanctuary-main spawn by the client name the spawn's `Npcs.json` NameId resolves. The
//! rows this brief places (`PLACED`, by id) are `legacy_data` / `legacy_data_spawn`, the
//! only placement `world.rs` draws from `npcs/*.json`. They are sent as the ordinary
//! 35/2 AddNpc body: u64 actor, i32 name id, i32 model id, then the transform (client
//! reader `0x00921a10`). No new wire shape.

#[path = "support/npc_quest_chain.rs"]
mod npc_quest_chain;
#[path = "support/placement.rs"]
mod placement;

use npc_quest_chain::{content_dir, read_json, seen_from};
use osfr_tools::{startup_world::NpcSpawn, world::NpcVisibility};
use placement::{distance, drawn_npcs};
use serde_json::Value;
use std::{collections::BTreeSet, path::Path};

/// The six rows this brief placed, by npc_id (R: the data decides the spawn; the ids are
/// the brief's list, so a copy edit can never silently drop one from the check).
const PLACED: [u64; 6] = [
    9_000_000_020,
    9_500_000_729,
    9_000_000_069,
    9_000_000_115,
    9_500_000_766,
    9_000_000_201,
];

fn rows(path: &Path) -> Vec<Value> {
    read_json(path)["records"]
        .as_array()
        .unwrap_or_else(|| panic!("{}: records", path.display()))
        .clone()
}

fn position(row: &Value) -> [f32; 3] {
    serde_json::from_value(row["position"].clone())
        .unwrap_or_else(|error| panic!("NPC {}: position: {error}", row["npc_id"]))
}

/// The brief's rows: all six exist, are `legacy_data` and come from the Legacy spawn table.
fn placed_rows() -> Vec<Value> {
    let all = rows(&content_dir().join("npcs/snowhill.json"));
    PLACED
        .iter()
        .map(|id| {
            let row = all
                .iter()
                .find(|row| row["npc_id"].as_u64() == Some(*id))
                .unwrap_or_else(|| panic!("{id}: no Snowhill row"));
            assert_eq!(row["placement"], "legacy_data", "{id}: placement");
            assert_eq!(row["placement_source"], "legacy_data_spawn", "{id}: source");
            row.clone()
        })
        .collect()
}

#[test]
fn every_row_this_brief_placed_is_drawn_at_its_spawn_position() {
    let placed = placed_rows();
    let base = NpcVisibility::load(&content_dir()).unwrap();
    for row in &placed {
        let id = row["npc_id"].as_u64().unwrap();
        let owner = format!("{id} ({})", row["name"].as_str().unwrap_or("unnamed"));
        let expected = position(row);
        let seen = seen_from(&base, expected);
        let mine: Vec<&NpcSpawn> = seen.iter().filter(|npc| npc.actor_id == id).collect();
        assert_eq!(mine.len(), 1, "{owner}: drawn {} times", mine.len());
        let drawn_position = [
            mine[0].position[0],
            mine[0].position[1],
            mine[0].position[2],
        ];
        assert_eq!(drawn_position, expected, "{owner}: drawn position");
        assert_eq!(
            mine[0].model_id,
            row["model_id"].as_i64().unwrap() as i32,
            "{owner}: model id"
        );
        assert_eq!(
            mine[0].name_string_id,
            row["name_string_id"].as_i64().unwrap() as i32,
            "{owner}: name string id"
        );
        for other in &seen {
            if other.actor_id == id {
                continue;
            }
            let other_position = [other.position[0], other.position[1], other.position[2]];
            let gap = distance(other_position, expected);
            assert!(
                gap > 1.0,
                "{owner}: drawn actor {} stands {gap:.2} m away",
                other.actor_id
            );
        }
    }
}

/// Every content-keyed NPC the loader draws (`legacy_data` regional rows and extras bodies
/// bound to a regional row) is a distinct actor and stands more than a metre from every
/// other. The set is the loader's own (`drawn_npcs`); unnamed scene props carry no key and
/// legitimately overlap.
#[test]
fn drawn_npc_rows_do_not_share_a_position() {
    let drawn: Vec<_> = drawn_npcs(&NpcVisibility::load(&content_dir()).unwrap())
        .into_iter()
        .filter(|npc| npc.content_key.is_some())
        .collect();
    for id in PLACED {
        assert!(
            drawn.iter().any(|npc| npc.actor == id),
            "{id}: the placement scan must include this brief's row"
        );
    }
    let actors: BTreeSet<_> = drawn.iter().map(|npc| npc.actor).collect();
    assert_eq!(actors.len(), drawn.len(), "an actor id is drawn twice");
    for (index, left) in drawn.iter().enumerate() {
        for right in &drawn[index + 1..] {
            let gap = distance(left.position, right.position);
            assert!(
                gap > 1.0,
                "actors {} and {} stand {gap:.2} m apart",
                left.actor,
                right.actor
            );
        }
    }
}

soccer.excerpt:
//! Focused tests for the bounded Soccer codec and reconstructed reducer.
//!
//! Every fixture in this file is built explicitly from synthetic field values
//! through the production codec's own `encode`. Raw captured bytes are not
//! embedded (AGENTS: raw captures live in the lab, tests are synthetic); the
//! optional lab corpus gate is a byte-codec smoke check only and is not used as
//! client behavior evidence.

use osfr_tools::soccer::{
    self, Direction, Evidence, Match, Message, Phase, SoccerPacket, decode, encode,
};

fn close(actual: [f32; 3], expected: [f32; 3], tolerance: f32) -> bool {
    actual
        .iter()
        .zip(expected.iter())
        .all(|(a, e)| (a - e).abs() <= tolerance)
}

fn frame(packet: SoccerPacket) -> Vec<u8> {
    encode(&Message {
        outer: 5,
        flag: true,
        packet,
    })
}

fn frame_with_flag(flag: bool, packet: SoccerPacket) -> Vec<u8> {
    encode(&Message {
        outer: 5,
        flag,
        packet,
    })
}

fn vec_goal() -> Vec<u8> {
    frame(SoccerPacket::GoalMade { fields: [0, 1, 1] })
}

fn vec_register(player: u64) -> Vec<u8> {
    frame(SoccerPacket::RegisterPlayer {
        player,
        marker: [0, 1],
    })
}

fn vec_team(player: u64, team: u32, slot: u32) -> Vec<u8> {
    frame(SoccerPacket::SetPlayerTeam { player, team, slot })
}

fn vec_colours() -> Vec<u8> {
    frame(SoccerPacket::TeamColours {
        team_a_name: "synthetic-a".to_string(),
        team_b_name: "synthetic-b".to_string(),
        team_a_rgba: [255, 100, 35, 0],
        team_b_rgba: [15, 50, 255, 0],
        team_a_id: 1001,
        team_b_id: 1002,
        tail: [0],
    })
}

fn vec_time(remaining: f32, elapsed: f32) -> Vec<u8> {
    frame(SoccerPacket::UpdateGameTime { remaining, elapsed })
}

fn identity_ball(position: [f32; 3], velocity: [f32; 3]) -> Vec<u8> {
    let mut transform = [0.0f32; 16];
    transform[0] = 1.0;
    transform[5] = 1.0;
    transform[10] = 1.0;
    transform[12] = position[0];
    transform[13] = position[1];
    transform[14] = position[2];
    transform[15] = 1.0;
    frame(SoccerPacket::UpdateSoccerBall {
        transform,
        velocity,
        tail: [0; 15],
    })
}

fn vec_config() -> Vec<u8> {
    let asset = "synthetic-soccer-ball.adr";
    let spawn = [3.0f32, 1.0, 4.0, 1.0];
    let mut raw = vec![0u8; 221];
    raw[124..128].copy_from_slice(&(asset.len() as u32).to_le_bytes());
    raw[128..128 + asset.len()].copy_from_slice(asset.as_bytes());
    for (index, value) in spawn.iter().enumerate() {
        raw[157 + index * 4..161 + index * 4].copy_from_slice(&value.to_le_bytes());
    }
    frame(SoccerPacket::SetClientConfig {
        raw,
        ball_asset: asset.to_string(),
        ball_spawn: spawn,
    })
}

fn vec_player_pos() -> Vec<u8> {
    frame_with_flag(
        false,
        SoccerPacket::UpdatePlayerPos {
            player: 0x0000_0010_0080_06b2,
            position: [7.25, 0.0, 9.5],
            tail: [0; 45],
        },
    )
}

fn vec_player_state() -> Vec<u8> {
    frame(SoccerPacket::UpdatePlayerState {
        player: 0x0000_0010_0080_06b2,
        state: 2,
        aux: 0,
        state_counter: 1,
        vectors: [
            [0.0, 1.0, 0.0, 0.0],
            [0.8, 0.0, 0.6, 0.0],
            [7.25, 0.0, 9.5, 1.0],
        ],
    })
}

fn vec_controls() -> Vec<u8> {
    frame(SoccerPacket::UpdatePlayerControls {
        player: 0x0000_0010_0080_06b2,
        direction: [0.0, -1.0],
        controls: 0,
    })
}

fn all_vectors() -> Vec<Vec<u8>> {
    let mut vectors = vec![
        vec_goal(),
        vec_colours(),
        vec_time(0.0, 0.5),
        vec_time(120.0, 1.0),
        vec_time(110.0, 5.0),
        identity_ball([3.0, 1.0, 4.0], [0.0, 0.0, 0.0]),
        identity_ball([3.2, 1.8, 3.8], [0.4, 2.5, -0.2]),
        vec_config(),
        vec_player_pos(),
        vec_player_state(),
        vec_controls(),
    ];
    for player in [0x0000_0010_0080_06b2, 0x0000_0070_0080_06b2] {
        vectors.push(vec_register(player));
    }
    for (player, team, slot) in roster() {
        vectors.push(vec_team(player, team, slot));
    }
    vectors
}

fn roster() -> [(u64, u32, u32); 8] {
    [
        (0x4b52_cc6a_9573_ca91u64, 0u32, 0u32),
        (0x0000_0010_0080_06b2, 0, 1),
        (0x0000_0020_0080_06b2, 0, 2),
        (0x0000_0030_0080_06b2, 0, 3),
        (0x0000_0040_0080_06b2, 1, 0),
        (0x0000_0050_0080_06b2, 1, 1),
        (0x0000_0060_0080_06b2, 1, 2),
        (0x0000_0070_0080_06b2, 1, 3),
    ]
}

fn match_session() -> Match {
    let mut game = Match::new();
    game.handle(Direction::ServerToClient, &vec_colours())
        .unwrap();
    for (player, team, slot) in roster() {
        game.handle(Direction::ServerToClient, &vec_team(player, team, slot))
            .unwrap();
    }
    for index in 0..=6u64 {
        game.handle(
            Direction::ServerToClient,
            &vec_register(0x0000_0010_0080_06b2u64 + index * 0x10_0000_0000),
        )
        .unwrap();
    }
    game
}

#[test]
fn session_registration_builds_four_v_four_roster() {
    let game = match_session();
    let session = game.session();
    assert_eq!(session.teams[0].name, "synthetic-a");
    assert_eq!(session.teams[1].name, "synthetic-b");
    assert_eq!(session.teams[0].colour_rgba, [255, 100, 35, 0]);
    assert_eq!(session.teams[1].colour_rgba, [15, 50, 255, 0]);
    assert_eq!(session.roster.len(), 8);
    assert_eq!(session.roster_of_team(0).count(), 4);
    assert_eq!(session.roster_of_team(1).count(), 4);
    assert_eq!(game.player_team(0x4b52_cc6a_9573_ca91), Some((0, 0)));
    assert_eq!(game.player_team(0x0000_0030_0080_06b2), Some((0, 3)));
    assert_eq!(game.player_team(0x0000_0040_0080_06b2), Some((1, 0)));
    assert_eq!(game.player_team(0x0000_0070_0080_06b2), Some((1, 3)));
}

#[test]
fn kickoff_starts_half_clock() {
    let mut game = match_session();
    let pre = decode(&vec_time(0.0, 0.5)).unwrap();
    match pre.packet {
        SoccerPacket::UpdateGameTime { remaining, elapsed } => {
            assert_eq!(remaining, 0.0);
            assert!((elapsed - 0.5).abs() < 0.001);
        }
        other => panic!("unexpected {other:?}"),
    }
    game.handle(Direction::ServerToClient, &vec_time(0.0, 0.5))
        .unwrap();
    assert_eq!(game.phase(), Phase::Lobby);

    game.handle(Direction::ServerToClient, &vec_time(120.0, 1.0))
