            AbilitySetEntry {
                kind: 0,
                serialized_fields: &[],
            }
        })
        .collect::<Vec<_>>();
    assert_eq!(12 + count * 4, bytes.len());
    assert_eq!(
        startup_catalogues::build_ability_set_definition(AbilitySetDefinition {
            id,
            entries: &entries,
        }),
