        count_definition(&before.0, RIDE_ITEM) + 1
    );
    // No coin path ran.
    assert_eq!(shop.inventory().state().coins, before.0.coins);
    assert_eq!(shop.sc_wallet().orders.len(), 1);
    // 66/4 full layout (`00b2ded0`, T453): tracking id, result, order-id st

