    assert_eq!(starts[0].bytes.len(), 39);
    assert_eq!(&starts[0].bytes[..3], &[0x3b, 0, 4]);
    assert_eq!(
        u64::from_le_bytes(starts[0].bytes[3..11].try_into().unwrap()),
