                "index": 0,
                "value": goal_value,
                "quota": quota,
                "per_reward": 1,
                "icon_id": 706,
            }],
            "outputs": [],
            "duration_seconds": 180,
            "seed": 111,
            "wildcard_percent": 0,
            "collectable_percent": 0,
            "blocker_percent": 0,
            "powerup_percent": 0,
            "meter_id": 0,
            "reconstructed_rules": true,
            "rule_notice": "Synthetic private Type8 repair fixture. Original server level tables unrecovered.",
        }
