vendor_buy_sell_gateway.excerpt:
//! T374: the vendor round trip through the real gateway. A player opens the shipped
//! representative vendor, buys one stock row (66/43), the canonical save holds the new
//! wallet/bag, a relog reads it back, and the same item sells once through 165/5 — with every
//! refusal asserted to change neither `Gateway::snapshot()` nor the serialized save.
//!
//! Wire bodies are the shipped client's, re-checked in IDA:
//! - 26/8 interact constructor `0x008b6bc0` (u64 target + bool);
//! - 26/10 select constructor `0x00a36f80` (u64 target + i32 choice);
//! - 165/10 coin merchant list: handler `0x00c78fb0` (header `0x00c71d90`, the shared record
//!   `0x00b33020` and row `0x00b29cd0` readers) raises `HandlerMerchant:Show("CoinStore")`
//!   (`0x00c78c10`); the row's displayed coin price is the item definition `+0x24`
//!   (`0x00cff140` case 27), not a row field;
//! - 66/43 buy serializer `0x00b3ab20`; its request constructor is `0x00b43310`;
//! - 66/44 result reader `0x00b32430`; `0x00b48a10` tests field `+0x58` (wire offset 48)
//!   against 1;
//! - 165/5 sell writer `0x00c75a70`, fields set by `0x00c76dd0`, Lua entry `0x00c77030`
//!   (which passes the null merchant GUIDs `0x01beea08`);
//! - 165/6 completion reader `0x00c74ef0` -> `0x00c71f30`; `0x00c78220` compares the first
//!   record dword (wire offset 4) with 1.
//!
//! No new wire shape is introduced: every request comes from the shared
//! `tests/common/gateway_vendor.rs` helpers, priced stock comes from the shared
//! `tests/common/vendor_fixture.rs`, and the save/relog is the real `game_store` envelope plus
//! the shared `connect_with` helper.

#[path = "common/gateway_vendor.rs"]
mod gateway_vendor;
#[path = "common/vendor_fixture.rs"]
mod vendor_fixture;
// Keep the shared module's canonical test running in this target: the integration suite treats
// a test that disappears from a target as a regression. This suite itself uses only the shared
// helpers above (the module's representative buy/refusal proof still runs in
// `vendor_stock_coverage`).
#[path = "common/vendor_purchase.rs"]
#[allow(dead_code)]
mod vendor_purchase;

use gateway_vendor::{
    NOW, completions, connect_with, count_definition, fixture_root, inner_packets, interact,
    inventory_of, merchant_status, select, sell_packet, send, vendor_buy_packet, wrap,
};
use osfr_tools::{
    account_store::AccountRole,
    character_store::CharacterState,
    coin_shop,
    game_store::{self, Snapshot},
    gameplay::GameplayState,
    gateway::{Gateway, GatewayOutcome},
    inventory::InventoryState,
    npc_interaction::{
        MerchantBuyRequestV2, decode_coin_merchant_list_165_10, encode_merchant_buy_66_43,
    },
    world::NpcVisibility,
};
use std::{fs, path::PathBuf};
use vendor_fixture::{REPRESENTATIVE_ITEM, REPRESENTATIVE_VENDOR, SEEDED_ITEM, VendorFixture};

const RESULT_SUCCESS: u32 = coin_shop::RESULT_SUCCESS;

fn reconnect(fixture: &VendorFixture, character: CharacterState, state: GameplayState) -> Gateway {
    connect_with(fixture.reference(), character, fixture.content(), state)
}

fn connect(fixture: &VendorFixture, state: GameplayState) -> Gateway {
    reconnect(fixture, fixture.character(), state)
}

/// Open the representative vendor's 165/10 coin window and return the merchant record.
fn open_shop(fixture: &VendorFixture, gateway: &mut Gateway) -> Vec<u8> {
    send(gateway, &interact(REPRESENTATIVE_VENDOR));
    let replies = send(gateway, &select(REPRESENTATIVE_VENDOR, fixture.option()));
    replies
        .into_iter()
        .find(|packet| packet.starts_with(&[165, 0, 10, 0]))
        .expect("the representative vendor opens its 165/10 coin shop")
}

fn buy(gateway: &mut Gateway, transaction: u32, item: i32, quantity: u32) -> Vec<Vec<u8>> {
    send(gateway, &vendor_buy_packet(transaction, item, quantity))
}

fn buy_status(replies: &[Vec<u8>]) -> u32 {
    merchant_status(replies.last().expect("a 66/43 buy always answers 66/44"))
}

/// The one stack the purchase granted (the fixture seeds only `SEEDED_ITEM`).
fn bought_instance(state: &InventoryState) -> (i32, u32) {
    let mut matches = state
        .items
        .iter()
        .filter(|item| item.definition_id == REPRESENTATIVE_ITEM)
        .map(|item| (item.id, item.count));
    let first = matches.next().expect("the purchase granted the item");
    assert!(
        matches.next().is_none(),
        "the purchase granted more than one stack"
    );
    first
}

fn assert_unique_instance_ids(label: &str, state: &InventoryState) {
    let mut ids: Vec<i32> = state.items.iter().map(|item| item.id).collect();
    ids.sort_unstable();
    let total = ids.len();
    ids.dedup();
    assert_eq!(
        ids.len(),
        total,
        "{label}: inventory instance ids are not unique"
    );
}

/// Save files go into the private build output, never `%TEMP%`: no other local user can
/// pre-create the path and each file is removed as soon as it is read back.
fn save_path(label: &str) -> PathBuf {
    let directory = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join("vendor-buy-sell-gateway");
    fs::create_dir_all(&directory).expect("the test save directory creates");
    directory.join(format!("{label}.json"))
}

/// Serialize the whole gateway snapshot through the real save envelope and return its bytes.
fn saved_bytes(label: &str, snapshot: &Snapshot) -> Vec<u8> {
    let path = save_path(label);
    game_store::save(&path, snapshot).expect("the canonical game save writes");
    let bytes = fs::read(&path).expect("the canonical game save reads");
    let _ = fs::remove_file(&path);
    bytes
}

fn read_save(label: &str, snapshot: &Snapshot) -> Snapshot {
    let path = save_path(label);
    game_store::save(&path, snapshot).expect("the canonical game save writes");
    let loaded = game_store::load_or_create(&path, snapshot.character.clone())
        .expect("the canonical save loads");
    let _ = fs::remove_file(&path);
    loaded
}

/// Send one request through the real gateway and keep both the inner replies and the
/// outcome, so a refusal can assert that it requested no save at all.
fn handled(gateway: &mut Gateway, packet: &[u8]) -> (Vec<Vec<u8>>, GatewayOutcome) {
    let outcome = gateway
        .handle_at(&wrap(packet), NOW)
        .expect("gateway handles the request");
    let replies = inner_packets(&outcome);
    (replies, outcome)
}

/// A refused buy answers exactly one 66/44 status 0, requests no save and changes neither the
/// snapshot nor the save bytes.
fn refused_buy(gateway: &mut Gateway, label: &str, packet: &[u8]) {
    let before = gateway.snapshot();
    let before_save = saved_bytes(&format!("{label}-before"), &before);
    let (replies, outcome) = handled(gateway, packet);
    assert!(
        !outcome.gameplay_changed,
        "{label}: a refused buy requested a save"
    );
    assert!(
        !outcome.state_changed,
        "{label}: a refused buy changed the character state"
    );
    assert_eq!(
        replies.len(),
        1,
        "{label}: a refused buy answers exactly one 66/44"
    );
    assert_eq!(merchant_status(&replies[0]), 0, "{label}: not refused");
    assert_eq!(
        gateway.snapshot(),
        before,
        "{label}: the refused buy changed the snapshot"
    );
    assert_eq!(
        saved_bytes(&format!("{label}-after"), &gateway.snapshot()),
        before_save,
        "{label}: the refused buy changed the save bytes"
    );
}

/// A refused sell answers one 165/6 with the production result code, requests no save and
/// changes nothing.
fn refused_sell(gateway: &mut Gateway, label: &str, packet: &[u8], code: u32) {
    let before = gateway.snapshot();
    let before_save = saved_bytes(&format!("{label}-before"), &before);
    let (replies, outcome) = handled(gateway, packet);
    assert!(
        !outcome.gameplay_changed,
        "{label}: a refused sell requested a save"
    );
    assert!(
        !outcome.state_changed,
        "{label}: a refused sell changed the character state"
    );
    let done = completions(&replies);
    assert_eq!(done.len(), 1, "{label}: exactly one 165/6 completion");
    assert_eq!(done[0].result, code, "{label}: result code");
    assert_eq!(done[0].kind, 2, "{label}: completion kind is sell");
    assert_eq!(done[0].remaining, 0, "{label}: nothing to buy back");
    assert_eq!(
        gateway.snapshot(),
        before,
        "{label}: the refused sell changed the snapshot"
    );
    assert_eq!(
        saved_bytes(&format!("{label}-after"), &gateway.snapshot()),
        before_save,
        "{label}: the refused sell changed the save bytes"
    );
}

/// Byte-level pins for the request bodies this suite sends, derived from the client writers:
/// 26/8 `008b6bc0` (u64 target + bool), 26/10 `00a36f80` (u64 target + i32 choice), and 165/5
/// `00c75a70` with `00c76dd0`'s field order (u64 merchant, item instance, quantity). The 66/43
/// body is pinned by `vendor_stock_coverage::vendor_buy_wire_matches_the_client_read

vendor_coin_window.excerpt:
//! T362: Roosey's 165/10 coin merchant window lists her stock at the server prices.
//!
//! Client evidence: `00c78fb0` reads the 165/10 body (header, the six-dword merchant record
//! `00b33020`, count, then 38-byte rows `00b29cd0`), stores it in the merchant stock data source
//! and raises `HandlerMerchant:Show("CoinStore")` (`00c78c10`). The `NpcMerchantV2` window's
//! CoinStore mode displays that data source (`ScriptsBase.lua` `NpcMerchantV2:setMode`). The
//! row's coin price is the resolved item definition's `+0x24` (`00cff140` case 27; serialized
//! dword 7), not a row field, so the server pushes a 35/37 definition update whenever the loaded
//! definition differs from `stores.json`.

#[allow(dead_code)]
#[path = "common/gateway_vendor.rs"]
mod gateway_vendor;
#[path = "common/roosey_shop.rs"]
mod roosey_shop;
#[path = "common/round70_content.rs"]
mod round70_content;

use gateway_vendor::{NOW, count_definition, inner_packets, inventory_of, wrap};
use osfr_tools::{inventory::Inventory, npc_interaction::decode_coin_merchant_list_165_10};
use roosey_shop::{Fixture, ROOSEY, data, read_json};
use std::collections::BTreeMap;

const RING: i32 = 75_260;
const RING_PRICE: u32 = 75;
const STOCK: [i32; 6] = [75_030, 75_250, 75_260, 75_278, 75_294, 75_297];

/// Roosey's `stores.json` purchase prices.
fn stock_prices() -> BTreeMap<i32, u32> {
    let stores = read_json(&data().join("stores.json"));
    stores["items"]
        .as_array()
        .expect("store rows are an array")
        .iter()
        .filter_map(|row| {
            Some((
                row["item_id"].as_i64()? as i32,
                row["purchase_price_coins"].as_u64()? as u32,
            ))
        })
        .filter(|(id, _)| STOCK.contains(id))
        .collect()
}

/// The 35/37 batch the shop pushes, when any loaded definition price differs.
fn definition_batch(replies: &[Vec<u8>]) -> Option<&[u8]> {
    replies
        .iter()
        .find(|packet| packet.starts_with(&[35, 0, 37, 0]))
        .map(Vec::as_slice)
}

/// The 165/6 completion (`00c74ef0`): result at offset 4, then the transaction record.
fn coin_completion(packets: &[Vec<u8>]) -> &[u8] {
    packets
        .iter()
        .find(|packet| packet.starts_with(&[165, 0, 6, 0]))
        .map(Vec::as_slice)
        .expect("a 165/6 transaction completion follows a 165/4 buy")
}

fn word(packet: &[u8], at: usize) -> u32 {
    u32::from_le_bytes(packet[at..at + 4].try_into().expect("packet field"))
}

#[test]
fn roosey_coin_window_lists_her_stock_at_server_prices() {
    let fixture = Fixture::new(&[]);
    let prices = stock_prices();
    let inventory = Inventory::load(&fixture.content, None).expect("fixture inventory loads");
    let mut gateway = fixture.connect(fixture.state());
    let replies = fixture.open_shop(&mut gateway);

    let list = replies
        .iter()
        .find(|packet| packet.starts_with(&[165, 0, 10, 0]))
        .expect("the Shop choice sends the 165/10 coin merchant list");
    assert!(
        !replies
            .iter()
            .any(|packet| packet.starts_with(&[66, 0, 42, 0])),
        "a coin vendor must not open the 66/42 Station Cash window"
    );
    let group = decode_coin_merchant_list_165_10(list).expect("165/10 matches the client reader");

    // The record carries the merchant identity the client copies into 165/4 and 165/5. The
    // first field is the per-shop context; there is no time-left dword in this message.
    assert_eq!(group.fields[0], NOW as u32, "the record starts at byte 4");
    assert_eq!(
        u64::from(group.fields[3]) | (u64::from(group.fields[4]) << 32),
        ROOSEY,
        "the record merchant GUID is Roosey"
    );
    assert_eq!(group.entries.len(), STOCK.len(), "Roosey's six stock rows");
    let ids: Vec<i32> = group
        .entries
        .iter()
        .map(|entry| entry.item_id as i32)
        .collect();
    for id in STOCK {
        assert!(ids.contains(&id), "row {id} is missing: {ids:?}");
    }

    // The row's display data comes from the definition; the client reads it directly.
    for entry in &group.entries {
        let presentation = inventory
            .presentation(entry.item_id as i32)
            .expect("the stock row resolves an item definition");
        assert_eq!(entry.name_id, presentation.name_id as u32);
        assert_eq!(entry.description_id, presentation.description_id as u32);
        assert_eq!(entry.icon_id, presentation.icon_id as u32);
        assert_eq!(entry.tint_value, presentation.icon_tint as u32);
        assert_eq!(entry.quantity_available, 0, "unlimited server stock");
        assert!(!entry.members_only);
        assert!(entry.can_buy);
        assert_eq!(entry.available_tint_group_id, 0);
    }

    // The displayed coin price is the definition's coin purchase price. A row the login
    // catalogue did not carry, or whose loaded definition price differs from stores.json, is
    // pushed through the paired 35/37 batch.
    let mut updates = 0;
    for id in STOCK {
        let price = prices[&id];
        let loaded = inventory
            .definition_coin_price(id)
            .expect("the definition carries a coin price");
        let raw = inventory
            .definition_record(id)
            .expect("the row has a definition");
        assert_eq!(
            &raw[28..32],
            &loaded.to_le_bytes(),
            "loaded price wire offset"
        );
        let captured = inventory.definition_was_captured(id);
        if captured && loaded == price {
            continue;
        }
        updates += 1;
        let record = inventory
            .definition_record_with_coin_price(id, price)
            .expect("the definition can carry the corrected price");
        // Reader-derived pin: `008e3760` stores serialized dword 7 (bytes 28..32) at `+0x24`,
        // the column `00cff140` case 27 displays.
        assert_eq!(&record[28..32], &price.to_le_bytes(), "price wire offset");
        let batch = definition_batch(&replies)
            .unwrap_or_else(|| panic!("row {id} needs a 35/37 definition update"));
        assert!(
            batch.windows(record.len()).any(|window| window == record),
            "the 35/37 batch does not carry item {id} at {price} coins"
        );
    }
    if updates == 0 {
        assert!(
            definition_batch(&replies).is_none(),
            "no definition needs an update, so no 35/37 batch should be sent"
        );
    }

    // Buy the 75-coin ring through the native 165/4 field order (`00c77230` -> the serializer
    // `00c75ed0`): merchant u64, merchant-record context, definition id, tint, then quantity.
    // Every buy from one open shop carries the same context, so buying the ring again is a
    // second purchase, not a retry.
    let merchant = u64::from(group.fields[3]) | (u64::from(group.fields[4]) << 32);
    let mut buy = vec![165, 0, 4, 0];
    buy.extend(merchant.to_le_bytes());
    buy.extend(group.fields[0].to_le_bytes());
    buy.extend(RING.to_le_bytes());
    buy.extend(0u32.to_le_bytes());
    buy.extend(1u32.to_le_bytes());
    for bought in 1..=2 {
        let outcome = gateway
            .handle_at(&wrap(&buy), NOW + 1 + u64::from(bought))
            .expect("the ring buy handles");
        assert!(outcome.gameplay_changed, "a successful buy requests a save");
        let done = inner_packets(&outcome);
        let completion = coin_completion(&done);
        assert_eq!(word(completion, 4), 1, "the 165/6 result is success");
        assert_eq!(word(completion, 12), 1, "kind 1 = buy");
        assert_eq!(word(completion, 44), 1, "quantity");
        assert_eq!(word(completion, 48), RING_PRICE, "the server unit price");
        let after = inventory_of(&gateway);
        assert_eq!(
            after.coins,
            1_000 - RING_PRICE * bought,
            "server price, not a client value"
        );
        assert_eq!(count_definition(&after, RING), bought);
    }

    // A refused row changes nothing and leaves the open shop usable.
    let before = gateway.snapshot();
    let mut refused = vec![165, 0, 4, 0];
    refused.extend(merchant.to_le_bytes());
    refused.extend(group.fields[0].to_le_bytes());
    refused.extend(999_999i32.to_le_bytes());
    refused.extend(0u32.to_le_bytes());
    refused.extend(1u32.to_le_bytes());
    let refused = gateway
        .handle_at(&wrap(&refused), NOW + 4)
        .expect("the session survives an unknown item");
    let refused = inner_packets(&refused);
    assert!(
        !refused
            .iter()
            .any(|packet| packet.starts_with(&[165, 0, 6, 0])),
        "a non-stock item must not produce a purchase completion"
    );
    assert_eq!(gateway.snapshot(), before, "a refused buy changed state");
}

